class EmailNotification:
    def __init__(self, address, body):
        self.address = address
        self.body = body

    def format_message(self):
        return "Subject " + self.body


class TextMessageNotification:
    def __init__(self, address, body):
        self.address = address
        self.body = body

    def format_message(self):
        return self.body[:10]


class PushNotification:
    def __init__(self, address, body):
        self.address = address
        self.body = body

    def format_message(self):
        return "[" + self.body + "]"


class VoiceCallNotification:
    def __init__(self, address, body):
        self.address = address
        self.body = body

    def format_message(self):
        return "Warning Message " + self.body


class RoutingTable:
    def __init__(self):
        self.handlers = {
            "email": EmailNotification,
            "sms": TextMessageNotification,
            "text": TextMessageNotification,
            "push": PushNotification,
            "voice": VoiceCallNotification,
        }

    def build(self, kind, address, body):
        handler = self.handlers.get(kind)
        if handler is None:
            raise ValueError("unknown destination type: %r" % (kind,))
        return handler(address, body)


class DeliveryReport:
    def __init__(self, entries):
        self.entries = entries

    def render(self):
        lines = []
        for address, text in self.entries:
            lines.append("%-10s -> %s" % (address, text))
        return "\n".join(lines)


def route(messages):
    table = RoutingTable()
    formatted = []
    for kind, address, body in messages:
        notification = table.build(kind, address, body)
        formatted.append(notification.format_message())
    return formatted


def build_report(messages):
    texts = route(messages)
    addresses = [address for _kind, address, _body in messages]
    report = DeliveryReport(list(zip(addresses, texts)))
    return report.render()


def main():
    messages = [
        ("email", "admin", "System down"),
        ("sms", "555-0100", "Disk usage is critical"),
        ("push", "device-77", "New login detected"),
        ("voice", "555-0199", "Reactor overheating"),
    ]
    print(route(messages))
    print(build_report(messages))


if __name__ == "__main__":
    main()

