class MeleeAttack:
    label = "melee attack"

    def execute(self, health):
        return health - 10


class RangedAttack:
    label = "ranged attack"

    def execute(self, health):
        return health - 5


class HealingSpell:
    label = "healing spell"

    def execute(self, health):
        return health + 20


class DefensiveBlock:
    label = "defensive block"

    def execute(self, health):
        return health + 15


class ActionParser:
    """Turns raw action strings into executable action objects."""

    factories = {
        "melee": MeleeAttack,
        "ranged": RangedAttack,
        "heal": HealingSpell,
        "block": DefensiveBlock,
    }

    def parse(self, text):
        key = text.strip().lower()
        if key not in self.factories:
            raise ValueError("unknown combat action: %r" % text)
        return self.factories[key]()


class CombatLog:
    def __init__(self, start_health):
        self.start_health = start_health
        self.entries = []

    def record(self, action, before, after):
        self.entries.append((action.label, before, after))

    def lines(self):
        for label, before, after in self.entries:
            yield "%-16s %3d -> %3d" % (label, before, after)


class BattleReport:
    def __init__(self, log, final_health):
        self.log = log
        self.final_health = final_health

    def render(self):
        rows = ["starting health: %d" % self.log.start_health]
        rows.extend(self.log.lines())
        rows.append("final health: %d" % self.final_health)
        return "\n".join(rows)


def combat(actions):
    health = 100
    parser = ActionParser()
    for text in actions:
        action = parser.parse(text)
        health = action.execute(health)
    return health


def combat_report(actions):
    health = 100
    parser = ActionParser()
    log = CombatLog(health)
    for text in actions:
        action = parser.parse(text)
        before = health
        health = action.execute(health)
        log.record(action, before, health)
    report = BattleReport(log, health)
    return report.render()


def main():
    script = ["ranged", "block", "melee", "heal"]
    print(combat_report(script))
    print("combat() ->", combat(script))


if __name__ == "__main__":
    main()

