class reading_report:
    """Pairs each original reading with its processed value for printing."""

    def __init__(self, readings):
        self.readings = [sensor_reading.from_tuple(entry) for entry in readings]
        self.values = sensors(readings)

    def lines(self):
        registry = sensor_registry()
        for reading, value in zip(self.readings, self.values):
            unit = registry.build(reading).unit
            yield "%-12s %-8s %s %s" % (reading.kind, reading.location, value, unit)


