class VideoFile:
    """A video file described by its title and its resolution."""

    def __init__(self, title, resolution):
        self.title = title
        self.resolution = resolution

    def display(self):
        return "{0} {1}".format(self.title, self.resolution)


class AudioTrack:
    """An audio track described by its title and its artist."""

    def __init__(self, title, artist):
        self.title = title
        self.artist = artist

    def display(self):
        return "{0} {1}".format(self.title, self.artist)


class PodcastEpisode:
    """A podcast episode described by its show name and its episode number."""

    def __init__(self, show, episode):
        self.show = show
        self.episode = episode

    def display(self):
        return "{0} {1}".format(self.show, self.episode)


class ImageFile:
    """An image file described by its title and its dimensions."""

    def __init__(self, title, dimensions):
        self.title = title
        self.dimensions = dimensions

    def display(self):
        return "{0} {1}".format(self.title, self.dimensions)


class MediaTypeError(ValueError):
    """Raised when an entry names a media type that has no matching class."""


class PlaylistReport:
    """Numbered listing of the formatted entries plus a per-type tally."""

    def __init__(self, kinds, lines):
        self.kinds = kinds
        self.lines = lines

    def render(self):
        rows = ["{0}. {1}".format(n, text) for n, text in enumerate(self.lines, 1)]
        tally = []
        for kind in sorted(set(self.kinds)):
            tally.append("{0}={1}".format(kind, self.kinds.count(kind)))
        rows.append("totals: " + ", ".join(tally))
        return "\n".join(rows)


def build_media(kind, first, second):
    if kind == "video":
        return VideoFile(first, second)
    if kind == "audio":
        return AudioTrack(first, second)
    if kind == "podcast":
        return PodcastEpisode(first, second)
    if kind == "image":
        return ImageFile(first, second)
    raise MediaTypeError("unsupported media type: {0!r}".format(kind))


def playlist(items):
    displays = []
    for entry in items:
        kind, first, second = entry
        displays.append(build_media(kind, first, second).display())
    return displays


def main():
    items = [
        ("video", "Intro", "1080p"),
        ("audio", "Sunrise", "Ada Lane"),
        ("podcast", "Deep Code", "42"),
        ("image", "Cover", "800x600"),
    ]
    lines = playlist(items)
    report = PlaylistReport([entry[0] for entry in items], lines)
    print(report.render())


if __name__ == "__main__":
    main()

