class CargoItem:
    """A single cargo entry parsed from a (method, distance, weight) tuple."""

    def __init__(self, method, distance, weight):
        self.method = str(method).strip().lower()
        self.distance = float(distance)
        self.weight = float(weight)
        if self.distance < 0 or self.weight < 0:
            raise ValueError("distance and weight must be non-negative")


class AirCargoShipment:
    def __init__(self, item):
        self.item = item

    def cost(self):
        return 10.0 * self.item.weight + self.item.distance


class SeaFreightShipment:
    def __init__(self, item):
        self.item = item

    def cost(self):
        return self.item.weight + 0.5 * self.item.distance


class RailTransportShipment:
    def __init__(self, item):
        self.item = item

    def cost(self):
        return 2.0 * self.item.weight + self.item.distance


class RoadTruckShipment:
    def __init__(self, item):
        self.item = item

    def cost(self):
        return 5.0 * self.item.weight + 2.0 * self.item.distance


SHIPMENT_TYPES = {
    "air": AirCargoShipment,
    "sea": SeaFreightShipment,
    "rail": RailTransportShipment,
    "road": RoadTruckShipment,
}


def build_shipment(entry):
    method, distance, weight = entry
    item = CargoItem(method, distance, weight)
    try:
        shipment_class = SHIPMENT_TYPES[item.method]
    except KeyError:
        raise ValueError("unknown transport method: %r" % method)
    return shipment_class(item)


def freight(cargo):
    """Total estimated shipping cost for a list of cargo tuples."""
    return sum(build_shipment(entry).cost() for entry in cargo)


class FreightReport:
    """Line-by-line breakdown of a cargo manifest plus its total."""

    def __init__(self, cargo):
        self.shipments = [build_shipment(entry) for entry in cargo]

    def lines(self):
        for shipment in self.shipments:
            item = shipment.item
            yield "%-5s %7.1f km %7.1f kg -> %10.2f" % (
                item.method, item.distance, item.weight, shipment.cost())
        yield "%-34s %10.2f" % ("TOTAL", sum(s.cost() for s in self.shipments))


def main():
    manifest = [("air", 100, 50), ("sea", 1000, 200),
                ("rail", 800, 120), ("road", 150, 60)]
    report = FreightReport(manifest)
    for line in report.lines():
        print(line)
    print("freight(example) =", freight([("air", 100, 50), ("sea", 1000, 200)]))


if __name__ == "__main__":
    main()

