class RegularFile:
    def __init__(self, size):
        self.size = size

    def space(self):
        return float(self.size)


class DirectoryFolder:
    OVERHEAD = 4096

    def __init__(self, size):
        self.declared_size = size

    def space(self):
        return float(self.OVERHEAD)


class SymbolicLink:
    LINK_SIZE = 64

    def __init__(self, size):
        self.declared_size = size

    def space(self):
        return float(self.LINK_SIZE)


class CompressedArchive:
    RATIO = 0.8

    def __init__(self, size):
        self.size = size

    def space(self):
        return self.size * self.RATIO


class NodeSpec:
    def __init__(self, kind, size):
        self.kind = kind
        self.size = size

    def as_tuple(self):
        return (self.kind, self.size)


class ReportRow:
    def __init__(self, kind, count, space):
        self.kind = kind
        self.count = count
        self.space = space

    def render(self):
        return "{:<8} x{:<4} {:>12.1f}".format(self.kind, self.count, self.space)


def build_node(kind, size):
    if kind == 'file':
        return RegularFile(size)
    if kind == 'folder':
        return DirectoryFolder(size)
    if kind == 'link':
        return SymbolicLink(size)
    if kind == 'archive':
        return CompressedArchive(size)
    raise ValueError("unknown node type: {!r}".format(kind))


def disk(nodes):
    total = 0.0
    for kind, size in nodes:
        total += build_node(kind, size).space()
    return float(total)


def parse_spec(text):
    kind, separator, raw_size = text.partition(':')
    if not separator:
        raise ValueError("expected 'kind:size', got {!r}".format(text))
    return NodeSpec(kind.strip(), int(raw_size))


def summarize(nodes):
    counts = {}
    spaces = {}
    for kind, size in nodes:
        counts[kind] = counts.get(kind, 0) + 1
        spaces[kind] = spaces.get(kind, 0.0) + build_node(kind, size).space()
    rows = []
    for kind in sorted(counts):
        rows.append(ReportRow(kind, counts[kind], spaces[kind]))
    return rows


def main(argv):
    import sys
    tokens = argv[1:] or sys.stdin.read().split()
    nodes = [parse_spec(token).as_tuple() for token in tokens]
    for row in summarize(nodes):
        print(row.render())
    print("total {:.1f}".format(disk(nodes)))


if __name__ == '__main__':
    import sys
    main(sys.argv)

