class IssueRecord:
    """A validated (type, severity, affected users) triple from the input list."""

    def __init__(self, kind, severity, affected_users):
        self.kind = str(kind).strip().lower()
        self.severity = int(severity)
        self.affected_users = int(affected_users)
        if self.severity < 0 or self.affected_users < 0:
            raise ValueError("severity and affected users must be non-negative")


class CrashBug:
    label = "crash bug"

    def __init__(self, record):
        self.record = record

    def priority_score(self):
        return self.record.severity * self.record.affected_users


class UserInterfaceGlitch:
    label = "UI glitch"

    def __init__(self, record):
        self.record = record

    def priority_score(self):
        return self.record.severity


class FeatureRequest:
    label = "feature request"

    def __init__(self, record):
        self.record = record

    def priority_score(self):
        return self.record.affected_users / 10 + self.record.severity


class SecurityVulnerability:
    label = "security vulnerability"

    def __init__(self, record):
        self.record = record

    def priority_score(self):
        return self.record.severity ** 2 + 1000


ISSUE_CLASSES = {
    "crash": CrashBug,
    "ui": UserInterfaceGlitch,
    "feature": FeatureRequest,
    "security": SecurityVulnerability,
}


def build_issue(entry):
    kind, severity, affected_users = entry
    record = IssueRecord(kind, severity, affected_users)
    if record.kind not in ISSUE_CLASSES:
        raise ValueError("unknown issue type: %s" % record.kind)
    return ISSUE_CLASSES[record.kind](record)


def triage(issues):
    return [build_issue(entry).priority_score() for entry in issues]


class TriageReport:
    """Renders scored issues sorted from most to least urgent."""

    def __init__(self, issues):
        self.rows = [(build_issue(entry), score)
                     for entry, score in zip(issues, triage(issues))]

    def render(self):
        ranked = sorted(self.rows, key=lambda row: row[1], reverse=True)
        return "\n".join("%-24s %8.1f" % (issue.label, score)
                         for issue, score in ranked)


def main():
    backlog = [
        ('crash', 5, 100),
        ('ui', 3, 50),
        ('feature', 2, 340),
        ('security', 7, 12),
    ]
    print(triage(backlog))
    report = TriageReport(backlog)
    print(report.render())


if __name__ == "__main__":
    main()

