class DayReading:
    """A validated raw observation for one day."""

    def __init__(self, condition, high, low):
        self.condition = str(condition).strip().lower()
        self.high = high
        self.low = low
        if self.high < self.low:
            raise ValueError(
                "high %r is below low %r for a %s day" % (high, low, self.condition)
            )

    def average(self):
        return (self.high + self.low) / 2

    def spread(self):
        return self.high - self.low


class SunnyDay:
    description = "clear skies"

    def __init__(self, reading):
        self.value = reading.high

    def summary(self):
        return "%s %s" % (self.description, self.value)


class RainyDay:
    description = "precipitation"

    def __init__(self, reading):
        self.value = reading.average()

    def summary(self):
        return "%s %s" % (self.description, self.value)


class SnowyDay:
    description = "freezing"

    def __init__(self, reading):
        self.value = reading.low

    def summary(self):
        return "%s %s" % (self.description, self.value)


class CloudyDay:
    description = "overcast"

    def __init__(self, reading):
        self.value = reading.spread()

    def summary(self):
        return "%s %s" % (self.description, self.value)


def build_condition(reading):
    """Pick and instantiate the class matching the reading's condition."""
    if reading.condition == "sunny":
        return SunnyDay(reading)
    if reading.condition == "rainy":
        return RainyDay(reading)
    if reading.condition == "snowy":
        return SnowyDay(reading)
    if reading.condition == "cloudy":
        return CloudyDay(reading)
    raise ValueError("unknown condition: %s" % reading.condition)


def forecast(days):
    summaries = []
    for condition, high, low in days:
        reading = DayReading(condition, high, low)
        summaries.append(build_condition(reading).summary())
    return summaries


class ForecastReport:
    """Renders a forecast as an aligned, human readable block of text."""

    def __init__(self, days):
        self.days = list(days)
        self.summaries = forecast(self.days)

    def lines(self):
        width = max(len(day[0]) for day in self.days)
        return [
            "%-*s  %3s/%-3s  %s" % (width, day[0], day[1], day[2], summary)
            for day, summary in zip(self.days, self.summaries)
        ]

    def render(self):
        return "\n".join(self.lines())


def main():
    week = [
        ("sunny", 30, 20),
        ("rainy", 20, 10),
        ("snowy", 1, -7),
        ("cloudy", 18, 11),
    ]
    print(forecast(week))
    report = ForecastReport(week)
    print(report.render())


if __name__ == "__main__":
    main()

