}


class RouteLeg:
    def __init__(self, mode, distance, minutes):
        self.mode = mode
        self.distance = distance
        self.minutes = minutes

    def describe(self):
        return "%-14s %5.1f km %6.1f min" % (self.mode, self.distance, self.minutes)


class RouteSummary:
    def __init__(self, legs):
        self.legs = legs

    def total(self):
        return sum(leg.minutes for leg in self.legs)

    def report(self):
