class LockedDoor:
    """A door whose lock takes twice the difficulty in seconds to pick."""

    def __init__(self, difficulty):
        self.difficulty = difficulty

    def seconds(self):
        return 2 * self.difficulty


class FloorSwitch:
    """A pressure plate that always needs the same ten seconds."""

    def __init__(self, difficulty):
        self.difficulty = difficulty

    def seconds(self):
        return 10


class HiddenClue:
    """A coded note needing the square of its difficulty to decipher."""

    def __init__(self, difficulty):
        self.difficulty = difficulty

    def seconds(self):
        return self.difficulty ** 2


class LaserGrid:
    """A beam pattern that grows faster to cross as difficulty rises."""

    def __init__(self, difficulty):
        self.difficulty = difficulty

    def seconds(self):
        return 20 - self.difficulty


PUZZLE_TYPES = {
    "locked door": LockedDoor,
    "floor switch": FloorSwitch,
    "hidden clue": HiddenClue,
    "laser grid": LaserGrid,
}


class PuzzleStep:
    """One interaction tuple, resolved to a concrete puzzle object."""

    def __init__(self, object_type, difficulty):
        key = str(object_type).strip().lower()
        if key not in PUZZLE_TYPES:
            raise ValueError("unknown puzzle type: %r" % (object_type,))
        if not isinstance(difficulty, int) or isinstance(difficulty, bool):
            raise TypeError("difficulty must be an integer: %r" % (difficulty,))
        self.name = key
        self.difficulty = difficulty
        self.puzzle = PUZZLE_TYPES[key](difficulty)

    def seconds(self):
        return self.puzzle.seconds()


class EscapeReport:
    """Collects per-step timings and renders a short summary."""

    def __init__(self):
        self.rows = []

    def add(self, step, cost):
        self.rows.append((step.name, step.difficulty, cost))

    def render(self):
        lines = ["%-13s d=%-3d %4d s" % row for row in self.rows]
        lines.append("total: %d s" % sum(row[2] for row in self.rows))
        return "\n".join(lines)


def solve(steps):
    total = 0
    for object_type, difficulty in steps:
        step = PuzzleStep(object_type, difficulty)
        total += step.seconds()
    return total


def describe_escape(steps):
    report = EscapeReport()
    for object_type, difficulty in steps:
        step = PuzzleStep(object_type, difficulty)
        report.add(step, step.seconds())
    return report.render()


def main():
    route = [("locked door", 3), ("hidden clue", 4)]
    print(describe_escape(route))
    print("solve() ->", solve(route))


if __name__ == "__main__":
    main()

