class WeldingRobot:
    """Consumes 15 energy units per duration unit plus a 50 unit start-up base."""

    def energy(self, duration):
        return 50 + 15 * duration


class PaintingStation:
    """Consumes 5 energy units per duration unit."""

    def energy(self, duration):
        return 5 * duration


class QualityScanner:
    """Consumes a flat 20 energy units, whatever the duration."""

    def energy(self, duration):
        return 20


class PackagingBelt:
    """Consumes 2 energy units per duration unit plus a 10 unit base."""

    def energy(self, duration):
        return 10 + 2 * duration


class ProductionStep:
    def __init__(self, operation, duration):
        if not isinstance(duration, int) or isinstance(duration, bool):
            raise TypeError("duration must be an integer: %r" % (duration,))
        if duration < 0:
            raise ValueError("duration must not be negative: %d" % duration)
        self.operation = str(operation).strip().lower()
        self.duration = duration


class EnergyReport:
    def __init__(self):
        self.entries = []

    def record(self, step, cost):
        self.entries.append((step.operation, step.duration, cost))

    @property
    def total(self):
        return sum(cost for _, _, cost in self.entries)

    def render(self):
        lines = ["%-16s %4d %6d" % entry for entry in self.entries]
        lines.append("%-16s %4s %6d" % ("TOTAL", "", self.total))
        return "\n".join(lines)


def build_machines():
    welder = WeldingRobot()
    painter = PaintingStation()
    scanner = QualityScanner()
    belt = PackagingBelt()
    return {
        "welding robot": welder,
        "painting station": painter,
        "quality scanner": scanner,
        "packaging belt": belt,
    }


def evaluate(tasks):
    machines = build_machines()
    report = EnergyReport()
    for operation, duration in tasks:
        step = ProductionStep(operation, duration)
        machine = machines.get(step.operation)
        if machine is None:
            raise KeyError("unknown operation: %s" % step.operation)
        report.record(step, machine.energy(step.duration))
    return report


def manufacture(tasks):
    return evaluate(tasks).total


def main():
    batch = [
        ("painting station", 10),
        ("quality scanner", 5),
        ("welding robot", 4),
        ("packaging belt", 12),
    ]
    print(evaluate(batch).render())
    print("simple job:", manufacture([("painting station", 10), ("quality scanner", 5)]))


if __name__ == "__main__":
    main()

