class RollerCoasterRide:
    label = "Roller Coaster"

    def thrill_points(self, age):
        return 50 if age > 12 else 0


class WaterFlumeRide:
    label = "Water Flume"

    def thrill_points(self, age):
        return 20


class HauntedHouseRide:
    label = "Haunted House"

    def thrill_points(self, age):
        return 30 - (10 if age < 10 else 0)


class GentleCarouselRide:
    label = "Gentle Carousel"

    def thrill_points(self, age):
        return 10


RIDE_REGISTRY = {
    "roller coaster": RollerCoasterRide,
    "water flume": WaterFlumeRide,
    "haunted house": HauntedHouseRide,
    "gentle carousel": GentleCarouselRide,
}


class GuestEntry:
    def __init__(self, ride, age):
        key = str(ride).strip().lower()
        if key not in RIDE_REGISTRY:
            raise ValueError("unknown ride type: %r" % (ride,))
        if not isinstance(age, int) or isinstance(age, bool) or age < 0:
            raise ValueError("invalid rider age: %r" % (age,))
        self.ride = key
        self.age = age

    def score(self):
        attraction = RIDE_REGISTRY[self.ride]()
        return attraction.label, attraction.thrill_points(self.age)


def admit(guests):
    total = 0
    for ride, age in guests:
        entry = GuestEntry(ride, age)
        total += entry.score()[1]
    return total


class ThrillReport:
    def __init__(self):
        self.rows = []

    def add(self, label, age, points):
        self.rows.append((label, age, points))

    def render(self):
        lines = ["%-16s age %3d -> %3d pts" % row for row in self.rows]
        lines.append("%-16s %9s    %3d pts" % ("TOTAL", "", sum(r[2] for r in self.rows)))
        return "\n".join(lines)


def build_report(guests):
    report = ThrillReport()
    for ride, age in guests:
        entry = GuestEntry(ride, age)
        label, points = entry.score()
        report.add(label, entry.age, points)
    return report.render()


def main():
    guests = [
        ("roller coaster", 14),
        ("haunted house", 8),
        ("water flume", 30),
        ("gentle carousel", 5),
    ]
    print(build_report(guests))
    print("admit() =", admit(guests[:2]))


if __name__ == "__main__":
