class CommercialStorefront:
    label = "commercial storefront"

    def annual_tax(self, value):
        return value * 0.03 + 500.0


class VacantLot:
    label = "vacant lot"

    def annual_tax(self, value):
        return value * 0.005


class IndustrialWarehouse:
    label = "industrial warehouse"

    def annual_tax(self, value):
        return value * 0.02


def build_registry():
    apartment = ResidentialApartment()
    storefront = CommercialStorefront()
    lot = VacantLot()
    warehouse = IndustrialWarehouse()
    return {model.label: model for model in (apartment, storefront, lot, warehouse)}


class PropertyParcel:
    def __init__(self, kind, value):
        self.kind = str(kind).strip().lower().replace("_", " ")
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("base value for %r must be numeric" % self.kind)
        if value < 0:
            raise ValueError("base value for %r must not be negative" % self.kind)
        self.value = float(value)


def parse_parcels(properties):
    entries = properties.items() if isinstance(properties, dict) else properties
    return [PropertyParcel(kind, value) for kind, value in entries]


class TaxLineItem:
    def __init__(self, parcel, tax):
        self.parcel = parcel
        self.tax = tax

    def format(self):
        return "%-22s %12.2f %10.2f" % (self.parcel.kind, self.parcel.value, self.tax)


class TaxAssessment:
    def __init__(self, lines):
        self.lines = lines

    @property
    def total(self):
        return round(sum(line.tax for line in self.lines), 2)

    def report(self):
        rows = [line.format() for line in self.lines]
        rows.append("%-22s %12s %10.2f" % ("TOTAL", "", self.total))
        return "\n".join(rows)


def assess(properties):
    registry = build_registry()
    lines = []
    for parcel in parse_parcels(properties):
        model = registry.get(parcel.kind)
        if model is None:
            raise KeyError("unknown property type: %r" % parcel.kind)
        lines.append(TaxLineItem(parcel, model.annual_tax(parcel.value)))
    return TaxAssessment(lines)


def evaluate(properties):
    return assess(properties).total


def main():
    portfolio = [
        ("residential apartment", 100000),
        ("vacant lot", 50000),
        ("commercial storefront", 250000),
        ("industrial warehouse", 400000),
    ]
