import sys

CARD_HEADER = "{:<16}{:>7}{:>8}"


class ResourceCard:
    kind = "resource"

    def __init__(self, face_value):
        self.face_value = face_value

    def points(self):
        return 0


class DevelopmentCard:
    kind = "development"

    def __init__(self, face_value):
        self.face_value = face_value

    def points(self):
        return 1 + (1 if self.face_value > 5 else 0)


class VictoryPointCard:
    kind = "victory"

    def __init__(self, face_value):
        self.face_value = face_value

    def points(self):
        return self.face_value


class PenaltyCard:
    kind = "penalty"

    def __init__(self, face_value):
        self.face_value = face_value

    def points(self):
        return -2


CARD_TYPES = {
    "resource": ResourceCard,
    "development": DevelopmentCard,
    "victory": VictoryPointCard,
    "penalty": PenaltyCard,
}


class ScoreLine:
    def __init__(self, kind, face_value, points):
        self.kind = kind
        self.face_value = face_value
        self.points = points

    def render(self):
        return CARD_HEADER.format(self.kind, self.face_value, self.points)


class ScoreReport:
    def __init__(self, lines, total):
        self.lines = lines
        self.total = total

    def render(self):
        rows = [CARD_HEADER.format("CARD", "VALUE", "POINTS")]
        rows.extend(line.render() for line in self.lines)
        rows.append(CARD_HEADER.format("TOTAL", "", self.total))
        return "\n".join(rows)


def build_hand(cards):
    hand = []
    for card_type, face_value in cards:
        if card_type not in CARD_TYPES:
            raise ValueError("unknown card type: %r" % (card_type,))
        hand.append(CARD_TYPES[card_type](int(face_value)))
    return hand


def score(cards):
    return sum(card.points() for card in build_hand(cards))


def build_report(cards):
    hand = build_hand(cards)
    lines = [ScoreLine(card.kind, card.face_value, card.points()) for card in hand]
    return ScoreReport(lines, sum(line.points for line in lines))


def parse_card_argument(text):
    card_type, separator, value = text.partition(":")
    if not separator:
        raise ValueError("expected TYPE:VALUE, got %r" % (text,))
    return card_type.strip(), int(value)


def main(argv):
    if len(argv) < 2:
        print("usage: score.py TYPE:VALUE [TYPE:VALUE ...]")
        return 1
    cards = [parse_card_argument(item) for item in argv[1:]]
    print(build_report(cards).render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

