INITIAL_INTEGRITY = 1000


class StoneWall:
    """Halves incoming damage before it reaches the fortress."""

    label = "stone wall"

    def integrity_loss(self, damage):
        return damage / 2


class WoodenGate:
    """Takes the full hit, but shrugs off anything under 20 points."""

    label = "wooden gate"

    def integrity_loss(self, damage):
        if damage < 20:
            return 0
        return damage


class WaterMoat:
    """Swallows the damage, yet every assault still costs 10 points."""

    label = "water moat"

    def integrity_loss(self, damage):
        return 10


class MagicalBarrier:
    """Deflects the attack completely at a flat upkeep of 5 points."""

    label = "magical barrier"

    def integrity_loss(self, damage):
        return 5


class AttackRecord:
    def __init__(self, defense, damage):
        if damage < 0:
            raise ValueError("damage cannot be negative: %r" % (damage,))
        self.defense = str(defense).strip().lower()
        self.damage = damage


class DefenseRegistry:
    def __init__(self):
        wall = StoneWall()
        gate = WoodenGate()
        moat = WaterMoat()
        barrier = MagicalBarrier()
        self.structures = {s.label: s for s in (wall, gate, moat, barrier)}

    def resolve(self, record):
        try:
            return self.structures[record.defense]
        except KeyError:
            raise ValueError("unknown defense: %r" % (record.defense,))


class SiegeReport:
    def __init__(self, initial):
        self.initial = initial
        self.entries = []

    def add(self, structure, record, loss):
        self.entries.append((structure.label, record.damage, loss))

    def render(self, final):
        lines = ["siege report (starting integrity: %g)" % self.initial]
        for label, damage, loss in self.entries:
            lines.append("  %-16s hit for %-6g -> lost %g" % (label, damage, loss))
        lines.append("remaining integrity: %g" % final)
        return "\n".join(lines)


def resolve_siege(attacks, report=None):
    registry = DefenseRegistry()
    integrity = INITIAL_INTEGRITY
    for defense, damage in attacks:
        record = AttackRecord(defense, damage)
        structure = registry.resolve(record)
        loss = structure.integrity_loss(record.damage)
        integrity -= loss
        if report is not None:
            report.add(structure, record, loss)
    return integrity


def defend(attacks):
    return resolve_siege(attacks)


def main():
    siege = [("stone wall", 50), ("magical barrier", 100), ("wooden gate", 15),
             ("water moat", 300), ("wooden gate", 80)]
    report = SiegeReport(INITIAL_INTEGRITY)
    final = resolve_siege(siege, report)
    print(report.render(final))
    print("defend() result:", defend([("stone wall", 50), ("magical barrier", 100)]))


if __name__ == "__main__":
    main()

