    def __init__(self, base_weight):
        self.base_weight = base_weight

    def batch_weight(self):
        return self.base_weight * self.factor

class LiquidExtract:
    factor = 2.0

    def __init__(self, base_weight):
        self.base_weight = base_weight

    def batch_weight(self):
        return self.base_weight * self.factor

class FreshGarnish:
    factor = 1.0

    def __init__(self, base_weight):
        self.base_weight = base_weight

    def batch_weight(self):
        return self.base_weight * self.factor

class StickySyrup:
    factor = 1.5

    def __init__(self, base_weight):
        self.base_weight = base_weight

    def batch_weight(self):
        return self.base_weight * self.factor

CLASSIFICATION_MAP = {
    "dry powder": DryPowder,
    "liquid extract": LiquidExtract,
    "fresh garnish": FreshGarnish,
    "sticky syrup": StickySyrup,
}

class BatchRecipe:
    def __init__(self, ingredients):
        self.names = [str(pair[0]).strip().lower() for pair in ingredients]
        self.components = [build_component(*pair) for pair in ingredients]

    def total_weight(self):
        return sum(component.batch_weight() for component in self.components)

    def report(self):
        lines = []
        for name, component in zip(self.names, self.components):
            lines.append("%-15s %7.1f g -> %7.1f g" % (
                name, component.base_weight, component.batch_weight()))
        lines.append("%-15s %7s    %7.1f g" % ("TOTAL", "", self.total_weight()))
        return "\n".join(lines)

def build_component(classification, base_weight):
    key = str(classification).strip().lower()
    if key not in CLASSIFICATION_MAP:
        raise ValueError("unknown ingredient classification: %r" % (classification,))
    if base_weight < 0:
        raise ValueError("base weight must not be negative: %r" % (base_weight,))
    return CLASSIFICATION_MAP[key](float(base_weight))

def scale(ingredients):
    total = BatchRecipe(ingredients).total_weight()
    return int(total) if total == int(total) else total

def main():
    recipe = [("dry powder", 100), ("fresh garnish", 50),
              ("liquid extract", 80), ("sticky syrup", 40)]
    print(BatchRecipe(recipe).report())
    print("batch total:", scale(recipe), "grams")

if __name__ == "__main__":
    main()

