class VolatileHerb:
    """Unstable plant matter: its mana is doubled."""

    def potency(self, mana):
        return mana * 2


class CrystalDust:
    """Ground crystal: contributes its mana plus a flat bonus."""

    def potency(self, mana):
        return mana + 5


class MonsterEssence:
    """Tripled mana, penalised by its own toxicity."""

    def potency(self, mana):
        return mana * 3 - 10


class PureWater:
    """Inert filler: always exactly one point of potency."""

    def potency(self, mana):
        return 1


class UnknownComponentError(ValueError):
    pass


class IngredientEntry:
    def __init__(self, name, mana):
        self.name = name
        self.mana = mana


class BrewReport:
    def __init__(self, contributions, total):
        self.contributions = contributions
        self.total = total

    def lines(self):
        for entry, value in self.contributions:
            yield "{:<16} mana {:>3} -> {:>4}".format(entry.name, entry.mana, value)
        yield "{:<16} {:>12}".format("final potency", self.total)


def component_table():
    return {
        "volatile herb": VolatileHerb(),
        "crystal dust": CrystalDust(),
        "monster essence": MonsterEssence(),
        "pure water": PureWater(),
    }


def parse_entry(item):
    name, mana = item
    return IngredientEntry(str(name).strip().lower(), int(mana))


def summarize(ingredients):
    table = component_table()
    contributions = []
    total = 0
    for item in ingredients:
        entry = parse_entry(item)
        component = table.get(entry.name)
        if component is None:
            raise UnknownComponentError("unknown component: " + entry.name)
        value = component.potency(entry.mana)
        contributions.append((entry, value))
        total += value
    return BrewReport(contributions, int(total))


def brew(ingredients):
    return summarize(ingredients).total


def main():
    recipe = [("volatile herb", 3), ("pure water", 4)]
    for line in summarize(recipe).lines():
        print(line)
    print(brew([("crystal dust", 2), ("monster essence", 5), ("pure water", 9)]))


if __name__ == "__main__":
    main()

