            raise ValueError("bag weight must be positive")
        self.weight = weight

    def is_heavy(self, threshold):
        return self.weight >= threshold


class loyalty_tier:
    def __init__(self, name):
        self.name = str(name).strip().lower()

    def is_elite(self):
        return self.name == "elite"


class baggage_policy:
    def __init__(self, heavy_threshold=20.0, light_fee=50, heavy_fee=100):
        self.heavy_threshold = heavy_threshold
        self.light_fee = light_fee
        self.heavy_fee = heavy_fee

    def fee_for(self, bag):
        if bag.is_heavy(self.heavy_threshold):
            return self.heavy_fee
        return self.light_fee

    def free_allowance(self, tier):
        return 1 if tier.is_elite() else 0


class passenger_profile:
    def __init__(self, name, tier, bag_weights):
        self.name = name
        self.tier = loyalty_tier(tier)
        self.bag_weights = list(bag_weights)

    def checked_bags(self):
        return [checked_bag(weight) for weight in self.bag_weights]

    def total_fee(self, policy):
        fees = sorted((policy.fee_for(bag) for bag in self.checked_bags()), reverse=True)
        waived = policy.free_allowance(self.tier)
        return sum(fees[waived:])


class fee_statement:
    def __init__(self, name, total):
        self.name = name
        self.total = total

    def as_tuple(self):
        return (self.name, self.total)

    def as_line(self):
        return "{:<10} ${:>5}".format(self.name, self.total)


def build_statements(passengers, policy):
    statements = []
    for name, tier, weights in passengers:
        profile = passenger_profile(name, tier, weights)
        statements.append(fee_statement(name, profile.total_fee(policy)))
    return statements


def calculate(passengers):
    policy = baggage_policy()
    return [statement.as_tuple() for statement in build_statements(passengers, policy)]


def main():
    passengers = [
        ("Alice", "basic", [15, 25]),
        ("Bob", "elite", [18, 22, 30]),
        ("Cara", "elite", [12]),
    ]
    statements = build_statements(passengers, baggage_policy())
    for statement in statements:
        print(statement.as_line())
    print("{:<10} ${:>5}".format("TOTAL", sum(s.total for s in statements)))


if __name__ == "__main__":
    main()

