class PriorityRule:
    """Thresholds that turn raw symptom scores into a risk level."""

    def __init__(self, high_score=8, medium_score=5, senior_age=65):
        self.high_score = high_score
        self.medium_score = medium_score
        self.senior_age = senior_age

    def risk_for(self, scores):
        peak = max(scores) if scores else 0
        if peak > self.high_score:
            return "high"
        if peak > self.medium_score:
            return "medium"
        return "low"

    def is_senior(self, age):
        return age > self.senior_age


class VitalSignReading:
    """A single set of symptom severity scores for one patient."""

    def __init__(self, scores, rule):
        self.scores = [float(score) for score in scores]
        self.rule = rule

    @property
    def peak(self):
        return max(self.scores) if self.scores else 0.0

    @property
    def risk_level(self):
        return self.rule.risk_for(self.scores)


class PatientRecord:
    def __init__(self, name, age, reading):
        self.name = name
        self.age = int(age)
        self.reading = reading

    def priority(self):
        risk = self.reading.risk_level
        if risk == "high":
            return 0 if self.reading.rule.is_senior(self.age) else 1
        return 2 if risk == "medium" else 3


class TriageQueue:
    def __init__(self):
        self.records = []

    def add(self, record):
        self.records.append(record)

    def ordered(self):
        return sorted(self.records, key=lambda r: (r.priority(), -r.reading.peak, r.name))

    def names(self):
        return [record.name for record in self.ordered()]


class TriageReport:
    def __init__(self, queue):
        self.queue = queue

    def lines(self):
        rows = ["{:<14}{:>5}  {:<8}{:>6}".format("NAME", "AGE", "RISK", "PEAK")]
        for record in self.queue.ordered():
            rows.append("{:<14}{:>5}  {:<8}{:>6.1f}".format(
                record.name, record.age, record.reading.risk_level, record.reading.peak))
        return rows


def build_queue(patients, rule=None):
    rule = rule if rule is not None else PriorityRule()
    queue = TriageQueue()
    for name, age, scores in patients:
        reading = VitalSignReading(scores, rule)
        record = PatientRecord(name, age, reading)
        queue.add(record)
    return queue


def triage(patients):
    return build_queue(patients).names()


def main():
    patients = [
        ("Ada Young", 24, [1, 2, 3]),
        ("Walter Senior", 78, [4, 9, 2]),
        ("Mina Cole", 41, [6, 5]),
        ("Omar Reyes", 70, [7, 7, 5]),
    ]
    print(triage(patients))
    report = TriageReport(build_queue(patients))
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

