INTERVALS = {"van": 10000, "sedan": 15000}


class VehicleRecord:
    """A validated (plate, type, mileage) triple taken from the input list."""

    def __init__(self, plate, vehicle_type, mileage):
        if not str(plate).strip():
            raise ValueError("license plate must not be empty")
        if mileage < 0:
            raise ValueError("mileage must not be negative for plate %s" % plate)
        self.plate = str(plate).strip().upper()
        self.vehicle_type = str(vehicle_type).strip().lower()
        self.mileage = int(mileage)

    @classmethod
    def from_tuple(cls, row):
        plate, vehicle_type, mileage = row
        return cls(plate, vehicle_type, mileage)


class ServiceLog:
    """Keeps the odometer reading and the mileage at which service last happened."""

    def __init__(self, last_service_mileage=0):
        self.last_service_mileage = last_service_mileage
        self.current_mileage = last_service_mileage

    def record_mileage(self, mileage):
        if mileage < self.current_mileage:
            raise ValueError("odometer cannot decrease")
        self.current_mileage = mileage

    def mileage_since_service(self):
        return self.current_mileage - self.last_service_mileage


class MaintenanceSchedule:
    """Knows how many miles a vehicle type may run between services."""

    def __init__(self, vehicle_type):
        if vehicle_type not in INTERVALS:
            raise ValueError("unknown vehicle type: %s" % vehicle_type)
        self.vehicle_type = vehicle_type
        self.interval = INTERVALS[vehicle_type]

    def is_due(self, miles_driven):
        return miles_driven >= self.interval

    def miles_remaining(self, miles_driven):
        return max(0, self.interval - miles_driven)


class DeliveryTruck:
    """A fleet vehicle: its service log combined with its maintenance schedule."""

    def __init__(self, record):
        self.record = record
        self.schedule = MaintenanceSchedule(record.vehicle_type)
        self.log = ServiceLog()
        self.log.record_mileage(record.mileage)

    def needs_service(self):
        return self.schedule.is_due(self.log.mileage_since_service())

    def miles_until_service(self):
        return self.schedule.miles_remaining(self.log.mileage_since_service())


class FleetReport:
    """Renders one human-readable line per vehicle in the fleet."""

    def __init__(self, trucks):
        self.trucks = trucks

    def lines(self):
        out = []
        for truck in self.trucks:
            if truck.needs_service():
                status = "DUE NOW"
            else:
                status = "in %d miles" % truck.miles_until_service()
            out.append("%-8s %-6s %7d  %s" % (truck.record.plate,
                                              truck.record.vehicle_type,
                                              truck.log.current_mileage,
                                              status))
        return out


def build_fleet(vehicles):
    trucks = []
    for row in vehicles:
        record = VehicleRecord.from_tuple(row)
        trucks.append(DeliveryTruck(record))
    return trucks


def check(vehicles):
    return [t.record.plate for t in build_fleet(vehicles) if t.needs_service()]


def main():
    fleet = [("VAN-114", "van", 12000), ("SED-902", "sedan", 9500),
             ("VAN-220", "van", 4300), ("SED-777", "sedan", 15000)]
    report = FleetReport(build_fleet(fleet))
    for line in report.lines():
        print(line)
    print("Needs maintenance:", check(fleet))


if __name__ == "__main__":
    main()

