        self.movie_format = key
        self.base_price = FORMAT_PRICES[key]

    def price_for(self, patron):
        return max(0.0, self.base_price - patron.discount())


class ConcessionDiscount:
    """Grants free popcorn once the paid ticket price clears the threshold."""

    def __init__(self, threshold=18.0):
        self.threshold = threshold

    def grants_popcorn(self, price):
        return price > self.threshold


class PatronRecord:
    """A validated (patron, ticket) pair built from one raw input tuple."""

    def __init__(self, patron, ticket):
        self.patron = patron
        self.ticket = ticket

    @classmethod
    def from_tuple(cls, raw):
