CAPACITIES = {"produce": 50, "dry goods": 100}


class GroceryItem:
    def __init__(self, name, category):
        self.name = name
        self.category = category

    def capacity(self):
        return CAPACITIES[self.category]


class DeliveryRecord:
    def __init__(self, name, category, quantity):
        self.name = name
        self.category = category
        self.quantity = quantity

    @classmethod
    def from_tuple(cls, entry):
        name, category, quantity = entry
        key = str(category).strip().lower()
        if key not in CAPACITIES:
            raise ValueError("unknown category: %s" % category)
        if int(quantity) < 0:
            raise ValueError("negative quantity for %s" % name)
        return cls(str(name).strip(), key, int(quantity))

    def as_item(self):
        return GroceryItem(self.name, self.category)


class StoreShelf:
    def __init__(self, item):
        self.item = item
        self.stocked = 0

    def add(self, quantity):
        room = self.item.capacity() - self.stocked
        placed = min(room, quantity)
        self.stocked += placed
        return quantity - placed


class InventoryManager:
    def __init__(self):
        self.shelves = {}

    def receive(self, record):
        shelf = self.shelves.get(record.name)
        if shelf is None:
            shelf = StoreShelf(record.as_item())
            self.shelves[record.name] = shelf
        return shelf.add(record.quantity)


class StockReport:
    def __init__(self, manager, overflows):
        self.manager = manager
        self.overflows = dict(overflows)

    def lines(self):
        out = []
        for name, shelf in sorted(self.manager.shelves.items()):
            spare = self.overflows.get(name, 0)
            out.append("%-10s %-10s shelf %3d/%3d overflow %3d"
                       % (name, shelf.item.category, shelf.stocked,
                          shelf.item.capacity(), spare))
        return out


def restock(deliveries):
    manager = InventoryManager()
    overflows = []
    for entry in deliveries:
        record = DeliveryRecord.from_tuple(entry)
        extra = manager.receive(record)
        if extra > 0:
            overflows.append((record.name, extra))
    return overflows


def main():
    deliveries = [("apples", "produce", 60), ("rice", "dry goods", 80),
                  ("rice", "dry goods", 40), ("kale", "produce", 12)]
    overflows = restock(deliveries)
    manager = InventoryManager()
    for entry in deliveries:
        manager.receive(DeliveryRecord.from_tuple(entry))
    report = StockReport(manager, overflows)
    for line in report.lines():
        print(line)
    print("overflow totals:", overflows)


if __name__ == "__main__":
    main()

