TOUR_CAPACITY = 20


class VisitorGroup:
    def __init__(self, name, size, language):
        if not str(name).strip():
            raise ValueError("visitor group name must not be empty")
        if not isinstance(size, int) or size <= 0:
            raise ValueError("group size must be a positive integer: %r" % (size,))
        if size > TOUR_CAPACITY:
            raise ValueError("group %s of %d exceeds tour capacity" % (name, size))
        self.name = str(name).strip()
        self.size = size
        self.language = str(language).strip().capitalize()


class GuidedTour:
    def __init__(self, language, number):
        self.language = language
        self.number = number
        self.members = []

    @property
    def booked(self):
        return sum(group.size for group in self.members)

    def remaining(self):
        return TOUR_CAPACITY - self.booked

    def accepts(self, group):
        return group.language == self.language and group.size <= self.remaining()

    def admit(self, group):
        self.members.append(group)


class TourAssignment:
    def __init__(self, group, tour):
        self.group = group
        self.tour = tour

    def as_tuple(self):
        return (self.group.name, self.tour.language)


class MuseumGallery:
    def __init__(self):
        self.tours = []

    def tours_in(self, language):
        return [tour for tour in self.tours if tour.language == language]

    def assign(self, group):
        for tour in self.tours:
            if tour.accepts(group):
                tour.admit(group)
                return TourAssignment(group, tour)
        tour = GuidedTour(group.language, len(self.tours_in(group.language)) + 1)
        self.tours.append(tour)
        tour.admit(group)
        return TourAssignment(group, tour)


class ScheduleReport:
    def __init__(self, gallery):
        self.gallery = gallery

    def lines(self):
        for tour in self.gallery.tours:
            names = ", ".join(group.name for group in tour.members)
            yield "%s tour #%d (%d/%d): %s" % (
                tour.language, tour.number, tour.booked, TOUR_CAPACITY, names)


def build_gallery(groups):
    gallery = MuseumGallery()
    assignments = []
    for name, size, language in groups:
        group = VisitorGroup(name, size, language)
        assignments.append(gallery.assign(group))
    return gallery, assignments


def schedule(groups):
    _gallery, assignments = build_gallery(groups)
    return [assignment.as_tuple() for assignment in assignments]


def main():
    bookings = [
        ("Dupont Family", 5, "french"),
        ("Berlin School", 18, "german"),
        ("Lyon Choir", 14, "french"),
        ("Paris Cyclists", 6, "french"),
        ("Munich Seniors", 4, "german"),
    ]
    gallery, _assignments = build_gallery(bookings)
    report = ScheduleReport(gallery)
    for line in report.lines():
        print(line)
    print(schedule(bookings))


if __name__ == "__main__":
    main()

