class RoleThreshold:
    def __init__(self, role, minimum_score):
        self.role = role
        self.minimum_score = minimum_score

    def matches(self, role):
        return self.role == role.strip().lower()

    def grants(self, score):
        return score > self.minimum_score


class JobCandidate:
    def __init__(self, name, role, score):
        self.name = name.strip()
        self.role = role.strip().lower()
        self.score = float(score)


class InterviewPanel:
    def __init__(self, thresholds):
        self.thresholds = thresholds

    def threshold_for(self, role):
        for threshold in self.thresholds:
            if threshold.matches(role):
                return threshold
        return None

    def approves(self, candidate):
        threshold = self.threshold_for(candidate.role)
        if threshold is None:
            return False
        return threshold.grants(candidate.score)


class InterviewSlot:
    def __init__(self, position, candidate):
        self.position = position
        self.candidate = candidate

    def describe(self):
        return "%d. %s (%s, score %.1f)" % (
            self.position, self.candidate.name, self.candidate.role, self.candidate.score)


class HiringPipeline:
    def __init__(self, panel):
        self.panel = panel
        self.schedule = []

    def evaluate_all(self, records):
        for name, role, score in records:
            candidate = JobCandidate(name, role, score)
            if self.panel.approves(candidate):
                slot = InterviewSlot(len(self.schedule) + 1, candidate)
                self.schedule.append(slot)
        return self.schedule

    def shortlist(self):
        return [slot.candidate.name for slot in self.schedule]


def build_panel():
    engineering = RoleThreshold("engineering", 80)
    sales = RoleThreshold("sales", 70)
    return InterviewPanel([engineering, sales])


def assign(candidates):
    pipeline = HiringPipeline(build_panel())
    pipeline.evaluate_all(candidates)
    return pipeline.shortlist()


def main():
    applicants = [
        ("Ada Lovelace", "engineering", 85),
        ("Bob Stone", "engineering", 78),
        ("Cara Diaz", "sales", 72),
        ("Dan Poole", "sales", 65),
        ("Eve Nunes", "marketing", 95),
    ]
    print(assign(applicants))
    pipeline = HiringPipeline(build_panel())
    for slot in pipeline.evaluate_all(applicants):
        print(slot.describe())


if __name__ == "__main__":
    main()

