class FishTank:
    """A single tank holding one species of fish."""

    def __init__(self, identifier, species, population):
        if population < 0:
            raise ValueError("population of tank %r cannot be negative" % identifier)
        self.identifier = identifier
        self.species = species.strip().lower()
        self.population = population

    def __str__(self):
        return "%s: %d %s" % (self.identifier, self.population, self.species)


class DietRule:
    """Food units per fish for the species names it covers."""

    def __init__(self, species_names, units_per_fish):
        self.species_names = frozenset(species_names)
        self.units_per_fish = units_per_fish

    def matches(self, species):
        return species in self.species_names


class DailyDiet:
    """Food units required per fish, per day, resolved through diet rules."""

    def __init__(self, rules, default_units=1):
        self.rules = rules
        self.default_units = default_units

    def units_per_fish(self, species):
        for rule in self.rules:
            if rule.matches(species):
                return rule.units_per_fish
        return self.default_units

    def units_for(self, tank):
        return tank.population * self.units_per_fish(tank.species)


class FeedingSchedule:
    """Aggregates the tanks of the facility and totals their food demand."""

    def __init__(self, diet):
        self.diet = diet
        self.tanks = []

    def add_tank(self, tank):
        self.tanks.append(tank)

    def total_food_units(self):
        return sum(self.diet.units_for(tank) for tank in self.tanks)

    def breakdown(self):
        return [(tank, self.diet.units_for(tank)) for tank in self.tanks]


class ScheduleReport:
    """Renders a feeding schedule as human-readable lines."""

    def __init__(self, schedule):
        self.schedule = schedule

    def lines(self):
        rendered = []
        for tank, units in self.schedule.breakdown():
            rendered.append("%-30s %4d units" % (str(tank), units))
        rendered.append("%-30s %4d units" % ("FACILITY TOTAL", self.schedule.total_food_units()))
        return rendered


def build_schedule(tanks):
    diet = DailyDiet([DietRule(["shark", "sharks"], 2)], default_units=1)
    schedule = FeedingSchedule(diet)
    for identifier, species, population in tanks:
        schedule.add_tank(FishTank(identifier, species, population))
    return schedule


def plan(tanks):
    return build_schedule(tanks).total_food_units()


def main():
    facility = [("T1", "shark", 5), ("T2", "guppy", 10)]
    report = ScheduleReport(build_schedule(facility))
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

