PREMIUM_RATE = 30
BASIC_RATE = 15


class TentSite:
    def __init__(self, label, has_electricity):
        self.label = label
        self.has_electricity = has_electricity
        self.occupied = False

    def nightly_rate(self):
        return PREMIUM_RATE if self.has_electricity else BASIC_RATE

    def kind(self):
        return "premium" if self.has_electricity else "basic"


class NatureCamper:
    def __init__(self, name, preference):
        self.name = name
        self.preference = preference

    def prefers_premium(self):
        return self.preference == "premium"


class BookingRecord:
    def __init__(self, camper, site, nights):
        self.camper = camper
        self.site = site
        self.nights = nights

    def total_cost(self):
        return self.site.nightly_rate() * self.nights


class StayReceipt:
    def __init__(self, record):
        self.record = record

    def line(self):
        r = self.record
        return "{:<10} {:<8} {:>2} night(s) -> {:>4}".format(
            r.camper.name, r.site.kind(), r.nights, r.total_cost())


class BookingLedger:
    def __init__(self, premium_count, basic_count):
        self.sites = [TentSite("P%d" % i, True) for i in range(1, premium_count + 1)]
        self.sites += [TentSite("B%d" % i, False) for i in range(1, basic_count + 1)]
        self.records = []

    def _free_site(self, has_electricity):
        for site in self.sites:
            if site.has_electricity == has_electricity and not site.occupied:
                return site
        return None

    def assign(self, camper, nights):
        site = None
        if camper.prefers_premium():
            site = self._free_site(True)
        if site is None:
            site = self._free_site(False)
        if site is None:
            return None
        site.occupied = True
        record = BookingRecord(camper, site, nights)
        self.records.append(record)
        return record

    def charges(self, requests):
        results = []
        for raw in requests:
            camper, nights = parse_request(raw)
            record = self.assign(camper, nights)
            results.append((camper.name, record.total_cost() if record else 0))
        return results


def parse_request(raw):
    name, preference, nights = raw
    if not name:
        raise ValueError("camper name must not be empty")
    if preference not in ("premium", "basic"):
        raise ValueError("unknown site preference: %r" % (preference,))
    if not isinstance(nights, int) or nights < 1:
        raise ValueError("duration must be a positive whole number of nights")
    return NatureCamper(name, preference), nights


def book(requests):
    return BookingLedger(2, 3).charges(requests)


def main():
    requests = [("Ana", "basic", 2), ("Bo", "premium", 3),
                ("Cy", "premium", 1), ("Dee", "premium", 4)]
    ledger = BookingLedger(2, 3)
    print(ledger.charges(requests))
    for record in ledger.records:
        receipt = StayReceipt(record)
        print(receipt.line())


if __name__ == "__main__":
    main()

