CHILD_AGE_LIMIT = 12
ADULT_DAY_RATE = 80
CHILD_DAY_RATE = 50
GEAR_DAY_RATE = 30
SHORT_TRIP_DAYS = 3


class WinterSkier:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def is_child(self):
        return self.age < CHILD_AGE_LIMIT


class LiftPass:
    def __init__(self, skier, days):
        self.skier = skier
        self.days = days
        self.daily_rate = CHILD_DAY_RATE if skier.is_child() else ADULT_DAY_RATE

    def cost(self):
        return self.daily_rate * self.days


class GearRental:
    def __init__(self, days):
        self.days = days
        self.required = days < SHORT_TRIP_DAYS

    def cost(self):
        return GEAR_DAY_RATE * self.days if self.required else 0


class SkierInvoice:
    def __init__(self, skier, days):
        self.skier = skier
        self.lift_pass = LiftPass(skier, days)
        self.gear_rental = GearRental(days)

    def total(self):
        return self.lift_pass.cost() + self.gear_rental.cost()


class ReportLine:
    def __init__(self, name, total):
        self.name = name
        self.total = total

    def render(self):
        return "{:<12}{:>6}".format(self.name, self.total)


def issue(skiers):
    prices = []
    for name, age, days in skiers:
        if age < 0 or days < 1:
            raise ValueError("invalid booking for {}".format(name))
        skier = WinterSkier(name, age)
        invoice = SkierInvoice(skier, days)
        prices.append((skier.name, invoice.total()))
    return prices


def build_report(prices):
    lines = []
    for name, total in prices:
        line = ReportLine(name, total)
        lines.append(line.render())
    lines.append(ReportLine("TOTAL", sum(t for _, t in prices)).render())
    return "\n".join(lines)


def main():
    bookings = [("Anna", 34, 2), ("Tim", 8, 5), ("Olav", 41, 7)]
    print(build_report(issue(bookings)))


if __name__ == "__main__":
    main()

