        self.skier = skier
        self.lift_pass = lift_pass(skier, days)
        self.gear_rental = gear_rental(days)

    def total(self):
        return self.lift_pass.cost() + self.gear_rental.cost()


class report_line:
    def __init__(self, name, total):
        self.name = name
        self.total = total

    def render(self):
        return "{:<12}{:>6}".format(self.name, self.total)


def issue(skiers):
    prices = []
    for name, age, days in skiers:
        if age < 0 or days < 1:
            raise ValueError("invalid booking for {}".format(name))
        skier = winter_skier(name, age)
        invoice = skier_invoice(skier, days)
        prices.append((skier.name, invoice.total()))
    return prices


def build_report(prices):
    lines = []
    for name, total in prices:
        line = report_line(name, total)
        lines.append(line.render())
    lines.append(report_line("TOTAL", sum(t for _, t in prices)).render())
    return "\n".join(lines)


def main():
    bookings = [("Anna", 34, 2), ("Tim", 8, 5), ("Olav", 41, 7)]
    print(build_report(issue(bookings)))


if __name__ == "__main__":
    main()

