class AuctionItem:
    STARTING_PRICE = 100

    def __init__(self, identifier):
        self.identifier = identifier
        self.starting_price = AuctionItem.STARTING_PRICE

    def accepts(self, amount):
        return amount >= self.starting_price


class UserBid:
    def __init__(self, bidder, amount):
        if not isinstance(amount, (int, float)):
            raise ValueError("bid amount must be numeric: %r" % (amount,))
        self.bidder = bidder
        self.amount = amount

    def beats(self, other):
        return self.amount > other.amount


class WinningEntry:
    def __init__(self, item, bid):
        self.item = item
        self.bid = bid

    def as_tuple(self):
        return (self.item.identifier, self.bid.bidder)


class WinningLedger:
    def __init__(self):
        self._entries = {}
        self._order = []

    def offer(self, item, bid):
        if not item.accepts(bid.amount):
            return
        current = self._entries.get(item.identifier)
        if current is None:
            self._order.append(item.identifier)
            self._entries[item.identifier] = WinningEntry(item, bid)
        elif bid.beats(current.bid):
            self._entries[item.identifier] = WinningEntry(item, bid)

    def results(self):
        return [self._entries[key].as_tuple() for key in self._order]

    def winning_amount(self, identifier):
        return self._entries[identifier].bid.amount


class BidReportFormatter:
    def __init__(self, ledger):
        self.ledger = ledger

    def lines(self):
        for identifier, bidder in self.ledger.results():
            yield "%s -> %s (%d)" % (identifier, bidder, self.ledger.winning_amount(identifier))


def evaluate(bids):
    ledger = WinningLedger()
    items = {}
    for bidder, identifier, amount in bids:
        item = items.get(identifier)
        if item is None:
            item = AuctionItem(identifier)
            items[identifier] = item
        ledger.offer(item, UserBid(bidder, amount))
    return ledger.results()


def main():
    bids = [
        ("Dave", "lamp-1", 90),
        ("Eve", "lamp-1", 120),
        ("Frank", "lamp-1", 110),
        ("Gina", "vase-2", 80),
        ("Hank", "clock-3", 100),
    ]
    print(evaluate(bids))
    ledger = WinningLedger()
    for bidder, identifier, amount in bids:
        ledger.offer(AuctionItem(identifier), UserBid(bidder, amount))
    reporter = BidReportFormatter(ledger)
    for line in reporter.lines():
        print(line)


if __name__ == "__main__":
    main()

