class GuestRecord:
    """A validated row of raw guest input."""

    def __init__(self, name, side, diet):
        self.name = name
        self.side = side
        self.diet = diet


def parse_guest_row(row):
    if len(row) != 3:
        raise ValueError("a guest row needs a name, a side and a diet: %r" % (row,))
    name, side, diet = row
    if not str(name).strip():
        raise ValueError("a guest must have a name")
    return GuestRecord(str(name).strip(), str(side).strip().lower(), str(diet).strip().lower())


class WeddingGuest:
    VEGETARIAN_DIETS = frozenset({"vegetarian", "vegan"})

    def __init__(self, name, diet):
        self.name = name
        self.diet = diet

    @property
    def is_vegetarian(self):
        return self.diet in self.VEGETARIAN_DIETS


class BanquetTable:
    CAPACITY = 8

    def __init__(self, side, number):
        self.side = side
        self.number = number
        self.guests = []

    @property
    def has_room(self):
        return len(self.guests) < self.CAPACITY

    def seat_guest(self, guest):
        self.guests.append(guest)

    @property
    def vegetarian_count(self):
        return sum(1 for guest in self.guests if guest.is_vegetarian)


class SideSummary:
    def __init__(self, side, vegetarian_meals, guest_count, table_count):
        self.side = side
        self.vegetarian_meals = vegetarian_meals
        self.guest_count = guest_count
        self.table_count = table_count

    def as_tuple(self):
        return (self.side, self.vegetarian_meals)


class SeatingPlan:
    def __init__(self):
        self.sides = []
        self.tables = []

    def tables_for_side(self, side):
        return [table for table in self.tables if table.side == side]

    def seat_guest(self, side, guest):
        if side not in self.sides:
            self.sides.append(side)
        side_tables = self.tables_for_side(side)
        for table in side_tables:
            if table.has_room:
                table.seat_guest(guest)
                return table
        table = BanquetTable(side, len(side_tables) + 1)
        table.seat_guest(guest)
        self.tables.append(table)
        return table

    def summaries(self):
        summaries = []
        for side in self.sides:
            side_tables = self.tables_for_side(side)
            meals = sum(table.vegetarian_count for table in side_tables)
            seated = sum(len(table.guests) for table in side_tables)
            summaries.append(SideSummary(side, meals, seated, len(side_tables)))
        return summaries


def build_plan(guests):
    plan = SeatingPlan()
    for row in guests:
        record = parse_guest_row(row)
        guest = WeddingGuest(record.name, record.diet)
        plan.seat_guest(record.side, guest)
    return plan


def format_report(plan):
    lines = []
    for summary in plan.summaries():
        lines.append("%s: %d guests on %d table(s), %d vegetarian meal(s)"
                     % (summary.side, summary.guest_count, summary.table_count,
                        summary.vegetarian_meals))
        for table in plan.tables_for_side(summary.side):
            names = ", ".join(guest.name for guest in table.guests)
            lines.append("  table %d: %s" % (table.number, names))
    return "\n".join(lines)


def seat(guests):
    return [summary.as_tuple() for summary in build_plan(guests).summaries()]


def main():
    party = [("Ada", "bride", "vegetarian"), ("Ben", "groom", "none"),
             ("Cleo", "bride", "vegan"), ("Dan", "groom", "vegetarian"),
             ("Eve", "bride", "none"), ("Finn", "bride", "none"),
             ("Gus", "bride", "none"), ("Hana", "bride", "vegetarian"),
             ("Iris", "bride", "none"), ("Jon", "bride", "vegan")]
    print(format_report(build_plan(party)))
    print(seat(party))
    print(seat([("Ada", "bride", "vegetarian")]))


if __name__ == "__main__":
    main()

