class DonationEntry:
    """A validated raw donation record: donor name, amount, recurring flag."""

    def __init__(self, name, amount, recurring):
        if not isinstance(name, str) or not name.strip():
            raise ValueError("donor name must be a non-empty string")
        if amount < 0:
            raise ValueError("donation amount must not be negative")
        self.name = name.strip()
        self.amount = float(amount)
        self.recurring = bool(recurring)


class FinancialPledge:
    """A single pledge; recurring pledges count double toward the total."""

    def __init__(self, amount, recurring):
        self.amount = amount
        self.recurring = recurring

    def effective_amount(self):
        return self.amount * 2 if self.recurring else self.amount


class CampaignDonor:
    """A donor together with every pledge they have made."""

    def __init__(self, name):
        self.name = name
        self.pledges = []

    def add_pledge(self, pledge):
        self.pledges.append(pledge)

    def effective_total(self):
        return sum(pledge.effective_amount() for pledge in self.pledges)


class RewardTier:
    """Gold above five hundred effective dollars, silver otherwise."""

    def __init__(self, effective_total):
        self.status = "gold" if effective_total > 500 else "silver"


class LedgerReport:
    """Human-readable summary of the tiers assigned to each donor."""

    def __init__(self, results):
        self.results = results

    def render(self):
        width = max((len(name) for name, _ in self.results), default=0)
        lines = ["{0:<{1}}  {2}".format(name, width, tier)
                 for name, tier in self.results]
        return "\n".join(lines)


def track(donations):
    donors = {}
    order = []
    for name, amount, recurring in donations:
        entry = DonationEntry(name, amount, recurring)
        if entry.name not in donors:
            donors[entry.name] = CampaignDonor(entry.name)
            order.append(entry.name)
        pledge = FinancialPledge(entry.amount, entry.recurring)
        donors[entry.name].add_pledge(pledge)
    results = []
    for name in order:
        tier = RewardTier(donors[name].effective_total())
        results.append((name, tier.status))
    return results


