MAX_BATTERY = 100

DIRECTIONS = {"N": (0, 1), "S": (0, -1), "E": (1, 0), "W": (-1, 0)}


class FloorTile:
    def __init__(self, position):
        self.position = position
        self.passes = 0

    def receive(self, vacuum):
        self.passes += 1


class DustBunny:
    def __init__(self, position, dirt_level):
        self.position = position
        self.dirt_level = dirt_level

    def receive(self, vacuum):
        vacuum.collect(self.dirt_level)
        self.dirt_level = 0


class ChargingStation:
    def __init__(self, position, charge_available):
        self.position = position
        self.charge_available = charge_available

    def receive(self, vacuum):
        transferred = min(vacuum.battery_deficit(), self.charge_available)
        self.charge_available -= transferred
        vacuum.recharge(transferred)


class RobotVacuum:
    def __init__(self):
        self.position = (0, 0)
        self.battery = MAX_BATTERY
        self.dirt_collected = 0

    def move(self, delta):
        if self.battery <= 0:
            return False
        self.position = (self.position[0] + delta[0], self.position[1] + delta[1])
        self.battery -= 1
        return True

    def collect(self, dirt):
        self.dirt_collected += dirt

    def battery_deficit(self):
        return MAX_BATTERY - self.battery

    def recharge(self, amount):
        self.battery += amount


class CleaningGrid:
    def __init__(self):
        self.tiles = {}

    def place(self, entity):
        self.tiles[entity.position] = entity

    def tile_at(self, position):
        if position not in self.tiles:
            self.tiles[position] = FloorTile(position)
        return self.tiles[position]

    def clean_floor_passes(self):
        return sum(t.passes for t in self.tiles.values() if isinstance(t, FloorTile))

    def dirt_remaining(self):
        return sum(t.dirt_level for t in self.tiles.values() if isinstance(t, DustBunny))


class ParsedCommand:
    def __init__(self, name, args):
        self.name = name
        self.args = args

    def position(self):
        return (int(self.args[0]), int(self.args[1]))

    def amount(self):
        return int(self.args[2])

    def direction(self):
        return DIRECTIONS[self.args[0].upper()]


class CleaningReport:
    def __init__(self, vacuum, grid):
        self.vacuum = vacuum
        self.grid = grid

    def render(self):
        return (
            "dirt collected: {}\nbattery: {}\ndirt left behind: {}\n"
            "clean floor passes: {}".format(
                self.vacuum.dirt_collected,
                self.vacuum.battery,
                self.grid.dirt_remaining(),
                self.grid.clean_floor_passes(),
            )
        )


def parse_instruction(text):
    parts = text.split()
    if not parts:
        raise ValueError("empty instruction")
    return ParsedCommand(parts[0].upper(), parts[1:])


def run(instructions):
    grid = CleaningGrid()
    vacuum = RobotVacuum()
    for text in instructions:
        command = parse_instruction(text)
        if command.name == "DUST":
            grid.place(DustBunny(command.position(), command.amount()))
        elif command.name == "CHARGER":
            grid.place(ChargingStation(command.position(), command.amount()))
        elif command.name == "MOVE":
            if vacuum.move(command.direction()):
                grid.tile_at(vacuum.position).receive(vacuum)
        else:
            raise ValueError("unknown command: " + command.name)
    return vacuum, grid


def simulate(instructions):
    vacuum, _grid = run(instructions)
    return (vacuum.dirt_collected, vacuum.battery)


def main():
    script = [
        "DUST 1 0 5",
        "DUST 2 0 5",
        "CHARGER 3 0 100",
        "MOVE E",
        "MOVE E",
        "MOVE E",
        "MOVE N",
    ]
    print(simulate(script))
    vacuum, grid = run(script)
    report = CleaningReport(vacuum, grid)
    print(report.render())


if __name__ == "__main__":
    main()

