        else:
            raise ValueError("unknown command: " + command.name)
    return vacuum, grid


def simulate(instructions):
    vacuum, _grid = run(instructions)
    return (vacuum.dirt_collected, vacuum.battery)


def main():
    script = [
        "DUST 1 0 5",
        "DUST 2 0 5",
        "CHARGER 3 0 100",
        "MOVE E",
        "MOVE E",
        "MOVE E",
        "MOVE N",
    ]
    print(simulate(script))
    vacuum, grid = run(script)
    report = cleaning_report(vacuum, grid)
    print(report.render())


if __name__ == "__main__":
    main()

