import math


class NoteEvent:
    """A single note, identified by its frequency and position in the sequence."""

    def __init__(self, frequency, index):
        if frequency <= 0:
            raise ValueError("note frequency must be positive, got %r" % (frequency,))
        self.frequency = float(frequency)
        self.index = index


class SineOscillator:
    """Pure tone generator: one sine sample taken at the first frame of the note."""

    def __init__(self, sample_rate):
        self.sample_rate = sample_rate

    def sample(self, event):
        return math.sin(2.0 * math.pi * event.frequency / self.sample_rate)


class SquareWaveGenerator:
    """Band-limited square wave built from a finite sum of odd harmonics."""

    def __init__(self, sample_rate, harmonics=5):
        self.sample_rate = sample_rate
        self.harmonics = harmonics

    def sample(self, event):
        total = 0.0
        for k in range(self.harmonics):
            order = 2 * k + 1
            total += math.sin(2.0 * math.pi * order * event.frequency / self.sample_rate) / order
        return (4.0 / math.pi) * total


class EnvelopeFilter:
    """Scales an audio level by an attack gain and an exponential per-note decay."""

    def __init__(self, attack, decay):
        self.attack = attack
        self.decay = decay

    def apply(self, level, index):
        return level * self.attack * (self.decay ** index)


class MixerBus:
    """Collects filtered note levels and reports their summed amplitude."""

    def __init__(self):
        self.levels = []

    def feed(self, level):
        self.levels.append(level)

    def total(self):
        return sum(self.levels)


class SynthReport:
    """Renders per-note amplitudes plus the mix total as readable text."""

    def __init__(self, rows, total):
        self.rows = rows
        self.total = total

    def render(self):
        lines = ["%2d. %8.2f Hz -> %+.6f" % (e.index + 1, e.frequency, a) for e, a in self.rows]
        lines.append("mix total: %.6f" % self.total)
        return "\n".join(lines)


def voice_amplitudes(notes):
    sine = SineOscillator(44100)
    square = SquareWaveGenerator(44100)
    envelope = EnvelopeFilter(0.9, 0.75)
    rows = []
    for index, frequency in enumerate(notes):
        event = NoteEvent(frequency, index)
        oscillator = sine if index % 2 == 0 else square
        rows.append((event, envelope.apply(oscillator.sample(event), index)))
    return rows


def synthesize(notes):
    bus = MixerBus()
    for _event, amplitude in voice_amplitudes(notes):
        bus.feed(amplitude)
    return round(bus.total(), 4)


def main():
    notes = [440.0, 493.88, 523.25]
    report = SynthReport(voice_amplitudes(notes), synthesize(notes))
    print(report.render())


if __name__ == "__main__":
    main()

