LOBBY_FLOOR = 0
VALID_DIRECTIONS = ("up", "down")


class CallRequest:
    """A single hall call: a floor number plus the requested direction."""

    REGISTRATION_SECONDS = 1

    def __init__(self, floor, direction):
        if not isinstance(floor, int) or floor < LOBBY_FLOOR:
            raise ValueError("floor must be a non-negative integer, got %r" % (floor,))
        normalized = str(direction).strip().lower()
        if normalized not in VALID_DIRECTIONS:
            raise ValueError("direction must be 'up' or 'down', got %r" % (direction,))
        self.floor = floor
        self.direction = normalized

    def __str__(self):
        return "floor %d (%s)" % (self.floor, self.direction)


class FloorButtonPanel:
    """Registers pressed buttons and keeps them in the order they arrived."""

    def __init__(self):
        self.pressed = []

    def press(self, call):
        self.pressed.append(call)

    def registration_seconds(self):
        return len(self.pressed) * CallRequest.REGISTRATION_SECONDS

    def pending(self):
        return list(self.pressed)


class DoorMotor:
    """Knows how long it takes to open and close the doors once."""

    def __init__(self, open_seconds, close_seconds):
        self.open_seconds = open_seconds
        self.close_seconds = close_seconds

    def cycle_seconds(self):
        return self.open_seconds + self.close_seconds


class ElevatorCabin:
    """Tracks position and occupancy, and the time spent moving and loading."""

    def __init__(self, capacity, seconds_per_floor=2, seconds_per_passenger=1):
        self.capacity = capacity
        self.seconds_per_floor = seconds_per_floor
        self.seconds_per_passenger = seconds_per_passenger
        self.current_floor = LOBBY_FLOOR
        self.occupancy = 0

    def travel_to(self, floor):
        distance = abs(floor - self.current_floor)
        self.current_floor = floor
        return distance * self.seconds_per_floor

    def board(self):
        self.occupancy += 1
        return self.seconds_per_passenger

    def is_full(self):
        return self.occupancy >= self.capacity

    def discharge(self):
        leaving = self.occupancy
        self.occupancy = 0
        return leaving * self.seconds_per_passenger


class TripReport:
    """Formats the outcome of a dispatch run."""

    def __init__(self, calls, total_seconds):
        self.calls = calls
        self.total_seconds = total_seconds

    def render(self):
        lines = ["Served %d call(s):" % len(self.calls)]
        lines.extend("  - " + str(call) for call in self.calls)
        lines.append("Total time: %d seconds" % self.total_seconds)
        return "\n".join(lines)


def parse_requests(requests):
    return [CallRequest(floor, direction) for floor, direction in requests]


def dispatch(requests):
    calls = parse_requests(requests)
    panel = FloorButtonPanel()
    for call in calls:
        panel.press(call)
    cabin = ElevatorCabin(capacity=3)
    motor = DoorMotor(3, 3)
    total = panel.registration_seconds()
    for call in panel.pending():
        total += cabin.travel_to(call.floor)
        total += motor.cycle_seconds()
        total += cabin.board()
        if cabin.is_full():
            total += cabin.travel_to(LOBBY_FLOOR)
            total += motor.cycle_seconds()
            total += cabin.discharge()
    if cabin.occupancy:
        total += cabin.travel_to(LOBBY_FLOOR)
        total += motor.cycle_seconds()
        total += cabin.discharge()
    return int(total)


def main():
    morning_calls = [(2, "up"), (3, "up"), (1, "down")]
    report = TripReport(parse_requests(morning_calls), dispatch(morning_calls))
    print(report.render())


if __name__ == "__main__":
    main()

