class ClimateBaseline:
    """Target climate the greenhouse controls try to restore."""

    def __init__(self, min_temperature, max_temperature, min_moisture):
        self.min_temperature = min_temperature
        self.max_temperature = max_temperature
        self.min_moisture = min_moisture

    def too_hot(self, reading):
        return reading.temperature > self.max_temperature

    def too_cold(self, reading):
        return reading.temperature < self.min_temperature

    def too_dry(self, reading):
        return reading.moisture < self.min_moisture


class SensorReading:
    def __init__(self, temperature, moisture):
        self.temperature = temperature
        self.moisture = moisture


class VentFan:
    label = "vent fan"

    def __init__(self, minutes_per_cycle=5):
        self.minutes_per_cycle = minutes_per_cycle
        self.total_minutes = 0

    def apply(self, reading, baseline):
        if baseline.too_hot(reading):
            self.total_minutes += self.minutes_per_cycle


class HeatingMat:
    label = "heating mat"

    def __init__(self, minutes_per_cycle=10):
        self.minutes_per_cycle = minutes_per_cycle
        self.total_minutes = 0

    def apply(self, reading, baseline):
        if baseline.too_cold(reading):
            self.total_minutes += self.minutes_per_cycle


class DripIrrigator:
    label = "drip irrigator"

    def __init__(self, minutes_per_cycle=5):
        self.minutes_per_cycle = minutes_per_cycle
        self.total_minutes = 0

    def apply(self, reading, baseline):
        if baseline.too_dry(reading):
            self.total_minutes += self.minutes_per_cycle


class ClimateReport:
    def __init__(self, controls, totals):
        self.controls = controls
        self.totals = totals

    def lines(self):
        return ["%s ran %d minute(s)" % (control.label, minutes)
                for control, minutes in zip(self.controls, self.totals)]


def parse_reading(raw):
    if len(raw) != 2:
        raise ValueError("each reading needs a temperature and a moisture value")
    temperature, moisture = raw
    return SensorReading(float(temperature), float(moisture))


def build_controls():
    fan = VentFan()
    mat = HeatingMat()
    irrigator = DripIrrigator()
    return [fan, mat, irrigator]


def regulate(readings):
    baseline = ClimateBaseline(18.0, 27.0, 40.0)
    controls = build_controls()
    for raw in readings:
        reading = parse_reading(raw)
        for control in controls:
            control.apply(reading, baseline)
    return [control.total_minutes for control in controls]


def main():
    samples = [(14.0, 30.0), (15.5, 22.0), (21.0, 55.0), (31.0, 60.0)]
    report = ClimateReport(build_controls(), regulate(samples))
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

