class DeliveryOrder:
    """A single package drop: payload weight in kg and one-way distance in km."""

    def __init__(self, weight, distance):
        if weight <= 0 or distance <= 0:
            raise ValueError("weight and distance must be positive")
        self.weight = float(weight)
        self.distance = float(distance)

    def round_trip(self):
        return self.distance * 2.0


class QuadCopter:
    """Light, fast courier drone."""

    capacity = 2.0
    speed = 30.0
    drain = 1.5

    def __init__(self):
        self.battery = 100.0

    def can_carry(self, order):
        return order.weight <= self.capacity

    def flight_time(self, order):
        return order.round_trip() / self.speed * 60.0


class HeavyLifterDrone:
    """Slower airframe able to move bulky payloads at a higher battery cost."""

    capacity = 12.0
    speed = 20.0
    drain = 2.4

    def __init__(self):
        self.battery = 100.0

    def can_carry(self, order):
        return order.weight <= self.capacity

    def flight_time(self, order):
        return order.round_trip() / self.speed * 60.0


class ChargingPad:
    """Ground station that refills a drone battery and counts charge cycles."""

    def __init__(self):
        self.cycles = 0

    def recharge(self, drone):
        drone.battery = 100.0
        self.cycles += 1


class FlightPlan:
    """A candidate assignment of one order to one drone."""

    def __init__(self, drone, order):
        self.drone = drone
        self.order = order
        self.duration = drone.flight_time(order)
        self.battery_cost = self.duration * drone.drain

    def execute(self):
        self.drone.battery -= self.battery_cost
        return self.duration


class DispatchReport:
    """Human readable summary of a dispatch run."""

    def __init__(self, minutes, cycles):
        self.minutes = minutes
        self.cycles = cycles

    def as_text(self):
        return "{0:.1f} minutes of flight, {1} charge cycle(s)".format(self.minutes, self.cycles)


def dispatch(deliveries):
    quad = QuadCopter()
    lifter = HeavyLifterDrone()
    pad = ChargingPad()
    fleet = (quad, lifter)
    total_time = 0.0
    for weight, distance in deliveries:
        order = DeliveryOrder(weight, distance)
        plans = []
        for drone in fleet:
            if drone.can_carry(order):
                plans.append(FlightPlan(drone, order))
        if not plans:
            raise ValueError("no drone can lift {0} kg".format(order.weight))
        plan = min(plans, key=lambda p: (p.duration, p.battery_cost))
        if plan.battery_cost > plan.drone.battery:
            pad.recharge(plan.drone)
        total_time += plan.execute()
    return (round(total_time, 1), pad.cycles)


def main():
    light_run = [(1.0, 4.0), (0.8, 3.0), (1.2, 3.0)]
    mixed_run = [(1.0, 4.0), (9.5, 12.0), (2.0, 9.0), (11.0, 14.0)]
    for label, batch in (("light", light_run), ("mixed", mixed_run)):
        minutes, cycles = dispatch(batch)
        report = DispatchReport(minutes, cycles)
        print(label, "run:", report.as_text())


if __name__ == "__main__":
    main()

