BASE_LOAD_WATTS = 400.0


class WindReading:
    """A single hourly wind speed sample in miles per hour."""

    def __init__(self, hour, speed):
        if isinstance(speed, bool) or not isinstance(speed, (int, float)):
            raise TypeError("wind speed at hour %d must be numeric" % hour)
        if speed < 0:
            raise ValueError("wind speed at hour %d cannot be negative" % hour)
        self.hour = hour
        self.speed = float(speed)


class TurbineBlade:
    """Converts wind speed into mechanical spin, measured in rpm."""

    def __init__(self, cut_in=5.0, cut_out=55.0, spin_factor=4.0):
        self.cut_in = cut_in
        self.cut_out = cut_out
        self.spin_factor = spin_factor

    def spin(self, speed):
        if speed < self.cut_in or speed >= self.cut_out:
            return 0.0
        return (speed - self.cut_in) * self.spin_factor


class RotaryGenerator:
    """Turns mechanical spin into electrical watts, limited by its rating."""

    def __init__(self, watts_per_rpm=10.0, efficiency=0.85, rated_watts=1200.0):
        self.watts_per_rpm = watts_per_rpm
        self.efficiency = efficiency
        self.rated_watts = rated_watts

    def output(self, rpm):
        return min(rpm * self.watts_per_rpm * self.efficiency, self.rated_watts)


class BatteryBank:
    """Stores surplus watt-hours up to a fixed capacity."""

    def __init__(self, capacity=1000.0):
        self.capacity = capacity
        self.charge = 0.0

    def store(self, surplus):
        accepted = min(surplus, self.capacity - self.charge)
        self.charge += accepted
        return accepted


class FarmReport:
    """Formats the outcome of a simulation run for display."""

    def __init__(self, hours, generated, stored):
        self.hours = hours
        self.generated = generated
        self.stored = stored

    def lines(self):
        yield "hours simulated : %d" % self.hours
        yield "watts generated : %d" % self.generated
        yield "watts stored    : %d" % self.stored


def simulate(winds):
    readings = [WindReading(hour, speed) for hour, speed in enumerate(winds)]
    blade = TurbineBlade()
    generator = RotaryGenerator()
    bank = BatteryBank()
    generated = 0.0
    for reading in readings:
        watts = generator.output(blade.spin(reading.speed))
        generated += watts
        surplus = watts - BASE_LOAD_WATTS
        if surplus > 0:
            bank.store(surplus)
    return round(generated), round(bank.charge)


def main():
    winds = [20.0] * 10
    generated, stored = simulate(winds)
    report = FarmReport(len(winds), generated, stored)
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

