SAFE_LEVEL = 5.0


class SampleBatch:
    """A batch of water samples with their contamination levels."""

    def __init__(self, levels):
        cleaned = []
        for value in levels:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("contamination levels must be numbers")
            if value < 0:
                raise ValueError("contamination levels cannot be negative")
            cleaned.append(float(value))
        self.levels = cleaned

    def total(self):
        return sum(self.levels)

    def unsafe_count(self):
        return sum(1 for level in self.levels if level > SAFE_LEVEL)


class StageReport:
    """What a single treatment stage achieved and what it charged."""

    def __init__(self, stage, cost, levels):
        self.stage = stage
        self.cost = cost
        self.levels = levels


class SedimentFilter:
    """Screens out large particles, charged per sample pushed through."""

    name = "sediment filter"
    price_per_sample = 1.0

    def treat(self, batch):
        levels = [level * 0.6 for level in batch.levels]
        return StageReport(self.name, self.price_per_sample * len(levels), levels)


class ChemicalMixer:
    """Neutralizes toxins with a dose sized by the volume it receives."""

    name = "chemical mixer"
    litres_per_dose = 30.0
    price_per_dose = 2.0

    def treat(self, batch):
        volume = batch.total()
        doses = int(-(-volume // self.litres_per_dose))
        levels = [level * 0.5 for level in batch.levels]
        return StageReport(self.name, doses * self.price_per_dose, levels)


class UltravioletLamp:
    """Burns off bacteria in every sample still above the safe level."""

    name = "ultraviolet lamp"
    price_per_sample = 5.0

    def treat(self, batch):
        cost = self.price_per_sample * batch.unsafe_count()
        levels = [min(level, SAFE_LEVEL * 0.5) for level in batch.levels]
        return StageReport(self.name, cost, levels)


class TreatmentPlant:
    """Runs a batch through every stage in order and collects the reports."""

    def __init__(self):
        self.stages = [SedimentFilter(), ChemicalMixer(), UltravioletLamp()]

    def run(self, batch):
        reports = []
        for stage in self.stages:
            report = stage.treat(batch)
            reports.append(report)
            batch = SampleBatch(report.levels)
        return reports


def purify(samples):
    plant = TreatmentPlant()
    return sum(report.cost for report in plant.run(SampleBatch(samples)))


def describe(samples):
    lines = []
    plant = TreatmentPlant()
    for report in plant.run(SampleBatch(samples)):
        worst = max(report.levels)
        lines.append(f"{report.stage:>16}: cost {report.cost:6.2f}, worst level {worst:7.2f}")
    lines.append(f"{'total':>16}: cost {purify(samples):6.2f}")
    return "\n".join(lines)


if __name__ == "__main__":
    readings = [96.0, 104.0, 100.0, 98.0, 102.0]
    print(describe(readings))

