MATERIALS_WEATHERPROOF = {"steel", "lumber", "pipe", "gravel", "coal"}
MATERIALS_FRAGILE = {"electronics", "glass", "grain", "textiles"}


class FreightCrate:
    def __init__(self, weight, material):
        self.weight = float(weight)
        self.material = str(material).strip().lower()
        if self.weight <= 0:
            raise ValueError("crate weight must be positive: %r" % weight)
        if self.material not in MATERIALS_WEATHERPROOF | MATERIALS_FRAGILE:
            raise ValueError("unknown material: %r" % material)


class FlatbedCar:
    capacity = 4000.0
    tare = 1200.0
    label = "flatbed"

    def __init__(self):
        self.crates = []
        self.loaded = 0.0

    def accepts(self, crate):
        return (crate.material in MATERIALS_WEATHERPROOF
                and self.loaded + crate.weight <= self.capacity)

    def stow(self, crate):
        self.crates.append(crate)
        self.loaded += crate.weight


class BoxCar:
    capacity = 2500.0
    tare = 1800.0
    label = "boxcar"

    def __init__(self):
        self.crates = []
        self.loaded = 0.0

    def accepts(self, crate):
        return (crate.weight <= 1200.0
                and self.loaded + crate.weight <= self.capacity)

    def stow(self, crate):
        self.crates.append(crate)
        self.loaded += crate.weight


class LocomotiveEngine:
    def __init__(self, max_pull):
        self.max_pull = float(max_pull)

    def can_pull(self, trailing_weight):
        return trailing_weight <= self.max_pull


class TrainConsist:
    def __init__(self, engine):
        self.engine = engine
        self.cars = []
        self.left_behind = []

    def trailing_weight(self):
        return sum(car.tare + car.loaded for car in self.cars)

    def accept(self, crate):
        for car in self.cars:
            if car.accepts(crate) and self.engine.can_pull(self.trailing_weight() + crate.weight):
                car.stow(crate)
                return True
        if crate.material in MATERIALS_WEATHERPROOF:
            fresh = FlatbedCar()
        else:
            fresh = BoxCar()
        if not fresh.accepts(crate) or not self.engine.can_pull(
                self.trailing_weight() + fresh.tare + crate.weight):
            self.left_behind.append(crate)
            return False
        fresh.stow(crate)
        self.cars.append(fresh)
        return True

    def total_weight(self):
        return sum(car.loaded for car in self.cars)


def load(crates):
    engine = LocomotiveEngine(30000)
    consist = TrainConsist(engine)
    for weight, material in crates:
        consist.accept(FreightCrate(weight, material))
    return len(consist.cars), consist.total_weight(), consist


def format_manifest(consist):
    lines = ["%2d. %-8s %7.0f lb (%d crates)" % (i + 1, car.label, car.loaded, len(car.crates))
             for i, car in enumerate(consist.cars)]
    if consist.left_behind:
        lines.append("left behind: %d crates" % len(consist.left_behind))
    return "\n".join(lines)


def main():
    shipment = []
    for i in range(20):
        if i % 4 == 3:
            shipment.append((900, "electronics"))
        else:
            shipment.append((600, "steel"))
    cars, weight, consist = load(shipment)
    print(format_manifest(consist))
    print("%d cars, %.0f pounds loaded" % (cars, weight))


if __name__ == "__main__":
    main()

