class PrintJob:
    INTENSITY = {"color": 1.0, "mono": 0.1}

    def __init__(self, pages, color_type):
        if pages <= 0:
            raise ValueError("a print job needs at least one page")
        if color_type not in self.INTENSITY:
            raise ValueError("unknown color type: %s" % color_type)
        self.pages = pages
        self.color_type = color_type
        self.intensity = self.INTENSITY[color_type]

    def ink_needed(self):
        return self.pages * self.intensity


class PaperFeeder:
    JAM_INTERVAL = 50
    RECOVERY_SECONDS = 15.0

    def __init__(self, sheets):
        self.sheets = sheets
        self.fed = 0
        self.jams = 0

    def can_feed(self, pages):
        return self.sheets >= pages

    def feed(self, pages):
        fresh_jams = (self.fed + pages) // self.JAM_INTERVAL - self.fed // self.JAM_INTERVAL
        self.fed += pages
        self.sheets -= pages
        self.jams += fresh_jams
        return fresh_jams * self.RECOVERY_SECONDS


class CyanCartridge:
    def __init__(self, units):
        self.units = units

    def can_supply(self, units):
        return self.units >= units

    def deplete(self, units):
        self.units -= units


class DryingHeater:
    WARMUP_SECONDS = 10.0

    def seconds_for(self, job):
        per_page = 3.5 if job.color_type == "color" else 1.2
        return self.WARMUP_SECONDS + job.pages * per_page


class JobQueueParser:
    def __init__(self, default_color="mono"):
        self.default_color = default_color

    def parse(self, line):
        parts = line.split()
        color_type = parts[1] if len(parts) > 1 else self.default_color
        return int(parts[0]), color_type


class ShopReport:
    def __init__(self, submitted):
        self.submitted = submitted

    def summary(self, completed, seconds):
        return "%d/%d jobs done in %d s" % (completed, self.submitted, seconds)


def process(jobs):
    feeder = PaperFeeder(500)
    cartridge = CyanCartridge(80.0)
    heater = DryingHeater()
    completed = 0
    elapsed = 0.0
    for pages, color_type in jobs:
        job = PrintJob(pages, color_type)
        ink = job.ink_needed()
        if not feeder.can_feed(job.pages) or not cartridge.can_supply(ink):
            break
        elapsed += feeder.feed(job.pages)
        cartridge.deplete(ink)
        elapsed += heater.seconds_for(job)
        completed += 1
    return completed, int(round(elapsed))


def main():
    parser = JobQueueParser()
    jobs = [parser.parse(line) for line in ["25 color", "25 color", "25 color", "25 color"]]
    completed, seconds = process(jobs)
    report = ShopReport(len(jobs))
    print(report.summary(completed, seconds))


if __name__ == "__main__":
    main()

