class SensorEvent:
    def __init__(self, code, timestamp):
        self.code = code
        self.timestamp = timestamp


class EventParser:
    """Turns raw codes such as 'motion' or 'seismic@7' into timed events."""

    def __init__(self):
        self.clock = 0

    def parse(self, raw):
        text = raw.strip().lower()
        if "@" in text:
            name, stamp = text.split("@", 1)
            timestamp = int(stamp)
            self.clock = timestamp + 1
        else:
            name = text
            timestamp = self.clock
            self.clock += 1
        return SensorEvent(name, timestamp)


class TripWindowSensor:
    def __init__(self, name, threshold, window):
        self.name = name
        self.threshold = threshold
        self.window = window
        self.trips = []

    def register(self, timestamp):
        self.trips = [t for t in self.trips if timestamp - t <= self.window]
        self.trips.append(timestamp)
        return len(self.trips) >= self.threshold

    def reset(self):
        self.trips = []


class MotionDetector(TripWindowSensor):
    def __init__(self):
        super().__init__("motion", 2, 4)


class SeismicSensor(TripWindowSensor):
    def __init__(self):
        super().__init__("seismic", 1, 3)


class GlassBreakSensor(TripWindowSensor):
    def __init__(self):
        super().__init__("glass", 1, 2)


class BreachRecord:
    def __init__(self, timestamp, sensors):
        self.timestamp = timestamp
        self.sensors = tuple(sensors)

    def describe(self):
        return "t=%d breach via %s" % (self.timestamp, " + ".join(self.sensors))


class AlarmSiren:
    def __init__(self):
        self.alarm_count = 0
        self.log = []

    def activate(self, record):
        self.alarm_count += 1
        self.log.append(record.describe())


class SecurityReport:
    def __init__(self, alarm_count, counts):
        self.alarm_count = alarm_count
        self.counts = counts

    def most_active(self):
        if not self.counts:
            return ""
        return max(sorted(self.counts), key=lambda name: self.counts[name])

    def as_tuple(self):
        return (self.alarm_count, self.most_active())

    def headline(self):
        return "alarms=%d most active=%s" % (self.alarm_count, self.most_active())


def _monitor(events, breach_window=2):
    parser = EventParser()
    sensors = {}
    for sensor in (MotionDetector(), SeismicSensor(), GlassBreakSensor()):
        sensors[sensor.name] = sensor
    siren = AlarmSiren()
    counts = {}
    armed = {}
    for raw in events:
        event = parser.parse(raw)
        sensor = sensors.get(event.code)
        if sensor is None:
            raise ValueError("unknown sensor code: %s" % event.code)
        counts[sensor.name] = counts.get(sensor.name, 0) + 1
        if sensor.register(event.timestamp):
            armed = {n: t for n, t in armed.items() if event.timestamp - t <= breach_window}
            armed[sensor.name] = event.timestamp
            if len(armed) >= 2:
                siren.activate(BreachRecord(event.timestamp, sorted(armed)))
                armed = {}
                for tripped in sensors.values():
                    tripped.reset()
    return siren, counts


def secure(events):
    siren, counts = _monitor(events)
    report = SecurityReport(siren.alarm_count, counts)
    return report.as_tuple()


def format_report(events):
    siren, counts = _monitor(events)
    report = SecurityReport(siren.alarm_count, counts)
    return "\n".join([report.headline()] + siren.log)


if __name__ == "__main__":
    trips = ["motion", "motion", "seismic", "motion", "glass",
             "motion", "motion", "motion", "motion", "motion"]
    print(secure(trips))
    print(format_report(trips))

