class ThreadPattern:
    """A single pattern entry: a colour, a length in yards and a thread thickness."""

    def __init__(self, color, yards, thickness):
        self.color = color
        self.yards = yards
        self.thickness = thickness

    @classmethod
    def parse(cls, raw):
        if isinstance(raw, dict):
            color, yards, thickness = raw["color"], raw["yards"], raw.get("thickness", 1.0)
        else:
            color, yards, thickness = raw
        if yards <= 0:
            raise ValueError("pattern %r has no length to weave" % (color,))
        if thickness <= 0:
            raise ValueError("pattern %r has an impossible thread thickness" % (color,))
        return cls(str(color), float(yards), float(thickness))


class ThreadSpool:
    """Holds yardage and dispenses it, never giving more than it still carries."""

    def __init__(self, yardage):
        self.remaining = float(yardage)

    def dispense(self, yards):
        given = min(self.remaining, yards)
        self.remaining -= given
        return given


class ShuttleMechanism:
    """Carries the weft back and forth; each throw costs power."""

    def __init__(self, power_per_yard=0.05):
        self.power_per_yard = power_per_yard
        self.passes = 0
        self.power_used = 0.0

    def throw(self, yards, tension):
        self.passes += 1
        self.power_used += yards * tension * self.power_per_yard


class TensionSpring:
    """Tightens for thick thread, slackens for fine thread, and wears out doing so."""

    def __init__(self, base_tension=1.0):
        self.base_tension = base_tension
        self.wear = 0.0

    def adjust(self, thickness, yards):
        tension = self.base_tension * thickness
        self.wear += 0.002 * thickness * yards
        return tension

    def wear_percent(self):
        return min(100.0, self.wear * 100.0)


class WeaveReport:
    """Turns the loom's final state into a readable summary."""

    def __init__(self, yards, wear_percent, shuttle):
        self.yards = yards
        self.wear_percent = wear_percent
        self.shuttle = shuttle

    def summary(self):
        return ("Woven %.1f yards in %d shuttle passes (%.2f kW), spring wear %.1f%%"
                % (self.yards, self.shuttle.passes, self.shuttle.power_used, self.wear_percent))


def weave(patterns):
    threads = [ThreadPattern.parse(raw) for raw in patterns]
    spool = ThreadSpool(sum(thread.yards for thread in threads))
    shuttle = ShuttleMechanism()
    spring = TensionSpring()
    total_yards = 0.0
    for thread in threads:
        dispensed = spool.dispense(thread.yards)
        tension = spring.adjust(thread.thickness, dispensed)
        shuttle.throw(dispensed, tension)
        total_yards += dispensed
    return round(total_yards, 2), round(spring.wear_percent(), 2)


def main():
    patterns = [
        {"color": "indigo", "yards": 10, "thickness": 1.0},
        {"color": "saffron", "yards": 10, "thickness": 1.0},
        ("crimson", 10, 1.0),
        ("olive", 10, 1.0),
        ("slate", 10, 1.0),
    ]
    yards, wear = weave(patterns)
    shuttle = ShuttleMechanism()
    spring = TensionSpring()
    for thread in (ThreadPattern.parse(raw) for raw in patterns):
        shuttle.throw(thread.yards, spring.adjust(thread.thickness, thread.yards))
    report = WeaveReport(yards, wear, shuttle)
    print(report.summary())


if __name__ == "__main__":
    main()

