MAX_CART_CAPACITY = 4
WEAR_PER_DISPATCH = 1.0 / 3.0


class GroupRoster:
    """Validated rider groups, pre-split so no group exceeds a cart."""

    def __init__(self, raw_groups, capacity):
        self.capacity = capacity
        self.groups = []
        for value in raw_groups:
            size = int(value)
            if size <= 0:
                raise ValueError("group sizes must be positive, got %r" % (value,))
            while size > capacity:
                self.groups.append(capacity)
                size -= capacity
            self.groups.append(size)

    def __iter__(self):
        return iter(self.groups)


class SafetyHarness:
    def __init__(self, seats):
        self.seats = seats
        self.engaged = 0

    def engage(self, passengers):
        if self.engaged + passengers > self.seats:
            raise ValueError("not enough harnesses for %d passengers" % passengers)
        self.engaged += passengers

    def is_secure(self, passengers):
        return self.engaged == passengers


class PassengerCart:
    def __init__(self, capacity):
        self.capacity = capacity
        self.groups = []
        self.harness = SafetyHarness(capacity)

    @property
    def occupancy(self):
        return sum(self.groups)

    def can_accept(self, size):
        return self.occupancy + size <= self.capacity

    def board(self, size):
        self.groups.append(size)
        self.harness.engage(size)


class TrackBrake:
    def __init__(self):
        self.wear = 0.0

    def apply(self):
        self.wear = min(100.0, self.wear + WEAR_PER_DISPATCH)

    @property
    def wear_percent(self):
        return round(self.wear, 2)


class RideDispatcher:
    def __init__(self, brake):
        self.brake = brake
        self.dispatched = 0

    def dispatch(self, cart):
        if not cart.harness.is_secure(cart.occupancy):
            raise RuntimeError("harness check failed for cart of %d" % cart.occupancy)
        self.brake.apply()
        self.dispatched += 1


class RideReport:
    def __init__(self, carts, wear_percent):
        self.carts = carts
        self.wear_percent = wear_percent

    def summary(self):
        return "%d carts dispatched, brake wear %.2f%%" % (self.carts, self.wear_percent)


def operate(riders):
    roster = GroupRoster(riders, MAX_CART_CAPACITY)
    brake = TrackBrake()
    dispatcher = RideDispatcher(brake)
    cart = PassengerCart(MAX_CART_CAPACITY)
    for size in roster:
        if not cart.can_accept(size):
            dispatcher.dispatch(cart)
            cart = PassengerCart(MAX_CART_CAPACITY)
        cart.board(size)
    if cart.occupancy:
        dispatcher.dispatch(cart)
    return dispatcher.dispatched, brake.wear_percent


def main():
    carts, wear = operate([1, 3, 2, 4] * 5)
    report = RideReport(carts, wear)
    print(report.summary())


if __name__ == "__main__":
    main()

