class ComputeInstance:
    label = "compute instance"

    def hourly_cost(self):
        return 50


class StorageVolume:
    label = "storage volume"

    def hourly_cost(self):
        return 10


class DatabaseCluster:
    label = "database cluster"

    def hourly_cost(self):
        return 100


class LoadBalancer:
    label = "load balancer"

    def hourly_cost(self):
        return 25


class InvoiceLine:
    def __init__(self, label, unit_cost, quantity):
        self.label = label
        self.unit_cost = unit_cost
        self.quantity = quantity

    def subtotal(self):
        return self.unit_cost * self.quantity

    def render(self):
        return "{:<18} {:>3} x {:>4} = {:>5}".format(
            self.label, self.quantity, self.unit_cost, self.subtotal())


class BillingReport:
    def __init__(self, lines):
        self.lines = lines

    def total(self):
        return sum(line.subtotal() for line in self.lines)

    def render(self):
        body = [line.render() for line in self.lines]
        body.append("{:<18} {:>20}".format("TOTAL", self.total()))
        return "\n".join(body)


def make_resource(name):
    key = name.strip().lower()
    if key == "compute":
        return ComputeInstance()
    if key == "storage":
        return StorageVolume()
    if key == "database":
        return DatabaseCluster()
    if key == "balancer":
        return LoadBalancer()
    return None


def provision(requests):
    resources = []
    for name in requests:
        resource = make_resource(name)
        if resource is not None:
            resources.append(resource)
    return resources


def invoice(requests):
    return sum(resource.hourly_cost() for resource in provision(requests))


def build_report(requests):
    groups = {}
    for resource in provision(requests):
        groups.setdefault(resource.label, []).append(resource)
    lines = []
    for label, members in groups.items():
        lines.append(InvoiceLine(label, members[0].hourly_cost(), len(members)))
    return BillingReport(lines)


def main():
    requests = ["compute", "compute", "storage", "balancer", "quantum"]
    print(build_report(requests).render())
    print("hourly cost:", invoice(requests))


if __name__ == "__main__":
    main()

