class SplashPanel:
    """A full-page splash panel."""

    def width_cm(self):
        return 20


class DialoguePanel:
    """A narrow panel holding a single exchange of dialogue."""

    def width_cm(self):
        return 5


class WideEstablishingPanel:
    """A letterboxed panel used to establish a scene."""

    def width_cm(self):
        return 15


class TallActionPanel:
    """A vertical panel used for action beats."""

    def width_cm(self):
        return 10


class PanelFactory:
    """Turns panel type strings from a layout script into panel objects."""

    def __init__(self):
        self.builders = {
            "splash": SplashPanel,
            "dialogue": DialoguePanel,
            "wide": WideEstablishingPanel,
            "tall": TallActionPanel,
        }

    def build(self, name):
        key = name.strip().lower()
        if key not in self.builders:
            raise ValueError("unknown panel type: {!r}".format(name))
        return self.builders[key]()


class LayoutReport:
    """Collects the panels of one page and describes the resulting row."""

    def __init__(self, page_width):
        self.page_width = page_width
        self.panels = []

    def add(self, panel):
        self.panels.append(panel)

    def total_width(self):
        return sum(panel.width_cm() for panel in self.panels)

    def describe(self):
        widths = " + ".join(str(panel.width_cm()) for panel in self.panels)
        total = self.total_width()
        overflow = total - self.page_width
        line = "{} panels: {} = {} cm".format(len(self.panels), widths, total)
        if overflow > 0:
            line += " (overflows page by {} cm)".format(overflow)
        return line


def arrange(panels):
    factory = PanelFactory()
    return sum(factory.build(name).width_cm() for name in panels)


def main():
    factory = PanelFactory()
    for script in (["splash", "dialogue", "dialogue"], ["wide", "tall", "tall", "dialogue"]):
        report = LayoutReport(page_width=40)
        for name in script:
            report.add(factory.build(name))
        print(report.describe())
        print("arrange() ->", arrange(script))


if __name__ == "__main__":
    main()

