class AlphaParticle:
    NAME = "alpha"

    def energy_level(self):
        return 4


class BetaParticle:
    NAME = "beta"

    def energy_level(self):
        return 1


class GammaPhoton:
    NAME = "gamma"

    def energy_level(self):
        return 10


class NeutrinoBeam:
    NAME = "neutrino"

    def energy_level(self):
        return 0


class ParticleRegistry:
    def __init__(self):
        self._by_name = {}

    def register(self, particle_type):
        self._by_name[particle_type.NAME] = particle_type

    def create(self, raw_name):
        particle_type = self._by_name.get(str(raw_name).strip().lower())
        if particle_type is None:
            return None
        return particle_type()


class CollisionReport:
    def __init__(self):
        self.total = 0
        self.counts = {}
        self.ignored = []

    def record(self, name, energy):
        self.total += energy
        self.counts[name] = self.counts.get(name, 0) + 1

    def reject(self, raw_name):
        self.ignored.append(raw_name)

    def format_lines(self):
        lines = []
        for name in sorted(self.counts):
            lines.append("{0:<9} x{1}".format(name, self.counts[name]))
        if self.ignored:
            lines.append("ignored: " + ", ".join(repr(i) for i in self.ignored))
        lines.append("total energy: {0}".format(self.total))
        return lines


def build_registry():
    registry = ParticleRegistry()
    registry.register(AlphaParticle)
    registry.register(BetaParticle)
    registry.register(GammaPhoton)
    registry.register(NeutrinoBeam)
    return registry


def analyse(particles):
    registry = build_registry()
    report = CollisionReport()
    for raw_name in particles:
        particle = registry.create(raw_name)
        if particle is None:
            report.reject(raw_name)
        else:
            report.record(particle.NAME, particle.energy_level())
    return report


def simulate(particles):
    return analyse(particles).total


def main():
    beam = ["alpha", "beta", "Beta", "gamma", "neutrino", "quark"]
    for line in analyse(beam).format_lines():
        print(line)
    print("simulate(['alpha', 'beta', 'beta', 'gamma']) =",
          simulate(["alpha", "beta", "beta", "gamma"]))


if __name__ == "__main__":
    main()

