}


def make_module(name):
    factory = MODULE_TYPES.get(name.strip().lower())
    if factory is None:
        raise UnknownModuleError("unsupported module type: %r" % (name,))
    return factory()


def build(modules):
    return sum(make_module(name).duration_minutes() for name in modules)


