class MedicalExpense:
    """Out-of-pocket medical costs, deductible up to 500."""

    label = "Medical"
    limit = 500.0

    def apply_limit(self, amount):
        return min(amount, self.limit)


class EducationalExpense:
    """Tuition and course material costs, deductible up to 200."""

    label = "Educational"
    limit = 200.0

    def apply_limit(self, amount):
        return min(amount, self.limit)


class CharitableDonation:
    """Gifts to registered charities, deductible up to 1000."""

    label = "Charitable"
    limit = 1000.0

    def apply_limit(self, amount):
        return min(amount, self.limit)


class BusinessExpense:
    """Work-related costs, deductible up to 300."""

    label = "Business"
    limit = 300.0

    def apply_limit(self, amount):
        return min(amount, self.limit)


EXPENSE_TYPES = {
    "medical": MedicalExpense,
    "educational": EducationalExpense,
    "charitable": CharitableDonation,
    "business": BusinessExpense,
}


def build_expense(kind):
    try:
        expense_class = EXPENSE_TYPES[kind.strip().lower()]
    except (AttributeError, KeyError):
        raise ValueError("unknown expense type: {!r}".format(kind))
    return expense_class()


def analyze(expenses):
    return sum(build_expense(kind).limit for kind in expenses)


class ExpenseLedger:
    def __init__(self):
        self.entries = []

    def record(self, kind, amount):
        expense = build_expense(kind)
        allowed = expense.apply_limit(amount)
        self.entries.append((expense.label, amount, allowed))
        return allowed

    def total_allowed(self):
        return sum(entry[2] for entry in self.entries)


class DeductionReport:
    def __init__(self, ledger):
        self.ledger = ledger

    def render(self):
        rows = ["{:<12} claimed {:>8.2f}  allowed {:>8.2f}".format(*entry)
                for entry in self.ledger.entries]
        rows.append("{:<12} {:>26.2f}".format("TOTAL", self.ledger.total_allowed()))
        return "\n".join(rows)


def main():
    claims = [("medical", 700.0), ("charitable", 250.0), ("business", 300.0)]
    ledger = ExpenseLedger()
    for kind, amount in claims:
        ledger.record(kind, amount)
    report = DeductionReport(ledger)
    print(report.render())
    print("Maximum potential deduction:", analyze([kind for kind, _amount in claims]))
    print("Medical + charitable ceiling:", analyze(["medical", "charitable"]))


if __name__ == "__main__":
    main()

