import sys
from collections import OrderedDict


class ClayPottery:
    def base_value(self):
        return 5


class BronzeWeapon:
    def base_value(self):
        return 20


class GoldCoin:
    def base_value(self):
        return 50


class MarbleBust:
    def base_value(self):
        return 100


class ArtifactCatalog:
    def create(self, label):
        key = " ".join(label.strip().lower().split())
        if key in ("pottery", "clay pottery", "clay pot", "pot"):
            return ClayPottery()
        if key in ("weapon", "bronze weapon", "sword", "bronze sword"):
            return BronzeWeapon()
        if key in ("coin", "gold coin"):
            return GoldCoin()
        if key in ("bust", "marble bust", "statue", "marble statue"):
            return MarbleBust()
        return None


class AppraisalLine:
    def __init__(self, label, artifact, count):
        self.label = label
        self.unit_value = artifact.base_value()
        self.count = count

    def subtotal(self):
        return self.unit_value * self.count

    def describe(self):
        return "%-16s x%-3d %3dk each = %4dk" % (
            self.label, self.count, self.unit_value, self.subtotal())


class AppraisalReport:
    def __init__(self, lines, unmatched):
        self.lines = lines
        self.unmatched = unmatched

    def total(self):
        return sum(line.subtotal() for line in self.lines)

    def describe(self):
        rows = [line.describe() for line in self.lines]
        for label in self.unmatched:
            rows.append("%-16s unrecognised, valued at 0k" % label)
        rows.append("TOTAL: %dk" % self.total())
        return "\n".join(rows)


def build_report(artifacts):
    catalog = ArtifactCatalog()
    counts = OrderedDict()
    for label in artifacts:
        counts[label] = counts.get(label, 0) + 1
    lines = []
    unmatched = []
    for label, count in counts.items():
        artifact = catalog.create(label)
        if artifact is None:
            unmatched.append(label)
        else:
            line = AppraisalLine(label, artifact, count)
            lines.append(line)
    return AppraisalReport(lines, unmatched)


def appraise(artifacts):
    return build_report(artifacts).total()


def main(argv):
    artifacts = argv[1:] or ["pottery", "gold coin", "gold coin"]
    report = build_report(artifacts)
    print(report.describe())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

