        return 800


class CrownPlacement:
    label = "Crown placement"

    def service_cost(self):
        return 1000


SERVICE_TYPES = {
    "cleaning": RoutineCleaning,
    "filling": CavityFilling,
    "canal": RootCanal,
    "crown": CrownPlacement,
}


class InvoiceLineItem:
    def __init__(self, label, quantity, unit_cost):
        self.label = label
        self.quantity = quantity
        self.unit_cost = unit_cost

    def subtotal(self):
        return self.quantity * self.unit_cost

    def render(self):
        return "{:<18} x{:<3} {:>7.2f}".format(self.label, self.quantity, self.subtotal())


def build_services(services):
    built = []
    for name in services:
        service_class = SERVICE_TYPES.get(str(name).strip().lower())
        if service_class is not None:
            built.append(service_class())
    return built


def bill(services):
    return sum(service.service_cost() for service in build_services(services))


class VisitInvoice:
    def __init__(self, patient, services):
        self.patient = patient
        self.services = build_services(services)

    def total(self):
        return sum(service.service_cost() for service in self.services)

    def line_items(self):
        items = []
        for service in self.services:
            for item in items:
                if item.label == service.label:
                    item.quantity += 1
                    break
            else:
                items.append(InvoiceLineItem(service.label, 1, service.service_cost()))
        return items

    def render(self):
        rows = ["Invoice for {}".format(self.patient)]
        rows.extend(item.render() for item in self.line_items())
        rows.append("{:<23} {:>7.2f}".format("TOTAL", self.total()))
        return "\n".join(rows)


