    name = "velvet curtain"

    def cubic_volume(self):
        return 5


class SmokeMachine:
    name = "smoke machine"

    def cubic_volume(self):
        return 2


class TrickBox:
    name = "trick box"

    def cubic_volume(self):
        return 15


class PropCatalog:
    """Turns the script's prop keywords into stage equipment objects."""

    def build(self, prop):
        key = str(prop).strip().lower()
        if key.startswith("trap"):
            return TrapDoor()
        if key.startswith("curtain") or key.startswith("velvet"):
            return VelvetCurtain()
        if key.startswith("smoke"):
            return SmokeMachine()
        if key.startswith("trick"):
            return TrickBox()
        return None


class LoadManifest:
    """Collected equipment plus the space it claims in the truck."""

    def __init__(self):
        self.equipment = []

    def add(self, item):
        self.equipment.append(item)

    def total_volume(self):
        return sum(item.cubic_volume() for item in self.equipment)

    def lines(self):
        return ["%-15s %3d cu ft" % (item.name, item.cubic_volume())
                for item in self.equipment]


class StorageTruck:
    def __init__(self, capacity):
        self.capacity = capacity

    def remaining_after(self, volume):
        return self.capacity - volume


def build_manifest(props):
    catalog = PropCatalog()
    manifest = LoadManifest()
    for prop in props:
        item = catalog.build(prop)
        if item is not None:
            manifest.add(item)
    return manifest


def organize(props):
    return build_manifest(props).total_volume()


def format_report(props, capacity):
    manifest = build_manifest(props)
    truck = StorageTruck(capacity)
    volume = manifest.total_volume()
    report = manifest.lines()
    report.append("total %d cu ft, %d cu ft free"
                  % (volume, truck.remaining_after(volume)))
    return "\n".join(report)


def main():
    print(organize(["smoke machine", "trick box"]))
    print(format_report(["trap", "curtain", "fog juice", "trick box"], 40))


if __name__ == "__main__":
