class PollutionMonitor:
    label = "pollution monitor"

    def payload_size_kb(self):
        return 12


class TrafficCamera:
    label = "traffic camera"

    def payload_size_kb(self):
        return 200


class NoiseSensor:
    label = "noise sensor"

    def payload_size_kb(self):
        return 8


class WeatherStation:
    label = "weather station"

    def payload_size_kb(self):
        return 15


class UnknownSensorError(ValueError):
    def __init__(self, name):
        super().__init__("unsupported sensor type: {!r}".format(name))
        self.name = name


class BandwidthReport:
    def __init__(self):
        self.counts = {}
        self.total = 0

    def record(self, sensor):
        self.counts[sensor.label] = self.counts.get(sensor.label, 0) + 1
        self.total += sensor.payload_size_kb()

    def total_kb(self):
        return self.total

    def lines(self):
        return ["{:<18} x{:<3} {:>5} kB".format(label, count, count * build_sensor(label).payload_size_kb())
                for label, count in sorted(self.counts.items())]


class DataRateEstimate:
    def __init__(self, total_kb, interval_seconds):
        self.total_kb = total_kb
        self.interval_seconds = interval_seconds

    def megabits_per_second(self):
        return (self.total_kb * 8.0) / 1024.0 / self.interval_seconds


def build_sensor(name):
    key = "_".join(str(name).strip().lower().split())
    if key in ("pollution", "pollution_monitor"):
        return PollutionMonitor()
    if key in ("traffic", "traffic_camera"):
        return TrafficCamera()
    if key in ("noise", "noise_sensor"):
        return NoiseSensor()
    if key in ("weather", "weather_station"):
        return WeatherStation()
    raise UnknownSensorError(name)


def summarize(sensors):
    report = BandwidthReport()
    for name in sensors:
        report.record(build_sensor(name))
    return report


def poll(sensors):
    return summarize(sensors).total_kb()


def main():
    deployment = ["traffic camera", "noise sensor", "noise sensor",
                  "pollution", "weather station", "traffic"]
    report = summarize(deployment)
    for line in report.lines():
        print(line)
    print("total bandwidth per poll: {} kB".format(report.total_kb()))
    rate = DataRateEstimate(report.total_kb(), 60)
    print("sustained rate: {:.3f} Mbit/s".format(rate.megabits_per_second()))
    print("single traffic camera plus two noise sensors: {} kB".format(
        poll(["traffic camera", "noise sensor", "noise sensor"])))


if __name__ == "__main__":
    main()

