class MinimumLengthConstraint:
    def __init__(self, length):
        self.length = length

    def accepts(self, value):
        return len(value) >= self.length

    def describe(self):
        return "shorter than {} characters".format(self.length)


class MaximumLengthConstraint:
    def __init__(self, length):
        self.length = length

    def accepts(self, value):
        return len(value) <= self.length

    def describe(self):
        return "longer than {} characters".format(self.length)


class AllowedCharactersConstraint:
    def __init__(self, predicate_name):
        self.predicate_name = predicate_name

    def accepts(self, value):
        return bool(value) and all(getattr(ch, self.predicate_name)() for ch in value)

    def describe(self):
        return "contains characters that are not {}".format(self.predicate_name[2:])


class ForbiddenPrefixConstraint:
    def __init__(self, prefix):
        self.prefix = prefix

    def accepts(self, value):
        return not value.lower().startswith(self.prefix)

    def describe(self):
        return "starts with the forbidden prefix '{}'".format(self.prefix)


class ConstraintViolation:
    def __init__(self, value, reason):
        self.value = value
        self.reason = reason

    def render(self):
        return "rejected {!r}: {}".format(self.value, self.reason)


class ValidationReport:
    def __init__(self, accepted, violations):
        self.accepted = accepted
        self.violations = violations

    def render(self):
        lines = ["accepted: {}".format(", ".join(self.accepted) or "(none)")]
        lines.extend(violation.render() for violation in self.violations)
        return "\n".join(lines)


def build_constraints():
    minimum = MinimumLengthConstraint(8)
    maximum = MaximumLengthConstraint(20)
    alphanumeric = AllowedCharactersConstraint("isalnum")
    prefix = ForbiddenPrefixConstraint("admin")
    return [minimum, maximum, alphanumeric, prefix]


def inspect(inputs):
    constraints = build_constraints()
    accepted = []
    violations = []
    for value in inputs:
        failed = [c for c in constraints if not c.accepts(value)]
        if failed:
            violations.append(ConstraintViolation(value, failed[0].describe()))
        else:
            accepted.append(value)
    return ValidationReport(accepted, violations)


def validate(inputs):
    return inspect(inputs).accepted


