WORD_NUMBERS = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
}

TRUE_WORDS = {"true", "t", "yes", "y"}
FALSE_WORDS = {"false", "f", "no", "n"}


def parse_number(response):
    if isinstance(response, bool):
        return None
    if isinstance(response, int):
        return response
    if isinstance(response, str):
        text = response.strip().lower()
        if text in WORD_NUMBERS:
            return WORD_NUMBERS[text]
        try:
            return int(text)
        except ValueError:
            return None
    return None


def parse_boolean(response):
    if isinstance(response, bool):
        return response
    if isinstance(response, str):
        text = response.strip().lower()
        if text in TRUE_WORDS:
            return True
        if text in FALSE_WORDS:
            return False
    return None


class MultipleChoiceQuestion:
    def __init__(self, prompt, choices, correct):
        self.prompt = prompt
        self.choices = choices
        self.correct = correct.strip().lower()

    def is_correct(self, response):
        if not isinstance(response, str):
            return False
        return response.strip().lower() == self.correct


class TrueFalseQuestion:
    def __init__(self, prompt, correct):
        self.prompt = prompt
        self.correct = correct

    def is_correct(self, response):
        return parse_boolean(response) is self.correct


class NumericRatingQuestion:
    def __init__(self, prompt, required, low=1, high=10):
        self.prompt = prompt
        self.required = required
        self.low = low
        self.high = high

    def is_correct(self, response):
        value = parse_number(response)
        if value is None or not self.low <= value <= self.high:
            return False
        return value == self.required


class FreeTextQuestion:
    def __init__(self, prompt):
        self.prompt = prompt

    def is_correct(self, response):
        return isinstance(response, str) and bool(response.strip())


class ScoreLine:
    def __init__(self, index, responses, points, total):
        self.index = index
        self.responses = responses
        self.points = points
        self.total = total

    def render(self):
        shown = ", ".join(str(item) for item in self.responses)
        return "Set {0}: {1} -> {2}/{3}".format(
            self.index, shown, self.points, self.total)


class ScoreReport:
    def __init__(self, title):
        self.title = title
        self.lines = []

    def add(self, line):
        self.lines.append(line)

    def render(self):
        body = [self.title, "-" * len(self.title)]
        body.extend(line.render() for line in self.lines)
        return "\n".join(body)


def build_survey():
    favourite = MultipleChoiceQuestion(
        "Favourite colour?", ["red", "green", "blue"], "blue")
    agreement = TrueFalseQuestion("The survey was clear?", True)
    rating = NumericRatingQuestion("Rate us from 1 to 10", 5)
    feedback = FreeTextQuestion("Any comments?")
    return [favourite, agreement, rating, feedback]


def score(answers):
    questions = build_survey()
    totals = []
    for answer_set in answers:
        points = 0
        for question, response in zip(questions, answer_set):
            if question.is_correct(response):
                points += 1
        totals.append(points)
    return totals


def main():
    answers = [
        ("blue", "true", "five", "good job"),
        ("red", True, 5, ""),
        ("Blue", "no", 7, "   "),
    ]
    scores = score(answers)
    report = ScoreReport("Survey results")
    for index, (answer_set, points) in enumerate(zip(answers, scores), start=1):
        report.add(ScoreLine(index, answer_set, points, len(answer_set)))
    print(report.render())


if __name__ == "__main__":
    main()

