class ConstantNode:
    def __init__(self, value):
        self.value = value

    def evaluate(self):
        return self.value

    def describe(self):
        return str(self.value)


class AdditionNode:
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def evaluate(self):
        return self.left.evaluate() + self.right.evaluate()

    def describe(self):
        return "(%s + %s)" % (self.left.describe(), self.right.describe())


class MultiplicationNode:
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def evaluate(self):
        return self.left.evaluate() * self.right.evaluate()

    def describe(self):
        return "(%s * %s)" % (self.left.describe(), self.right.describe())


class MaximumNode:
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def evaluate(self):
        return max(self.left.evaluate(), self.right.evaluate())

    def describe(self):
        return "max(%s, %s)" % (self.left.describe(), self.right.describe())


class ProgramParser:
    def __init__(self, source):
        self.source = source

    def parse(self):
        instructions = []
        for line in self.source.splitlines():
            parts = line.split()
            if not parts:
                continue
            opcode = parts[0]
            instructions.append((opcode,) + tuple(int(token) for token in parts[1:]))
        return instructions


def build_tree(instructions):
    nodes = []
    for position, instruction in enumerate(instructions):
        opcode, operands = instruction[0], instruction[1:]
        if opcode == "const":
            node = ConstantNode(operands[0])
        else:
            for index in operands:
                if not 0 <= index < position:
                    raise ValueError("instruction %d references node %d" % (position, index))
            left, right = nodes[operands[0]], nodes[operands[1]]
            if opcode == "add":
                node = AdditionNode(left, right)
            elif opcode == "mul":
                node = MultiplicationNode(left, right)
            elif opcode == "max":
                node = MaximumNode(left, right)
            else:
                raise ValueError("unknown opcode %r" % opcode)
        nodes.append(node)
    if not nodes:
        raise ValueError("no instructions to evaluate")
    return nodes[-1]


def evaluate(instructions):
    return build_tree(instructions).evaluate()


def main():
    parser = ProgramParser(
        "const 5\nconst 10\nadd 0 1\nconst 3\nmul 2 3\nconst 40\nmax 4 5\n"
    )
    instructions = parser.parse()
    root = build_tree(instructions)
    print("%s = %d" % (root.describe(), root.evaluate()))
    print(evaluate([("const", 5), ("const", 10), ("add", 0, 1)]))


if __name__ == "__main__":
    main()

