class UnknownAssetType(ValueError):
    """Raised when a portfolio entry names an asset type we cannot appraise."""


class CashAccount:
    def __init__(self, balance):
        self.balance = float(balance)

    def describe(self):
        return "Cash account"

    def current_value(self):
        return self.balance


class StockHolding:
    def __init__(self, shares, price):
        self.shares = float(shares)
        self.price = float(price)

    def describe(self):
        return "Stock holding ({:g} shares @ {:.2f})".format(self.shares, self.price)

    def current_value(self):
        return self.shares * self.price


class RealEstateProperty:
    APPRECIATION = 0.035

    def __init__(self, original_value):
        self.original_value = float(original_value)

    def describe(self):
        return "Real estate (+{:.1f}%)".format(self.APPRECIATION * 100)

    def current_value(self):
        return self.original_value * (1.0 + self.APPRECIATION)


class GovernmentBond:
    def __init__(self, principal, interest):
        self.principal = float(principal)
        self.interest = float(interest)

    def describe(self):
        return "Government bond (principal {:.2f})".format(self.principal)

    def current_value(self):
        return self.principal + self.interest


def build_asset(spec):
    kind, numbers = spec[0].strip().lower(), spec[1:]
    if kind == "cash":
        return CashAccount(*numbers)
    if kind == "stock":
        return StockHolding(*numbers)
    if kind == "real_estate":
        return RealEstateProperty(*numbers)
    if kind == "bond":
        return GovernmentBond(*numbers)
    raise UnknownAssetType("cannot appraise asset of type {!r}".format(spec[0]))


def build_portfolio(portfolio):
    return [build_asset(spec) for spec in portfolio]


class PortfolioReport:
    def __init__(self, assets):
        self.assets = assets

    def render(self):
        lines = []
        for asset in self.assets:
            lines.append("{:<40}{:>14,.2f}".format(asset.describe(), asset.current_value()))
        total = sum(asset.current_value() for asset in self.assets)
        lines.append("{:<40}{:>14,.2f}".format("TOTAL", total))
        return "\n".join(lines)


def appraise(portfolio):
    return sum(asset.current_value() for asset in build_portfolio(portfolio))


def main():
    holdings = [
        ("cash", 1000),
        ("bond", 500, 50),
        ("stock", 40, 12.5),
        ("real_estate", 250000),
    ]
    report = PortfolioReport(build_portfolio(holdings))
    print(report.render())
    print("appraise() =", appraise(holdings))
    print("appraise() =", appraise([("cash", 1000), ("bond", 500, 50)]))


if __name__ == "__main__":
