class PreparationStep:
    """Chopping and measuring: five minutes for every ingredient."""

    label = "prep"

    def __init__(self, ingredient_count):
        self.ingredient_count = ingredient_count

    def estimate_minutes(self):
        return 5 * self.ingredient_count

    def describe(self):
        return "prep of {} ingredient(s)".format(self.ingredient_count)


class RestingStep:
    """Dough or meat resting: exactly the requested time."""

    label = "rest"

    def __init__(self, rest_minutes):
        self.rest_minutes = rest_minutes

    def estimate_minutes(self):
        return self.rest_minutes

    def describe(self):
        return "resting for {} min".format(self.rest_minutes)


class StovetopBoilingStep:
    """Boiling on the stove: ten minutes to reach a boil, then the boil itself."""

    label = "boil"

    def __init__(self, boil_minutes):
        self.boil_minutes = boil_minutes

    def estimate_minutes(self):
        return 10 + self.boil_minutes

    def describe(self):
        return "boiling for {} min (+10 min heat-up)".format(self.boil_minutes)


class OvenBakingStep:
    """Baking: fifteen minutes of preheating plus the bake time."""

    label = "bake"

    def __init__(self, bake_minutes):
        self.bake_minutes = bake_minutes

    def estimate_minutes(self):
        return 15 + self.bake_minutes

    def describe(self):
        return "baking for {} min (+15 min preheat)".format(self.bake_minutes)


class RecipeSchedule:
    """An ordered sequence of step objects that can be totalled or listed."""

    def __init__(self, steps):
        self.steps = steps

    def total_minutes(self):
        return sum(step.estimate_minutes() for step in self.steps)

    def breakdown(self):
        return ["{:>3} min  {}".format(step.estimate_minutes(), step.describe())
                for step in self.steps]


STEP_KINDS = {
    PreparationStep.label: PreparationStep,
    RestingStep.label: RestingStep,
    StovetopBoilingStep.label: StovetopBoilingStep,
    OvenBakingStep.label: OvenBakingStep,
}


def build_schedule(recipe):
    steps = []
    for kind, amount in recipe:
        if kind not in STEP_KINDS:
            raise ValueError("unknown step kind: {!r}".format(kind))
        if amount < 0:
            raise ValueError("negative quantity for step {!r}".format(kind))
        steps.append(STEP_KINDS[kind](amount))
    return RecipeSchedule(steps)


def parse(recipe):
    return int(build_schedule(recipe).total_minutes())


def report(recipe):
    schedule = build_schedule(recipe)
    lines = schedule.breakdown()
    lines.append("{:>3} min  total".format(schedule.total_minutes()))
    return "\n".join(lines)


def main():
    pasta = [("prep", 4), ("boil", 5), ("rest", 3)]
    bread = [("prep", 6), ("rest", 90), ("bake", 40)]
    for name, recipe in (("Pasta", pasta), ("Bread", bread)):
        print(name, "->", parse(recipe), "minutes")
        print(report(recipe))
        print()


if __name__ == "__main__":
    main()

