    def name(self):
        return "signal delay -%d" % self.amount

    def apply(self, signal):
        return signal - self.amount


class distortion_effect:
    def __init__(self, ceiling):
        self.ceiling = ceiling

    @property
    def name(self):
        return "distortion cap %d" % self.ceiling

    def apply(self, signal):
        return self.ceiling if signal > self.ceiling else signal


class noise_reduction_effect:
    def __init__(self, floor):
        self.floor = floor

    @property
    def name(self):
        return "noise reduction floor %d" % self.floor

    def apply(self, signal):
        return 0 if signal < self.floor else signal


class effect_specification:
    def __init__(self, kind, parameter):
        if not isinstance(parameter, int) or isinstance(parameter, bool):
            raise TypeError("effect parameter must be an integer: %r" % (parameter,))
        self.kind = kind
        self.parameter = parameter

    def build(self):
        if self.kind == "volume_boost":
            return volume_boost_effect(self.parameter)
        if self.kind == "signal_delay":
            return signal_delay_effect(self.parameter)
        if self.kind == "distortion":
            return distortion_effect(self.parameter)
        if self.kind == "noise_reduction":
            return noise_reduction_effect(self.parameter)
        raise ValueError("unknown effect kind: %r" % (self.kind,))


class effect_log_entry:
    def __init__(self, name, before, after):
        self.name = name
        self.before = before
        self.after = after

    def describe(self):
        return "%-24s %6d -> %6d" % (self.name, self.before, self.after)


class effect_chain_runner:
    def __init__(self, signal):
        self.signal = signal
        self.log = []

    def run(self, effect_tuples):
        for kind, parameter in effect_tuples:
            specification = effect_specification(kind, parameter)
            effect = specification.build()
            previous = self.signal
            self.signal = effect.apply(previous)
            self.log.append(effect_log_entry(effect.name, previous, self.signal))
        return self.signal


def process(audio):
    signal, effect_tuples = audio
    runner = effect_chain_runner(signal)
    return runner.run(effect_tuples)


def render_report(audio):
    signal, effect_tuples = audio
    runner = effect_chain_runner(signal)
    final = runner.run(effect_tuples)
    lines = ["initial signal: %d" % signal]
    lines.extend(entry.describe() for entry in runner.log)
    lines.append("final signal:   %d" % final)
    return "\n".join(lines)


def main():
    print(process((10, [("volume_boost", 2), ("signal_delay", 5)])))
    print(render_report((7, [("volume_boost", 4), ("distortion", 20),
                             ("signal_delay", 18), ("noise_reduction", 5)])))


if __name__ == "__main__":
    main()

