        self.descriptions = descriptions

    def counts(self):
        tally = {}
        for text in self.descriptions:
            kind = text.rsplit(" ", 1)[0]
            tally[kind] = tally.get(kind, 0) + 1
        return tally

    def render(self):
        lines = []
        for kind, number in sorted(self.counts().items()):
            lines.append("{}: {}".format(kind, number))
        return "\n".join(lines)


def tokenize(code):
