class ShipmentRequest:
    """A validated (delivery type, weight) pair taken from the raw input."""

    def __init__(self, raw_entry):
        try:
            service_name, weight = raw_entry
        except (TypeError, ValueError):
            raise ValueError("each package must be a (type, weight) tuple: %r" % (raw_entry,))
        self.service_name = str(service_name).strip().lower()
        self.weight = float(weight)
        if self.weight < 0:
            raise ValueError("weight cannot be negative: %r" % (weight,))


class StandardGroundDelivery:
    label = "standard ground"

    def __init__(self, weight):
        self.weight = weight

    def cost(self):
        return 2.0 * self.weight


class OvernightAirDelivery:
    label = "overnight air"

    def __init__(self, weight):
        self.weight = weight

    def cost(self):
        return 5.0 * self.weight + 10.0


class RefrigeratedDelivery:
    label = "refrigerated"

    def __init__(self, weight):
        self.weight = weight

    def cost(self):
        return 3.0 * self.weight + 20.0


class OversizedFreightDelivery:
    label = "oversized freight"

    def __init__(self, weight):
        self.weight = weight

    def cost(self):
        return 50.0 + 1.0 * self.weight


SERVICES = {
    "standard": StandardGroundDelivery,
    "ground": StandardGroundDelivery,
    "overnight": OvernightAirDelivery,
    "air": OvernightAirDelivery,
    "refrigerated": RefrigeratedDelivery,
    "oversized": OversizedFreightDelivery,
    "freight": OversizedFreightDelivery,
}


def build_deliveries(packages):
    deliveries = []
    for raw_entry in packages:
        request = ShipmentRequest(raw_entry)
        service_class = SERVICES.get(request.service_name)
        if service_class is None:
            raise ValueError("unknown delivery type: %r" % (request.service_name,))
        deliveries.append(service_class(request.weight))
    return deliveries


class DeliveryManifest:
    """Collects the per-package costs so they can be totalled and printed."""

    def __init__(self, deliveries):
        self.lines = [(d.label, d.weight, d.cost()) for d in deliveries]

    def total(self):
        return sum(cost for _label, _weight, cost in self.lines)

    def report(self):
        rows = ["%-18s %7.1f lb  $%8.2f" % line for line in self.lines]
        rows.append("%-18s %10s  $%8.2f" % ("TOTAL", "", self.total()))
        return "\n".join(rows)


def route(packages):
    manifest = DeliveryManifest(build_deliveries(packages))
    return manifest.total()


def main():
    shipment = [
        ("standard", 10),
        ("overnight", 10),
        ("refrigerated", 12.5),
        ("oversized", 300),
    ]
    manifest = DeliveryManifest(build_deliveries(shipment))
    print(manifest.report())
    print("route() total: $%.2f" % route(shipment))


if __name__ == "__main__":
    main()

