class FieldSpec:
    """Validated description of one form element taken from the input tuples."""

    KINDS = ("text", "password", "textarea", "select")

    def __init__(self, kind, name, choices=None):
        if kind not in self.KINDS:
            raise ValueError("unknown field kind: %r" % (kind,))
        if not name:
            raise ValueError("field of kind %r needs a name" % (kind,))
        if kind == "select" and not choices:
            raise ValueError("drop down %r needs at least one choice" % (name,))
        self.kind = kind
        self.name = name
        self.choices = list(choices) if choices else []


class SingleLineTextInput:
    def __init__(self, name):
        self.name = name

    def render(self):
        return '<input type="text" name="%s" />' % html.escape(self.name, quote=True)


class MaskedPasswordInput:
    def __init__(self, name):
        self.name = name

    def render(self):
        return '<input type="password" name="%s" />' % html.escape(self.name, quote=True)


