class SelectFieldClause:
    def __init__(self, fields):
        if not fields:
            raise ValueError("a select clause needs at least one field")
        self.fields = list(fields)

    def generate(self):
        return "select " + ", ".join(self.fields)


class FromTableClause:
    def __init__(self, table):
        if not table:
            raise ValueError("a from clause needs a table name")
        self.table = table

    def generate(self):
        return "from " + self.table


class WhereConditionClause:
    def __init__(self, conditions):
        if not conditions:
            raise ValueError("a where clause needs at least one condition")
        self.conditions = list(conditions)

    def generate(self):
        return "where " + " and ".join(self.conditions)


class OrderByClause:
    def __init__(self, column, direction="asc"):
        if not column:
            raise ValueError("an order by clause needs a column name")
        normalized = direction.lower()
        if normalized not in ("asc", "desc"):
            raise ValueError("unknown sort direction: " + direction)
        self.column = column
        self.direction = normalized

    def generate(self):
        return "order by " + self.column + " " + self.direction


class QueryStatement:
    def __init__(self, clauses):
        self.clauses = list(clauses)

    def render(self):
        return " ".join(clause.generate() for clause in self.clauses)


def make_clause(component):
    kind = component[0].strip().lower()
    parts = [str(part).strip() for part in component[1:]]
    if kind == "select":
        clause = SelectFieldClause(parts)
    elif kind == "from":
        clause = FromTableClause(parts[0] if parts else "")
    elif kind == "where":
        clause = WhereConditionClause(parts)
    elif kind == "order by":
        clause = OrderByClause(*(parts or [""]))
    else:
        raise ValueError("unknown clause type: " + component[0])
    return clause


def build(components):
    clauses = []
    for component in components:
        clauses.append(make_clause(component))
    statement = QueryStatement(clauses)
    return statement.render()


def main():
    print(build([("select", "id", "name"), ("from", "users")]))
    print(build([
        ("select", "customer", "total"),
        ("from", "orders"),
        ("where", "total > 100", "shipped = 0"),
        ("order by", "total", "desc"),
    ]))


if __name__ == "__main__":
    main()

