class CalorieRule:
    """Calorie cost of one unit of a single ingredient type."""

    def __init__(self, name, calories_per_unit):
        self.name = name
        self.calories_per_unit = calories_per_unit

    def calories_for(self, quantity):
        return self.calories_per_unit * quantity


class RuleCatalog:
    """Lookup table of the calorie rules the sundae menu allows."""

    def __init__(self, table):
        self.rules = {}
        for name, per_unit in table:
            self.rules[name] = CalorieRule(name, per_unit)

    def rule_for(self, name):
        try:
            return self.rules[name]
        except KeyError:
            raise ValueError("unknown ingredient: {!r}".format(name))


class DessertComponent:
    """One ingredient line of a sundae: a rule plus how many units were added."""

    def __init__(self, rule, quantity):
        self.rule = rule
        self.quantity = quantity

    @property
    def calories(self):
        return self.rule.calories_for(self.quantity)

    def label(self):
        return "{} x{}".format(self.rule.name, self.quantity)


class ReceiptLine:
    """A label/value pair rendered as a fixed-width receipt row."""

    def __init__(self, label, calories):
        self.label = label
        self.calories = calories

    def render(self, width):
        return "{}{:>{}} kcal".format(self.label, self.calories, width - len(self.label))


class SundaeOrder:
    """A collection of dessert components making up one sundae."""

    def __init__(self, components):
        self.components = components

    def total_calories(self):
        return sum(component.calories for component in self.components)

    def receipt(self, width=28):
        rows = [ReceiptLine(c.label(), c.calories).render(width) for c in self.components]
        rows.append(ReceiptLine("TOTAL", self.total_calories()).render(width))
        return "\n".join(rows)


MENU = RuleCatalog((("vanilla", 200), ("syrup", 150), ("sprinkles", 20), ("cherry", 10)))


def parse_component(entry):
    parts = entry.split()
    if len(parts) != 2:
        raise ValueError("expected '<ingredient> <quantity>', got {!r}".format(entry))
    name, raw_quantity = parts[0].lower(), parts[1]
    if not raw_quantity.lstrip("+").isdigit():
        raise ValueError("invalid quantity: {!r}".format(raw_quantity))
    return DessertComponent(MENU.rule_for(name), int(raw_quantity))


def build_order(ingredients):
    return SundaeOrder([parse_component(entry) for entry in ingredients])


def scoop(ingredients):
    return int(build_order(ingredients).total_calories())


def main():
    deluxe = ["vanilla 3", "syrup 2", "sprinkles 4", "cherry 2"]
    print(build_order(deluxe).receipt())
    print("total calories:", scoop(deluxe))


if __name__ == "__main__":
    main()

