class MoveCommand:
    """A parsed instruction: an action keyword plus the square or side it targets."""

    def __init__(self, action, target):
        self.action = action
        self.target = target


class PawnMove:
    def __init__(self, target):
        self.target = target

    def energy(self):
        return 1

    def describe(self):
        return "pawn advances to " + self.target


class KnightJump:
    def __init__(self, target):
        self.target = target

    def energy(self):
        return 3

    def describe(self):
        return "knight jumps to " + self.target


class CastleAction:
    def __init__(self, side):
        self.side = side

    def energy(self):
        return 5

    def describe(self):
        return "castles " + self.side


class EnPassantCapture:
    def __init__(self, target):
        self.target = target

    def energy(self):
        return 4

    def describe(self):
        return "captures en passant on " + self.target


class UnknownManeuver:
    def __init__(self, action):
        self.action = action

    def energy(self):
        return 0

    def describe(self):
        return "unrecognized action " + repr(self.action)


class EnergyReport:
    def __init__(self):
        self.entries = []

    def add(self, maneuver):
        self.entries.append((maneuver.describe(), maneuver.energy()))

    def total(self):
        return sum(cost for _, cost in self.entries)

    def render(self):
        lines = ["%-34s %d" % entry for entry in self.entries]
        lines.append("%-34s %d" % ("TOTAL", self.total()))
        return "\n".join(lines)


def parse_move(line):
    action, _, target = line.strip().partition(" ")
    return MoveCommand(action.lower(), target.strip())


def build_maneuver(command):
    if command.action == "pawn":
        return PawnMove(command.target)
    if command.action == "knight":
        return KnightJump(command.target)
    if command.action == "castle":
        return CastleAction(command.target or "kingside")
    if command.action == "enpassant":
        return EnPassantCapture(command.target)
    return UnknownManeuver(command.action)


def validate(moves):
    total = 0
    for line in moves:
        command = parse_move(line)
        total += build_maneuver(command).energy()
    return total


def main():
    sequence = ["pawn e4", "knight f3", "castle kingside", "enpassant d6", "teleport h8"]
    report = EnergyReport()
    for line in sequence:
        report.add(build_maneuver(parse_move(line)))
    print(report.render())
    print("validate() ->", validate(sequence))
    print("validate(['pawn e4', 'knight f3']) ->", validate(["pawn e4", "knight f3"]))


if __name__ == "__main__":
    main()

