class score_adjustment:
    """A signed change applied to a base score: positive bonus, negative deduction."""

    def __init__(self, amount):
        self.amount = amount

    def applied_to(self, base_score):
        return base_score + self.amount

    def describe(self):
        kind = "bonus" if self.amount >= 0 else "deduction"
        return "%s %.1f" % (kind, abs(self.amount))


class routine_entry:
    """A single parsed routine: apparatus key plus the judged base score."""

    def __init__(self, apparatus, base_score):
        self.apparatus = apparatus
        self.base_score = base_score


class apparatus_rule:
    """Apparatus specific adjustment, selected by any of the accepted names."""

    def __init__(self, label, aliases, amount):
        self.label = label
        self.aliases = aliases
        self.adjustment = score_adjustment(amount)

    def matches(self, apparatus):
        return apparatus in self.aliases

    def score(self, entry):
        return self.adjustment.applied_to(entry.base_score)


class apparatus_rule_book:
    """Resolves an apparatus name to the rule that governs it."""

    def __init__(self, rules):
        self.rules = rules

    def resolve(self, apparatus):
        for rule in self.rules:
            if rule.matches(apparatus):
                return rule
        raise ValueError("unknown apparatus: %r" % apparatus)


class adjusted_routine:
    """One routine after its rule has been applied."""

    def __init__(self, label, base_score, adjusted_score, note):
        self.label = label
        self.base_score = base_score
        self.adjusted_score = adjusted_score
        self.note = note

    def render(self):
        return "%-15s %6.2f -> %6.2f  (%s)" % (
            self.label, self.base_score, self.adjusted_score, self.note)


class routine_score_report:
    """Per routine adjusted scores together with the all around total."""

    def __init__(self):
        self.rows = []

    def add(self, rule, entry):
        row = adjusted_routine(rule.label, entry.base_score,
                              rule.score(entry), rule.adjustment.describe())
        self.rows.append(row)

    def total(self):
        return round(sum(row.adjusted_score for row in self.rows), 1)

    def render(self):
        lines = [row.render() for row in self.rows]
        lines.append("%-15s %6s    %6.1f" % ("all around", "", self.total()))
        return "\n".join(lines)


def parse_routine(text):
    parts = text.split()
    if len(parts) < 2:
        raise ValueError("routine needs an apparatus and a base score: %r" % text)
    try:
        base = float(parts[-1])
    except ValueError:
        raise ValueError("base score is not a number: %r" % text)
    entry = routine_entry(" ".join(parts[:-1]).lower(), base)
    return entry


def build_rule_book():
    vault_rule = apparatus_rule("vault", {"vault", "vt"}, 0.5)
    bars_rule = apparatus_rule("uneven bars", {"bars", "uneven bars", "ub"}, -0.2)
    beam_rule = apparatus_rule("balance beam", {"beam", "balance beam", "bb"}, -0.1)
    floor_rule = apparatus_rule("floor exercise", {"floor", "floor exercise", "fx"}, 0.3)
    return apparatus_rule_book([vault_rule, bars_rule, beam_rule, floor_rule])


def build_report(routines):
    rule_book = build_rule_book()
    report = routine_score_report()
    for text in routines:
        entry = parse_routine(text)
        report.add(rule_book.resolve(entry.apparatus), entry)
    return report


def score(routines):
    return build_report(routines).total()


def main():
    meet = ["vault 15.0", "bars 14.8", "beam 14.1", "floor 14.6"]
    print(build_report(meet).render())
    print("short meet:", score(["vault 15.0", "beam 14.1"]))


if __name__ == "__main__":
    main()

