    def footprint(self, quantity):
        return self.kg_per_unit * quantity


class ConcreteCalculator:
    label = "concrete"
    kg_per_unit = 200.0

    def footprint(self, quantity):
        return self.kg_per_unit * quantity


class TimberCalculator:
    label = "timber"
    kg_per_unit = -10.0

    def footprint(self, quantity):
        return self.kg_per_unit * quantity


class SteelCalculator:
    label = "steel"
    kg_per_unit = 500.0

    def footprint(self, quantity):
        return self.kg_per_unit * quantity


class ReportRow:
    def __init__(self, entry, footprint):
        self.entry = entry
        self.footprint = footprint

    def render(self):
        return "{:<10}{:>8.2f} units{:>12.1f} kg".format(
            self.entry.name, self.entry.quantity, self.footprint)


class FootprintReport:
    def __init__(self, rows):
        self.rows = rows

    def total(self):
        return float(sum(row.footprint for row in self.rows))

    def render(self):
        lines = [row.render() for row in self.rows]
        lines.append("{:<10}{:>26.1f} kg".format("TOTAL", self.total()))
        return "\n".join(lines)


def parse_entry(line):
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected '<material> <quantity>', got %r" % line)
    name, raw_quantity = parts
    try:
        quantity = float(raw_quantity)
    except ValueError:
        raise ValueError("quantity is not a number: %r" % raw_quantity)
    if quantity < 0:
        raise ValueError("quantity must not be negative: %r" % raw_quantity)
    return MaterialEntry(name.lower(), quantity)


def make_calculator(name):
    if name == "brick":
        return BrickCalculator()
    if name == "concrete":
        return ConcreteCalculator()
    if name == "timber":
        return TimberCalculator()
    if name == "steel":
        return SteelCalculator()
    raise ValueError("unknown material: %r" % name)


def tally(materials):
    rows = []
    for line in materials:
        entry = parse_entry(line)
        calculator = make_calculator(entry.name)
        rows.append(ReportRow(entry, calculator.footprint(entry.quantity)))
    return rows


def build(materials):
    report = FootprintReport(tally(materials))
    return report.total()


def format_report(materials):
    report = FootprintReport(tally(materials))
    return report.render()


