BASE_ASSEMBLY_HOURS = 20


class ComplicationSpec:
    """A single requested complication with its complexity multiplier."""

    def __init__(self, name, complexity):
        self.name = name
        self.complexity = complexity


class ComplicationRule:
    """Hourly cost of one complication before the complexity multiplier."""

    def __init__(self, name, base_hours):
        self.name = name
        self.base_hours = base_hours

    def hours_for(self, spec):
        return self.base_hours * spec.complexity


class ComplicationCatalog:
    """Look-up table of the complications this workshop can assemble."""

    def __init__(self):
        self.rules = {}
        for rule in self._build_rules():
            self.rules[rule.name] = rule

    @staticmethod
    def _build_rules():
        chronograph = ComplicationRule("chronograph", 12)
        moonphase = ComplicationRule("moonphase", 8)
        calendar = ComplicationRule("calendar", 15)
        tourbillon = ComplicationRule("tourbillon", 50)
        return [chronograph, moonphase, calendar, tourbillon]

    def rule_for(self, spec):
        if spec.name not in self.rules:
            raise ValueError("unknown complication: %s" % spec.name)
        return self.rules[spec.name]


class AssemblyEstimate:
    """Base time plus the per-complication times of one watch."""

    def __init__(self, base_hours):
        self.base_hours = base_hours
        self.entries = []

    def add(self, spec, hours):
        self.entries.append((spec, hours))

    def total_hours(self):
        return int(self.base_hours + sum(hours for _, hours in self.entries))


class EstimateLine:
    """One formatted row of the printed estimate."""

    def __init__(self, label, hours):
        self.label = label
        self.hours = hours

    def render(self):
        return "{:<14}{:>6} h".format(self.label, self.hours)


def parse_feature(text):
    parts = text.split()
    if len(parts) != 2:
        raise ValueError("malformed feature: %r" % text)
    return ComplicationSpec(parts[0].lower(), int(parts[1]))


def estimate(features):
    catalog = ComplicationCatalog()
    result = AssemblyEstimate(BASE_ASSEMBLY_HOURS)
    for text in features:
        spec = parse_feature(text)
        result.add(spec, catalog.rule_for(spec).hours_for(spec))
    return result


def construct(features):
    return estimate(features).total_hours()


def report(features):
    result = estimate(features)
    lines = [EstimateLine("base", result.base_hours).render()]
    for spec, hours in result.entries:
        row = EstimateLine("%s x%d" % (spec.name, spec.complexity), hours)
        lines.append(row.render())
    lines.append(EstimateLine("TOTAL", result.total_hours()).render())
    return "\n".join(lines)


def main():
    order = ["moonphase 2", "tourbillon 1"]
    print(report(order))
    print("construct ->", construct(order))
    print("construct ->", construct(["chronograph 3", "calendar 2", "moonphase 1"]))


if __name__ == "__main__":
    main()

