    def __init__(self, notes, total):
        self.notes = notes
        self.total = total

    def render(self):
        lines = [str(note) for note in self.notes]
        lines.append("total: %d/100" % self.total)
        return "\n".join(lines)


def build_panel():
    visual = visual_reviewer()
    aroma = aroma_reviewer()
    palate = palate_reviewer()
    finish = finish_reviewer()
    return {r.category: r for r in (visual, aroma, palate, finish)}


