        self.value = value

    @classmethod
    def parse(cls, text):
        parts = text.split()
        if len(parts) != 2:
            raise ValueError("malformed effect description: %r" % text)
        name, raw = parts
        try:
            value = float(raw)
        except ValueError:
            raise ValueError("parameter of %r is not numeric" % text)
        return cls(name.lower(), value)


class DistortionNode:
    def __init__(self, spec):
