def build_node(spec):
    if spec.name == "distortion":
        return DistortionNode(spec)
    if spec.name == "delay":
        return DelayNode(spec)
    if spec.name == "reverb":
        return ReverbNode(spec)
    if spec.name == "chorus":
        return ChorusNode(spec)
    raise ValueError("unknown pedal: %r" % spec.name)


class SignalChain:
    def __init__(self, descriptions):
        self.nodes = [build_node(EffectSpec.parse(text)) for text in descriptions]

    def total_latency(self):
        return float(sum(node.latency() for node in self.nodes))


