        return 2.0


class DeploymentReport:
    def __init__(self, elements: list, total: float):
        self.elements = elements
        self.total = total

    def render(self) -> str:
        rows = ["{:<10} {:>8.2f}".format(e.label, e.drag()) for e in self.elements]
        rows.append("{:<10} {:>8.2f}".format("TOTAL", self.total))
        return "\n".join(rows)


def parse_spec(text: str) -> ComponentSpec:
    parts = text.split()
    if not 1 <= len(parts) <= 2:
        raise ValueError("malformed component entry: {!r}".format(text))
