class FormationReading:
    """A single line of survey notes: a formation name and its size in centimetres."""

    def __init__(self, text):
        parts = text.split()
        if len(parts) != 2:
            raise ValueError("cannot read formation entry: %r" % text)
        self.kind = parts[0].strip().lower()
        try:
            self.measure = float(parts[1])
        except ValueError:
            raise ValueError("bad measurement in entry: %r" % text)
        if self.measure < 0:
            raise ValueError("negative measurement in entry: %r" % text)


class StalactiteModel:
    kind = "stalactite"
    centuries_per_cm = 2

    def estimate(self, measure):
        return int(measure * self.centuries_per_cm)


class StalagmiteModel:
    kind = "stalagmite"
    centuries_per_cm = 3

    def estimate(self, measure):
        return int(measure * self.centuries_per_cm)


class ColumnModel:
    kind = "column"
    centuries_per_cm = 4

    def estimate(self, measure):
        return int(measure * self.centuries_per_cm)


class FlowstoneModel:
    kind = "flowstone"
    centuries_per_cm = 1

    def estimate(self, measure):
        return int(measure * self.centuries_per_cm)


def model_for(kind):
    for model in (StalactiteModel(), StalagmiteModel(), ColumnModel(), FlowstoneModel()):
        if model.kind == kind:
            return model
    raise ValueError("unknown formation type: %r" % kind)


class SurveyReport:
    def __init__(self):
        self.entries = []

    def add(self, kind, measure, age):
        self.entries.append((kind, measure, age))

    def oldest_age(self):
        if not self.entries:
            return 0
        return max(age for _kind, _measure, age in self.entries)

    def lines(self):
        for kind, measure, age in self.entries:
            yield "%-11s %7.1f cm -> %6d centuries" % (kind, measure, age)
        yield "cavern age estimate: %d centuries" % self.oldest_age()


def build_report(formations):
    report = SurveyReport()
    for text in formations:
        reading = FormationReading(text)
        model = model_for(reading.kind)
        report.add(reading.kind, reading.measure, model.estimate(reading.measure))
    return report


def survey(formations):
    return build_report(formations).oldest_age()


def main():
    notes = ["stalactite 50", "stalagmite 40", "column 18", "flowstone 120"]
    for line in build_report(notes).lines():
        print(line)


if __name__ == "__main__":
    main()

