class LacquerDisc:
    """Master disc whose groove depth sets the base audio fidelity."""

    def __init__(self, groove_depth):
        self.groove_depth = float(groove_depth)

    def fidelity_modifier(self):
        return self.groove_depth

    def visual_appeal(self):
        return 0


class StamperPlate:
    """Nickel stamper; every pressing cycle wears the grooves a little."""

    def __init__(self, wear_count, wear_factor=1.0):
        self.wear_count = int(wear_count)
        self.wear_factor = float(wear_factor)

    def fidelity_modifier(self):
        return -self.wear_count * self.wear_factor

    def visual_appeal(self):
        return 0


class VinylPellet:
    """Raw compound; colour additive introduces audible surface noise."""

    def __init__(self, color_additive_pct):
        self.color_additive_pct = float(color_additive_pct)

    def fidelity_modifier(self):
        return -self.color_additive_pct * 0.5

    def visual_appeal(self):
        return 0


class CenterLabel:
    """Paper label: inaudible, but it makes the record look finished."""

    VISUAL_BONUS = 5

    def fidelity_modifier(self):
        return 0.0

    def visual_appeal(self):
        return self.VISUAL_BONUS


class StageSpec:
    """Validated description of one production step."""

    def __init__(self, raw):
        self.kind = raw.get("type")
        self.params = {k: v for k, v in raw.items() if k != "type"}
        if self.kind not in ("lacquer", "stamper", "pellet", "label"):
            raise ValueError("unknown production stage: %r" % (self.kind,))

    def build(self):
        if self.kind == "lacquer":
            return LacquerDisc(**self.params)
        if self.kind == "stamper":
            return StamperPlate(**self.params)
        if self.kind == "pellet":
            return VinylPellet(**self.params)
        return CenterLabel(**self.params)


class QualityReport:
    """Formats the outcome of a pressing run for the shop floor."""

    def __init__(self, audio_quality, visual_appeal):
        self.audio_quality = audio_quality
        self.visual_appeal = visual_appeal

    def render(self):
        return "audio quality: %.2f%% | visual appeal: %d" % (
            self.audio_quality,
            self.visual_appeal,
        )


def press(stages):
    audio = 0.0
    visual = 0
    for raw in stages:
        spec = StageSpec(raw)
        stage = spec.build()
        audio += stage.fidelity_modifier()
        visual += stage.visual_appeal()
    return (round(min(100.0, max(0.0, audio)), 2), visual)


def main():
    line = [
        {"type": "lacquer", "groove_depth": 100},
        {"type": "stamper", "wear_count": 2},
        {"type": "pellet", "color_additive_pct": 4},
        {"type": "label"},
    ]
    quality, appeal = press(line)
    report = QualityReport(quality, appeal)
    print(report.render())
    print(press([{"type": "lacquer", "groove_depth": 100},
                 {"type": "stamper", "wear_count": 2}]))


if __name__ == "__main__":
    main()

