LIFT_COEFFICIENT = 0.0035  # kg of lift per cubic metre per degree Celsius of overheat
LIFT_MARGIN = 1.10


class EnvelopeFabric:
    def __init__(self, volume, ambient_temp, mass):
        self.volume = float(volume)
        self.ambient_temp = float(ambient_temp)
        self.mass = float(mass)

    def lift(self, internal_temp):
        overheat = max(0.0, internal_temp - self.ambient_temp)
        return self.volume * overheat * LIFT_COEFFICIENT


class BurnerUnit:
    def __init__(self, mass, max_temp):
        self.mass = float(mass)
        self.max_temp = float(max_temp)


class WickerBasket:
    def __init__(self, mass, passengers, passenger_mass=80.0):
        self.mass = float(mass)
        self.passengers = int(passengers)
        self.passenger_mass = float(passenger_mass)

    @property
    def total_mass(self):
        return self.mass + self.passengers * self.passenger_mass


class TetherRope:
    def __init__(self, length, mass_per_metre, drag):
        self.length = float(length)
        self.mass_per_metre = float(mass_per_metre)
        self.drag = float(drag)

    @property
    def total_mass(self):
        return self.length * self.mass_per_metre + self.drag


def build_part(spec):
    kind = spec["type"]
    if kind == "envelope":
        return EnvelopeFabric(spec["volume"], spec["ambient_temp"], spec["mass"])
    if kind == "burner":
        return BurnerUnit(spec["mass"], spec["max_temp"])
    if kind == "basket":
        return WickerBasket(spec["mass"], spec["passengers"], spec.get("passenger_mass", 80.0))
    if kind == "tether":
        return TetherRope(spec["length"], spec["mass_per_metre"], spec["drag"])
    raise ValueError("unknown balloon part: %r" % (kind,))


class BalloonAssembly:
    def __init__(self, parts):
        self.envelopes = [p for p in parts if isinstance(p, EnvelopeFabric)]
        self.burners = [p for p in parts if isinstance(p, BurnerUnit)]
        self.baskets = [p for p in parts if isinstance(p, WickerBasket)]
        self.tethers = [p for p in parts if isinstance(p, TetherRope)]
        if not self.envelopes:
            raise ValueError("a balloon needs at least one envelope fabric")

    @property
    def internal_temp(self):
        if not self.burners:
            return min(e.ambient_temp for e in self.envelopes)
        return max(b.max_temp for b in self.burners)

    def total_lift(self):
        return sum(e.lift(self.internal_temp) for e in self.envelopes)

    def total_weight(self):
        return (sum(e.mass for e in self.envelopes)
                + sum(b.mass for b in self.burners)
                + sum(b.total_mass for b in self.baskets)
                + sum(t.total_mass for t in self.tethers))

    def max_altitude(self):
        if not self.tethers:
            return float("inf")
        return min(t.length for t in self.tethers)

    def can_lift(self):
        return self.total_lift() >= self.total_weight() * LIFT_MARGIN


class FlightReport:
    def __init__(self, assembly):
        self.assembly = assembly

    def lines(self):
        ceiling = self.assembly.max_altitude()
        return [
            "internal temperature: %.0f C" % self.assembly.internal_temp,
            "total lift: %.1f kg" % self.assembly.total_lift(),
            "total weight: %.1f kg" % self.assembly.total_weight(),
            "ceiling: %s" % ("free flight" if ceiling == float("inf") else "%.0f m" % ceiling),
            "liftoff: %s" % self.assembly.can_lift(),
        ]


def ascend(parts):
    return BalloonAssembly([build_part(spec) for spec in parts]).can_lift()


def main():
    parts = [
        {"type": "envelope", "volume": 2400.0, "ambient_temp": 15.0, "mass": 110.0},
        {"type": "burner", "mass": 45.0, "max_temp": 105.0},
        {"type": "basket", "mass": 70.0, "passengers": 3},
        {"type": "tether", "length": 60.0, "mass_per_metre": 0.4, "drag": 12.0},
    ]
    for line in FlightReport(BalloonAssembly([build_part(s) for s in parts])).lines():
        print(line)
    print("ascend() ->", ascend(parts))


if __name__ == "__main__":
    main()

