class GearSpec:
    """A single raw gear entry normalised into a kind plus numeric parameters."""

    def __init__(self, raw):
        if isinstance(raw, dict):
            kind = raw.get("type")
            self.params = {key: value for key, value in raw.items() if key != "type"}
        else:
            kind, self.params = raw[0], dict(raw[1])
        if not kind:
            raise ValueError("every equipment entry needs a type")
        self.kind = str(kind).lower()

    def number(self, name, default=None):
        value = self.params.get(name, default)
        if value is None:
            raise ValueError("%s is missing parameter %r" % (self.kind, name))
        if not isinstance(value, (int, float)) or value < 0:
            raise ValueError("%s has a bad value for %r: %r" % (self.kind, name, value))
        return float(value)


class AirTank:
    def __init__(self, volume):
        self.volume = volume


class RegulatorValve:
    def __init__(self, surface_rate, depth):
        self.surface_rate = surface_rate
        self.depth = depth

    def flow_rate(self):
        return self.surface_rate * (1.0 + self.depth / 10.0)


class BuoyancyCompensator:
    def __init__(self, drag):
        self.drag = drag

    def multiplier(self):
        return 1.0 + self.drag


class WeightBelt:
    def __init__(self, mass):
        self.mass = mass

    def multiplier(self):
        return 1.0 + 0.01 * self.mass


class DiveProfile:
    def __init__(self, tank, regulator, compensator, belt):
        self.tank = tank
        self.regulator = regulator
        self.compensator = compensator
        self.belt = belt

    def consumption_rate(self):
        rate = self.regulator.flow_rate() * self.compensator.multiplier() * self.belt.multiplier()
        if rate <= 0:
            raise ValueError("consumption rate must be positive")
        return rate

    def bottom_time(self):
        return int(self.tank.volume // self.consumption_rate())


def dive(equipment):
    by_kind = {}
    for raw in equipment:
        spec = GearSpec(raw)
        by_kind[spec.kind] = spec
    for required in ("air_tank", "regulator"):
        if required not in by_kind:
            raise ValueError("loadout is missing the %s" % required)
    tank = AirTank(by_kind["air_tank"].number("volume"))
    reg_spec = by_kind["regulator"]
    regulator = RegulatorValve(reg_spec.number("rate"), reg_spec.number("depth", 0))
    bc_drag = by_kind["bc"].number("drag", 0) if "bc" in by_kind else 0.0
    compensator = BuoyancyCompensator(bc_drag)
    belt_mass = by_kind["weight_belt"].number("mass", 0) if "weight_belt" in by_kind else 0.0
    belt = WeightBelt(belt_mass)
    profile = DiveProfile(tank, regulator, compensator, belt)
    return profile.bottom_time()


def report(name, equipment):
    return "%s: %d minutes of bottom time" % (name, dive(equipment))


if __name__ == "__main__":
    print(report("minimal rig", [
        {"type": "air_tank", "volume": 2000},
        {"type": "regulator", "rate": 25, "depth": 10},
    ]))
    print(report("full rig", [
        {"type": "air_tank", "volume": 3000},
        {"type": "regulator", "rate": 20, "depth": 20},
        {"type": "bc", "drag": 0.15},
        {"type": "weight_belt", "mass": 6},
    ]))

