class LatheOperation:
    """A single requested pass: a tool name plus the depth of cut in millimetres."""

    def __init__(self, spec):
        name, depth = spec
        depth = float(depth)
        if depth < 0.0:
            raise ValueError("pass depth cannot be negative: %r" % (depth,))
        self.tool_name = str(name).strip().lower()
        self.depth = depth


class RoughingGouge:
    label = "roughing gouge"

    def __init__(self, depth):
        self.depth = depth

    def diameter_loss(self):
        return 2.0 * self.depth

    def finish_delta(self):
        return -8.0 * self.depth


class SpindleGouge:
    label = "spindle gouge"

    def __init__(self, depth):
        self.depth = depth

    def diameter_loss(self):
        return 1.0 * self.depth

    def finish_delta(self):
        return 5.0 * self.depth


class PartingTool:
    label = "parting tool"

    def __init__(self, depth):
        self.depth = depth

    def diameter_loss(self):
        return 1.5 * self.depth

    def finish_delta(self):
        return 0.0


class SkewChisel:
    label = "skew chisel"

    def __init__(self, depth):
        self.depth = depth

    def diameter_loss(self):
        return 0.1 * self.depth

    def finish_delta(self):
        return 25.0 * self.depth


class TurningBlank:
    def __init__(self, diameter):
        self.diameter = float(diameter)
        self.finish = 0.0

    def apply(self, tool):
        self.diameter = max(0.0, self.diameter - tool.diameter_loss())
        self.finish = min(100.0, max(0.0, self.finish + tool.finish_delta()))


class FinishReport:
    def __init__(self, diameter, finish):
        self.diameter = diameter
        self.finish = finish

    def grade(self):
        if self.finish >= 60.0:
            return "ready for wax"
        if self.finish >= 25.0:
            return "needs light sanding"
        return "needs heavy sanding"

    def lines(self):
        return ["final diameter: %.2f" % self.diameter,
                "finish score:   %.2f" % self.finish,
                "verdict:        %s" % self.grade()]


def make_tool(name, depth):
    if name == "roughing gouge":
        return RoughingGouge(depth)
    if name == "spindle gouge":
        return SpindleGouge(depth)
    if name == "parting tool":
        return PartingTool(depth)
    if name == "skew chisel":
        return SkewChisel(depth)
    raise ValueError("unknown turning tool: %r" % (name,))


def turn(operations):
    blank = TurningBlank(10.0)
    for spec in operations:
        operation = LatheOperation(spec)
        tool = make_tool(operation.tool_name, operation.depth)
        blank.apply(tool)
    return (blank.diameter, blank.finish)


