class ArmatureBar:
    def __init__(self, weight_grams):
        self.weight_grams = weight_grams

    def frequency_penalty(self):
        return self.weight_grams * 0.4


class ContactScrew:
    def __init__(self, gap_mm):
        self.gap_mm = gap_mm

    def duty_offset(self):
        return (self.gap_mm - 1.0) * 12.0


class ElectromagneticCoil:
    def __init__(self, wraps):
        self.wraps = wraps

    def frequency_gain(self):
        return self.wraps * 12.0


class TubeGrip:
    DAMPING = 0.08

    def __init__(self, material):
        self.material = material

    def damped(self, hertz):
        return hertz * (1.0 - self.DAMPING)


class MachineReport:
    def __init__(self, hertz, duty):
        self.hertz = hertz
        self.duty = duty

    def render(self):
        return "{0:.1f} Hz at {1:.1f}% duty cycle".format(self.hertz, self.duty)


def _validate(settings):
    for key in ("bar_weight", "screw_gap", "wraps"):
        if key not in settings:
            raise KeyError("missing setting: " + key)
    if settings["wraps"] <= 0:
        raise ValueError("coil must have at least one wrap")
    if settings["screw_gap"] < 0:
        raise ValueError("contact screw gap cannot be negative")


def tune(settings):
    _validate(settings)
    bar = ArmatureBar(settings["bar_weight"])
    screw = ContactScrew(settings["screw_gap"])
    coil = ElectromagneticCoil(settings["wraps"])
    grip = TubeGrip(settings.get("grip_material", "steel"))

    base = 30.0 + coil.frequency_gain() - bar.frequency_penalty()
    hertz = max(0.0, grip.damped(base))
    duty = min(100.0, max(0.0, 50.0 + screw.duty_offset()))
    return (round(hertz, 1), round(duty, 1))


def describe(settings):
    hertz, duty = tune(settings)
    report = MachineReport(hertz, duty)
    return report.render()


def main():
    liner = {"bar_weight": 20, "screw_gap": 1.0, "wraps": 10, "grip_material": "brass"}
    shader = {"bar_weight": 35, "screw_gap": 1.6, "wraps": 14}
    print("liner:", describe(liner))
    print("shader:", describe(shader))
    print("raw liner tuple:", tune(liner))


if __name__ == "__main__":
    main()

