class SpringTensionSpec:
    """Return-spring characteristics of a type bar."""

    def __init__(self, newtons, base_delay_ms=120.0):
        if newtons <= 0:
            raise ValueError("spring tension must be positive")
        self.newtons = newtons
        self.base_delay_ms = base_delay_ms

    def delay_ms(self):
        return self.base_delay_ms / self.newtons


class TypeBarLever:
    def __init__(self, tension_spec):
        self.tension_spec = tension_spec

    def return_delay(self, shifted):
        delay = self.tension_spec.delay_ms()
        return delay * 2.0 if shifted else delay


class CarriageRoller:
    def __init__(self, friction_coefficient, friction_base_ms=9.0):
        self.friction_coefficient = friction_coefficient
        self.friction_base_ms = friction_base_ms

    def friction_delay(self):
        return self.friction_base_ms * self.friction_coefficient


class RibbonSpool:
    def __init__(self, ink_per_strike, ink_remaining):
        self.ink_per_strike = ink_per_strike
        self.ink_remaining = ink_remaining

    def strike(self):
        if self.ink_remaining < self.ink_per_strike:
            raise RuntimeError("ribbon spool is out of ink")
        self.ink_remaining -= self.ink_per_strike
        return self.ink_per_strike


class ShiftKeyLever:
    def needs_shift(self, character):
        return character.isalpha() and character.isupper()


class StrokeRecord:
    def __init__(self, character, delay_ms, ink_used):
        self.character = character
        self.delay_ms = delay_ms
        self.ink_used = ink_used


class TypewriterAssembly:
    def __init__(self, type_bar, roller, spool, shift_key):
        self.type_bar = type_bar
        self.roller = roller
        self.spool = spool
        self.shift_key = shift_key

    def strike(self, character):
        if len(character) != 1:
            raise ValueError("each stroke must be a single character")
        delay = self.type_bar.return_delay(self.shift_key.needs_shift(character))
        delay += self.roller.friction_delay()
        ink = 0.0 if character.isspace() else self.spool.strike()
        return StrokeRecord(character, delay, ink)


class SpeedReport:
    def __init__(self, words_per_minute, ink_used, stroke_count):
        self.words_per_minute = words_per_minute
        self.ink_used = ink_used
        self.stroke_count = stroke_count

    def render(self):
        return "{0} strokes -> {1} wpm, {2} ml of ink".format(
            self.stroke_count, self.words_per_minute, self.ink_used)


def typewrite(strokes):
    tension = SpringTensionSpec(3.0)
    type_bar = TypeBarLever(tension)
    roller = CarriageRoller(1.4)
    spool = RibbonSpool(0.0025, 5.0)
    shift_key = ShiftKeyLever()
    machine = TypewriterAssembly(type_bar, roller, spool, shift_key)
    records = [machine.strike(character) for character in strokes]
    if not records:
        return (0.0, 0.0)
    slowest = max(record.delay_ms for record in records)
    words_per_minute = 60000.0 / (slowest * 5.0)
    total_ink = sum(record.ink_used for record in records)
    return (round(words_per_minute, 2), round(total_ink, 4))


def main():
    phrase = "The Quick Brown Fox Jumps Over 13 Lazy Dogs"
    speed, ink = typewrite(phrase)
    report = SpeedReport(speed, ink, len(phrase))
    print(report.render())


if __name__ == "__main__":
    main()

