class lye_solution:
    """A caustic solution contributing active lye mass to the batch."""

    def __init__(self, mass, concentration):
        if not 0 < concentration <= 1:
            raise ValueError("lye concentration must be a fraction in (0, 1]")
        self.mass = mass
        self.concentration = concentration

    def active_lye(self):
        return self.mass * self.concentration


class base_oil:
    """A fat or oil that neutralises lye and lengthens the cure."""

    def __init__(self, name, mass, sap_index):
        self.name = name
        self.mass = mass
        self.sap_index = sap_index

    def lye_consumed(self):
        return self.mass * self.sap_index

    def cure_days(self):
        return self.mass * 0.004 + 14.0


class fragrance_blend:
    """Scent additive; alcohol carriers accelerate saponification."""

    def __init__(self, name, mass, alcohol_content):
        self.name = name
        self.mass = mass
        self.alcohol_content = alcohol_content

    def cure_factor(self):
        if self.alcohol_content > 0:
            return 1.0 - min(0.30, self.alcohol_content * 0.5)
        return 1.0


class color_pigment:
    """Mineral colourant that soaks up a little oil and no lye."""

    def __init__(self, name, mass, absorption_ratio):
        self.name = name
        self.mass = mass
        self.absorption_ratio = absorption_ratio

    def absorbed_oil(self):
        return self.mass * self.absorption_ratio


class recipe_parser:
    """Turns recipe dictionaries into ingredient objects."""

    def build(self, spec):
        kind = spec["type"]
        if kind == "lye":
            return lye_solution(spec["mass"], spec["concentration"])
        if kind == "oil":
            return base_oil(spec["name"], spec["mass"], spec["sap_index"])
        if kind == "fragrance":
            return fragrance_blend(spec["name"], spec["mass"], spec.get("alcohol", 0.0))
        if kind == "pigment":
            return color_pigment(spec["name"], spec["mass"], spec.get("absorption", 0.0))
        raise ValueError("unknown ingredient type: %s" % kind)


class batch_summary:
    """Human readable report for a finished calculation."""

    def __init__(self, free_lye, cure_days):
        self.free_lye = free_lye
        self.cure_days = cure_days

    def describe(self):
        state = "lye heavy" if self.free_lye > 0.5 else "skin safe"
        return "free lye %.2f g (%s), cure %.1f days" % (
            self.free_lye, state, self.cure_days)


def saponify(ingredients):
    parser = recipe_parser()
    components = [parser.build(spec) for spec in ingredients]

    active_lye = sum(c.active_lye() for c in components if isinstance(c, lye_solution))
    oils = [c for c in components if isinstance(c, base_oil)]
