        if isinstance(blend, fragrance_blend):
            cure_days *= blend.cure_factor()

    return round(max(0.0, active_lye - consumed), 3), round(cure_days, 1)


def main():
    recipe = [
        {"type": "lye", "mass": 140.0, "concentration": 0.33},
