class GlassPiece:
    """Coloured glass: passes light in proportion to its transparency, adds weight."""

    def __init__(self, color_opacity, area_cm2):
        if not 0.0 <= color_opacity <= 1.0:
            raise ValueError("color_opacity must lie between 0 and 1")
        self.color_opacity = color_opacity
        self.area_cm2 = area_cm2

    def integrity(self):
        return -0.02 * self.area_cm2 * (0.5 + self.color_opacity)

    def light_transmission(self):
        return self.area_cm2 * (1.0 - self.color_opacity)


class LeadCame:
    """H-profile lead strip: stiffens the panel, lets no light through."""

    def __init__(self, profile_width_mm, length_cm):
        self.profile_width_mm = profile_width_mm
        self.length_cm = length_cm

    def integrity(self):
        return 0.35 * self.profile_width_mm * self.length_cm

    def light_transmission(self):
        return 0.0


class SolderJoint:
    """Joint between cames: a weak point proportional to the blob's surface."""

    def __init__(self, surface_area_mm2):
        self.surface_area_mm2 = surface_area_mm2

    def integrity(self):
        return -1.5 * self.surface_area_mm2

    def light_transmission(self):
        return 0.0


class ZincBorder:
    """Perimeter frame: flat structural bonus, opaque."""

    def __init__(self, perimeter_cm):
        self.perimeter_cm = perimeter_cm

    def integrity(self):
        return 120.0 + 0.4 * self.perimeter_cm

    def light_transmission(self):
        return 0.0


class PanelAssessment:
    def __init__(self, integrity, transmission):
        self.integrity = integrity
        self.transmission = transmission

    def verdict(self):
        return "sound" if self.integrity > 0 else "fragile"

    def report(self):
        return "integrity {:.1f} | light {:.1f} cm2 | {}".format(
            self.integrity, self.transmission, self.verdict())


def parse_panel(spec_lines):
    elements = []
    for line in spec_lines:
        kind, *values = line.split()
        numbers = [float(value) for value in values]
        if kind == "glass":
            elements.append(GlassPiece(numbers[0], numbers[1]))
        elif kind == "lead":
            elements.append(LeadCame(numbers[0], numbers[1]))
        elif kind == "solder":
            elements.append(SolderJoint(numbers[0]))
        elif kind == "zinc":
            elements.append(ZincBorder(numbers[0]))
        else:
            raise ValueError("unknown panel element: " + kind)
    return elements


def solder(panel):
    integrity = 0.0
    transmission = 0.0
    for element in panel:
        integrity += element.integrity()
        transmission += element.light_transmission()
    return integrity, transmission


def main():
    panel = parse_panel([
        "zinc 400",
        "lead 6 90",
        "glass 0.35 240",
        "glass 0.8 60",
        "solder 12",
        "solder 9.5",
    ])
    panel.append(LeadCame(4, 55))
    panel.append(GlassPiece(0.15, 130))
    panel.append(SolderJoint(7))
    integrity, transmission = solder(panel)
    assessment = PanelAssessment(integrity, transmission)
    print(assessment.report())


if __name__ == "__main__":
    main()

