from dataclasses import dataclass


@dataclass
class SteelBlade:
    """Tapered foil blade: mass biased towards the tip, sets raw flexibility."""
    length_cm: float
    mass_g: float

    def centroid(self, grip_length_cm):
        return 0.55 * self.length_cm

    def raw_flexibility(self):
        return min(100.0, self.length_cm ** 3 / (self.mass_g * 90.0))


@dataclass
class BellGuard:
    mass_g: float

    def centroid(self, grip_length_cm):
        return 0.0


@dataclass
class PistolGrip:
    mass_g: float
    length_cm: float

    def centroid(self, grip_length_cm):
        return -0.55 * self.length_cm


@dataclass
class PommelNut:
    mass_g: float
    thickness_cm: float

    def centroid(self, grip_length_cm):
        return -(grip_length_cm + 0.5 * self.thickness_cm)


class WeaponAssembly:
    def __init__(self, parts):
        self.parts = parts
        self.blade = self._single(SteelBlade)
        self.guard = self._single(BellGuard)
        self.grip = self._single(PistolGrip)
        self.pommel = self._single(PommelNut)

    def _single(self, part_type):
        found = [p for p in self.parts if isinstance(p, part_type)]
        if len(found) != 1:
            raise ValueError("a foil needs exactly one %s" % part_type.__name__)
        return found[0]

    def total_mass(self):
        return sum(p.mass_g for p in self.parts)

    def balance_point(self):
        grip_length = self.grip.length_cm
        moment = sum(p.mass_g * p.centroid(grip_length) for p in self.parts)
        return round(moment / self.total_mass(), 2)

    def flexibility(self):
        return round(self.blade.raw_flexibility(), 2)


class BalanceReport:
    def __init__(self, balance_point_cm, flexibility):
        self.balance_point_cm = balance_point_cm
        self.flexibility = flexibility

    def __str__(self):
        return "balance %.2f cm from guard | flexibility %.2f" % (
            self.balance_point_cm, self.flexibility)


def build_part(spec):
    kind = spec["type"]
    if kind == "blade":
        return SteelBlade(spec["length_cm"], spec["mass_g"])
    if kind == "guard":
        return BellGuard(spec["mass_g"])
    if kind == "grip":
        return PistolGrip(spec["mass_g"], spec["length_cm"])
    if kind == "pommel":
        return PommelNut(spec["mass_g"], spec["thickness_cm"])
    raise ValueError("unknown weapon part: %r" % kind)


def balance(weapon):
    assembly = WeaponAssembly([build_part(spec) for spec in weapon])
    return assembly.balance_point(), assembly.flexibility()


def main():
    foil = [
        {"type": "blade", "length_cm": 90.0, "mass_g": 130.0},
        {"type": "guard", "mass_g": 170.0},
        {"type": "grip", "mass_g": 110.0, "length_cm": 11.0},
        {"type": "pommel", "mass_g": 70.0, "thickness_cm": 2.5},
    ]
    point, flex = balance(foil)
    print(BalanceReport(point, flex))


if __name__ == "__main__":
    main()

