STAGE_HEAD, STAGE_TAPE, STAGE_SPOOL, STAGE_ROLLER = 0, 1, 2, 3


class VideoHead:
    """Determines the base read accuracy before physical tape noise is added."""

    stage = STAGE_HEAD

    def __init__(self, alignment_error, gain):
        self.alignment_error = alignment_error
        self.gain = gain

    def apply(self, state):
        accuracy = max(0.0, min(1.0, self.gain * (1.0 - self.alignment_error)))
        state.noise += 1.0 - accuracy


class MagneticTape:
    """Contributes a baseline signal noise based on its degradation age."""

    stage = STAGE_TAPE

    def __init__(self, age_years, oxide_loss):
        self.age_years = age_years
        self.oxide_loss = oxide_loss

    def apply(self, state):
        state.noise += self.age_years * 0.004 * (1.0 + self.oxide_loss)


class SupplySpool:
    """Adds drag friction that alters playback speed depending on how full it is."""

    stage = STAGE_SPOOL

    def __init__(self, fill_ratio):
        self.fill_ratio = fill_ratio

    def apply(self, state):
        drag = (1.0 - self.fill_ratio) * 0.09 + 0.01
        state.variance += drag
        state.noise += drag * 0.05


class PinchRoller:
    """Stabilizes the speed but adds a jitter artifact when the rubber is hardened."""

    stage = STAGE_ROLLER

    def __init__(self, hardened):
        self.hardened = hardened

    def apply(self, state):
        state.variance *= 0.45 if not self.hardened else 0.8
        if self.hardened:
            state.noise += 0.015


class PlaybackState:
    def __init__(self):
        self.noise = 0.0
        self.variance = 0.0


class PlaybackReport:
    def __init__(self, noise, variance):
        self.noise = noise
        self.variance = variance

    def format_lines(self):
        return "\n".join([
            "signal noise:    {:.4f}".format(self.noise),
            "speed variance:  {:.4f}".format(self.variance),
        ])


def build_part(spec):
    kind = spec["kind"]
    if kind == "video_head":
        return VideoHead(float(spec["alignment_error"]), float(spec.get("gain", 1.0)))
    if kind == "magnetic_tape":
        return MagneticTape(float(spec["age_years"]), float(spec.get("oxide_loss", 0.0)))
    if kind == "supply_spool":
        return SupplySpool(float(spec["fill_ratio"]))
    if kind == "pinch_roller":
        return PinchRoller(bool(spec.get("hardened", False)))
    raise ValueError("unknown cassette part: {!r}".format(kind))


def playback(mechanism):
    parts = sorted((build_part(spec) for spec in mechanism), key=lambda p: p.stage)
    state = PlaybackState()
    for part in parts:
        part.apply(state)
    return round(state.noise, 6), round(state.variance, 6)


def main():
    mechanism = [
        {"kind": "supply_spool", "fill_ratio": 0.3},
        {"kind": "magnetic_tape", "age_years": 22, "oxide_loss": 0.35},
        {"kind": "video_head", "alignment_error": 0.06, "gain": 0.97},
        {"kind": "pinch_roller", "hardened": True},
    ]
    noise, variance = playback(mechanism)
    report = PlaybackReport(noise, variance)
    print(report.format_lines())


if __name__ == "__main__":
    main()

