class TreadmillMachine:
    """A treadmill machine, serviced quarterly."""

    def service_interval(self):
        return 3


class RowingErgometer:
    """A rowing ergometer, serviced twice a year."""

    def service_interval(self):
        return 6


class SquatRack:
    """A squat rack, serviced once a year."""

    def service_interval(self):
        return 12


class ExerciseBike:
    """An exercise bike, serviced three times a year."""

    def service_interval(self):
        return 4


def normalize(name):
    return " ".join(str(name).strip().lower().replace("-", " ").split())


def build_machine(name):
    key = normalize(name)
    if key in ("treadmill", "treadmill machine"):
        return TreadmillMachine()
    if key in ("rowing ergometer", "rower", "ergometer"):
        return RowingErgometer()
    if key in ("squat rack", "rack"):
        return SquatRack()
    if key in ("exercise bike", "bike", "stationary bike"):
        return ExerciseBike()
    raise ValueError("unknown equipment: %r" % (name,))


class ServiceSchedule:
    """Collects machines and answers questions about their service needs."""

    def __init__(self):
        self.machines = []

    def add(self, machine):
        self.machines.append(machine)

    def intervals(self):
        return [machine.service_interval() for machine in self.machines]

    def summary(self):
        intervals = self.intervals()
        if not intervals:
            return (0, 0)
        return (max(intervals), sum(1 for months in intervals if months < 5))


class MaintenanceReport:
    """Renders the outcome of a planning run as readable text."""

    def __init__(self, inventory, longest, short_term):
        self.inventory = inventory
        self.longest = longest
        self.short_term = short_term

    def as_text(self):
        listed = ", ".join(normalize(name) for name in self.inventory) or "nothing"
        return ("Inventory: %s\nLongest service interval: %d months\n"
                "Items due within five months: %d"
                % (listed, self.longest, self.short_term))


def plan(inventory):
    schedule = ServiceSchedule()
    for name in inventory:
        schedule.add(build_machine(name))
    return schedule.summary()


def main():
    inventory = ["treadmill machine", "squat rack", "exercise bike", "rowing ergometer"]
    longest, short_term = plan(inventory)
    report = MaintenanceReport(inventory, longest, short_term)
    print(report.as_text())


