def summarize(rolls):
    order = build_order(rolls)
    counts = {}
    for roll in order:
        counts[roll.label] = counts.get(roll.label, 0) + 1
    calories = sum(roll.calories for roll in order)
    protein = sum(roll.protein for roll in order)
    return order_summary(counts, calories, protein)


def calculate(rolls):
    summary = summarize(rolls)
    return (summary.calories, summary.protein)


def main():
    order = ["california roll", "dragon roll", "Spicy Tuna Roll", "spider roll", "dragon roll"]
    for line in summarize(order).as_lines():
        print(line)
    print("Sample order:", calculate(["california roll", "dragon roll"]))


if __name__ == "__main__":
    main()

