class StrokeTally:
    """Accumulates bristle loss per brush label and overall."""

    def __init__(self):
        self.total = 0
        self.per_brush = {}

    def record(self, brush):
        self.total += brush.bristle_loss
        entry = self.per_brush.setdefault(brush.label, [0, 0])
        entry[0] += 1
        entry[1] += brush.bristle_loss


class WearReport:
    """Renders a tally as human-readable lines."""

    def __init__(self, tally):
        self.tally = tally

    def lines(self):
        rows = sorted(self.tally.per_brush.items(), key=lambda item: -item[1][1])
        body = ["%-14s %2d strokes %3d bristles" % (name, c, loss) for name, (c, loss) in rows]
        return body + ["%-14s %2s %11d bristles" % ("TOTAL", "", self.tally.total)]


def normalize(stroke):
