from collections import Counter


class PrimeLens:
    label = "prime lens"
    weight_grams = 500
    focal_length_mm = 50


class ZoomLens:
    label = "zoom lens"
    weight_grams = 900
    focal_length_mm = 200


class MacroLens:
    label = "macro lens"
    weight_grams = 600
    focal_length_mm = 100


class WideAngleLens:
    label = "wide angle lens"
    weight_grams = 400
    focal_length_mm = 24


class UnknownLensError(ValueError):
    def __init__(self, name):
        super().__init__("unsupported lens type: {!r}".format(name))
        self.name = name


class BagSummary:
    def __init__(self, lenses):
        self.total_weight = sum(lens.weight_grams for lens in lenses)
        self.max_focal_length = max((lens.focal_length_mm for lens in lenses), default=0)
        self.counts = Counter(lens.label for lens in lenses)

    def as_tuple(self):
        return self.total_weight, self.max_focal_length

    def report(self):
        lines = ["{} x {}".format(count, label) for label, count in sorted(self.counts.items())]
        lines.append("total weight: {} g".format(self.total_weight))
        lines.append("longest focal length: {} mm".format(self.max_focal_length))
        return "\n".join(lines)


def make_lens(name):
    key = " ".join(str(name).lower().split())
    if key in ("prime lens", "prime"):
        return PrimeLens()
    if key in ("zoom lens", "zoom"):
        return ZoomLens()
    if key in ("macro lens", "macro"):
        return MacroLens()
    if key in ("wide angle lens", "wide angle", "wide"):
        return WideAngleLens()
    raise UnknownLensError(name)


def build_lenses(lenses):
    return [make_lens(name) for name in lenses]


def summarize(lenses):
    return BagSummary(build_lenses(lenses))


def pack(lenses):
    return summarize(lenses).as_tuple()


def main():
    bag = ["prime lens", "macro lens"]
    print(pack(bag))
    kit = ["zoom", "Wide Angle Lens", "prime lens", "macro"]
    print(pack(kit))
    print(summarize(kit).report())
    try:
        pack(["tilt shift lens"])
    except UnknownLensError as error:
        print(error)


if __name__ == "__main__":
    main()

