    def build(self, name):
        key = " ".join(str(name).strip().lower().split())
        if key not in self.entries:
            raise UnknownLureError("unknown lure: %r" % (name,))
        return self.entries[key]()


class GradeReport:
    def __init__(self, lures, average_depth, best_rate):
        self.lures = lures
        self.average_depth = average_depth
        self.best_rate = best_rate

    def render(self):
        names = ", ".join(self.lures) if self.lures else "no lures"
        return "%s -> avg depth %.1f ft, best success %d%%" % (
