    flour_cups = 4


class BowtiePasta:
    label = "bowtie pasta"
    boil_time = 11
    flour_cups = 2


class UnknownPastaError(ValueError):
    def __init__(self, name):
        super().__init__("unknown pasta type: {!r}".format(name))
        self.name = name


class OrderSummary:
    def __init__(self, items):
        self.items = items
        self.max_time = max((item.boil_time for item in items), default=0)
        self.total_flour = sum(item.flour_cups for item in items)

    def as_tuple(self):
        return self.max_time, self.total_flour


PASTA_CLASSES = {
    "spaghetti": SpaghettiNoodles,
    "penne": PenneTubes,
    "lasagna": LasagnaSheets,
    "bowtie": BowtiePasta,
}


def make_pasta(name):
    key = name.strip().lower().split()[0] if name.strip() else ""
    pasta_class = PASTA_CLASSES.get(key)
    if pasta_class is None:
        raise UnknownPastaError(name)
    return pasta_class()


def summarize(pastas):
    return OrderSummary([make_pasta(name) for name in pastas])


def cook(pastas):
    return summarize(pastas).as_tuple()


def format_report(summary):
    lines = ["Order of {} item(s):".format(len(summary.items))]
    for item in summary.items:
        lines.append(
            "  {:<18} {:>2} min, {} cup(s) flour".format(
                item.label, item.boil_time, item.flour_cups
            )
        )
    lines.append("Boil for {} min, use {} cup(s) of flour.".format(
        summary.max_time, summary.total_flour))
    return "\n".join(lines)


def main():
    orders = [
        ["spaghetti noodles", "lasagna sheets"],
        ["penne tubes", "bowtie pasta", "penne tubes"],
        ["mystery shapes"],
    ]
    for order in orders:
        try:
            print(format_report(summarize(order)))
            print("cook({!r}) -> {}".format(order, cook(order)))
        except UnknownPastaError as error:
            print("Cannot cook: {}".format(error))


if __name__ == "__main__":
    main()

