class MattressOrder:
    """A raw entry from the delivery list, normalized to a known size."""

    def __init__(self, raw):
        text = str(raw).strip().lower()
        if text.endswith("mattress"):
            text = text[: -len("mattress")].strip()
        self.raw = raw
        self.size = text.replace("-", " ").replace("_", " ").strip()

    def build(self):
        if self.size == "twin":
            return TwinMattress()
        if self.size == "full" or self.size == "double":
            return FullMattress()
        if self.size == "queen":
            return QueenMattress()
        if self.size == "king":
            return KingMattress()
        raise ValueError("unknown mattress type: %r" % (self.raw,))


