def update_inventory(inventory, item_name, quantity):
    """Add quantity to item_name, creating the entry when it is absent."""
    if item_name in inventory:
        inventory[item_name] += quantity
    else:
        inventory[item_name] = quantity
    return inventory

class StockChange:
    def __init__(self, item_name, quantity):
        self.item_name = item_name
        self.quantity = quantity

    def apply_to(self, inventory):
        return update_inventory(inventory, self.item_name, self.quantity)

class ShipmentParser:
    """Reads "name: amount" lines into stock changes."""

    def __init__(self, separator=":"):
        self.separator = separator

    def parse(self, text):
        name, amount = text.split(self.separator, 1)
        return StockChange(name.strip(), int(amount))

    def parse_all(self, lines):
        return [self.parse(line) for line in lines]

def apply_shipment(inventory, shipment_lines):
    parser = ShipmentParser()
    for change in parser.parse_all(shipment_lines):
        inventory = change.apply_to(inventory)
    return inventory

class InventoryRecord:
    def __init__(self, item_name, quantity):
        self.item_name = item_name
        self.quantity = quantity

    def as_line(self, low):
        marker = " (low)" if low else ""
        return "{:<10} {:>4}{}".format(self.item_name, self.quantity, marker)

class LowStockRule:
    def __init__(self, threshold):
        self.threshold = threshold

    def is_low(self, record):
        return record.quantity <= self.threshold

class InventoryReport:
    def __init__(self, inventory, threshold):
        self.inventory = inventory
        self.rule = LowStockRule(threshold)

    def lines(self):
        out = []
        for name in sorted(self.inventory):
            record = InventoryRecord(name, self.inventory[name])
            out.append(record.as_line(self.rule.is_low(record)))
        return out

def render_inventory(inventory, threshold):
    report = InventoryReport(inventory, threshold)
    return report.lines()

def summarize(inventory):
    return "{} items, {} units".format(len(inventory), sum(inventory.values()))

def main():
    stock = apply_shipment({"apple": 10}, ["apple: 5", "banana: 3", "cherry: 12"])
    for line in render_inventory(stock, 4):
        print(line)
    print(summarize(stock))

if __name__ == "__main__":
    main()

