import sys


class NonNegativeInteger:
    def __init__(self, raw):
        if isinstance(raw, bool) or not isinstance(raw, int):
            raise TypeError("expected an int, got %r" % (raw,))
        if raw < 0:
            raise ValueError("expected a non-negative integer, got %d" % raw)
        self.value = raw


class DigitSequence:
    """The decimal digits of a validated number, most significant first."""

    def __init__(self, number):
        self.digits = [int(ch) for ch in str(number.value)]

    def __iter__(self):
        return iter(self.digits)


class DigitSumResult:
    def __init__(self, original, chain):
        self.original = original
        self.chain = chain
        self.total = chain[0]
        self.digital_root = chain[-1]


class ReportRow:
    def __init__(self, result):
        steps = " -> ".join(str(step) for step in result.chain)
        self.cells = (str(result.original), str(result.total), steps, str(result.digital_root))


class ReportTable:
    HEADERS = ("n", "sum", "reduction", "root")

    def __init__(self):
        self.rows = []

    def add(self, result):
        self.rows.append(ReportRow(result))

    def render(self):
        grid = [self.HEADERS] + [row.cells for row in self.rows]
        widths = [max(len(row[i]) for row in grid) for i in range(len(self.HEADERS))]
        lines = ["  ".join(t.ljust(widths[i]) for i, t in enumerate(r)).rstrip() for r in grid]
        lines.insert(1, "  ".join("-" * w for w in widths))
        return "\n".join(lines)


def sum_digits(n):
    """Return the sum of the decimal digits of the non-negative integer n."""
    checked = NonNegativeInteger(n)
    sequence = DigitSequence(checked)
    return sum(sequence)


def reduce_to_root(n):
    """Repeatedly apply sum_digits until a single digit remains."""
    chain = [sum_digits(n)]
    while chain[-1] > 9:
        chain.append(sum_digits(chain[-1]))
    return DigitSumResult(n, chain)


def main(argv):
    numbers = [int(token) for token in argv[1:]] or [123, 9, 0, 987654321]
    table = ReportTable()
    for number in numbers:
        table.add(reduce_to_root(number))
    print(table.render())


if __name__ == "__main__":
    main(sys.argv)

