class LoanTerms:
    """Validated inputs for a simple-interest calculation."""

    principal: float
    rate: InterestRate
    time: int

    def __post_init__(self) -> None:
        if self.principal < 0:
            raise ValueError("principal must not be negative")
        if self.time < 0:
            raise ValueError("time must not be negative")

    def interest_after(self, years: int) -> float:
        return self.principal * self.rate.fraction() * years

    def total_interest(self) -> float:
        return self.interest_after(self.time)


@dataclass(frozen=True)
