FEET_PER_METER = 3.28084


class LengthUnit:
    """A length unit described by how many meters one of it is worth."""

    def __init__(self, symbol, label, meters_per_unit):
        self.symbol = symbol
        self.label = label
        self.meters_per_unit = meters_per_unit

    def to_meters(self, value):
        return value * self.meters_per_unit

    def from_meters(self, meters):
        return meters / self.meters_per_unit


class UnitRegistry:
    """Looks up length units by their textual symbol."""

    def __init__(self, units):
        self._by_symbol = {unit.symbol: unit for unit in units}

    def resolve(self, symbol):
        key = str(symbol).strip().lower()
        if key not in self._by_symbol:
            known = ", ".join(sorted(self._by_symbol))
            raise ValueError("unknown unit %r (expected one of: %s)" % (symbol, known))
        return self._by_symbol[key]


REGISTRY = UnitRegistry([
    LengthUnit("m", "meters", 1.0),
    LengthUnit("ft", "feet", 1.0 / FEET_PER_METER),
])


def convert_length(value, from_unit, to_unit):
    source = REGISTRY.resolve(from_unit)
    target = REGISTRY.resolve(to_unit)
    return round(target.from_meters(source.to_meters(float(value))), 10)


class ConversionRequest:
    """A conversion asked for in the textual form "10 m -> ft"."""

    def __init__(self, text):
        body, _, to_unit = text.partition("->")
        amount, _, from_unit = body.strip().partition(" ")
        self.value = float(amount)
        self.from_unit = from_unit.strip()
        self.to_unit = to_unit.strip()


class ConversionRecord:
    """One completed conversion, ready to be displayed."""

    def __init__(self, request):
        self.value = request.value
        self.source = REGISTRY.resolve(request.from_unit)
        self.target = REGISTRY.resolve(request.to_unit)
        self.result = convert_length(self.value, request.from_unit, request.to_unit)

    def describe(self):
        return "%-12s = %.4f %s" % (
            "%g %s" % (self.value, self.source.symbol),
            self.result,
            self.target.symbol,
        )


class ConversionReport:
    """Collects conversion records and renders them as a small table."""

    def __init__(self, title):
        self.title = title
        self.records = []

    def add(self, request):
        record = ConversionRecord(request)
        self.records.append(record)
        return record

    def render(self):
        lines = [self.title, "-" * len(self.title)]
        lines.extend(record.describe() for record in self.records)
        return "\n".join(lines)


def main():
    report = ConversionReport("Length conversions")
    for line in ["10 m -> ft", "3.28084 ft -> m", "1 m -> m", "100 ft -> m"]:
        report.add(ConversionRequest(line))
    print(report.render())


if __name__ == "__main__":
    main()

