import math
import sys


class NumberToken:
    """One comma separated field of input text."""
    def __init__(self, text):
        self.text = text.strip()

    def value(self):
        try:
            return int(self.text)
        except ValueError:
            return float(self.text)


class SampleSeries:
    """A sequence of measurements that may or may not be usable."""
    def __init__(self, values):
        self.values = list(values)

    def is_usable(self):
        return bool(self.values) and all(
            isinstance(v, (int, float)) and v > 0 for v in self.values)


class LogAccumulator:
    """Accumulates natural logarithms so large products cannot overflow."""
    def __init__(self):
        self.logs = []

    def add(self, value):
        self.logs.append(math.log(value))

    def exponentiated_mean(self):
        return round(math.exp(math.fsum(self.logs) / len(self.logs)), 12)


class MeanReport:
    """Pairs a series with its geometric mean for printing."""
    def __init__(self, series, mean):
        self.series = series
        self.mean = mean

    def format_line(self):
        shown = ", ".join(repr(v) for v in self.series.values)
        if self.mean == 0.0:
            return "[%s] -> 0.0 (empty or non-positive input)" % shown
        return "[%s] -> %g" % (shown, self.mean)


class DataSetParser:
    """Converts comma separated text into numeric measurements."""
    def parse(self, text):
        values = []
        for field in text.split(","):
            token = NumberToken(field)
            if token.text:
                values.append(token.value())
        return SampleSeries(values)


def geometric_mean(numbers):
    series = SampleSeries(numbers)
    if not series.is_usable():
        return 0.0
    accumulator = LogAccumulator()
    for value in series.values:
        accumulator.add(value)
    return accumulator.exponentiated_mean()


def describe_dataset(text):
    parser = DataSetParser()
    series = parser.parse(text)
    report = MeanReport(series, geometric_mean(series.values))
    return report.format_line()


def main(argv):
    texts = argv[1:]
    if not texts:
        texts = ["1, 2, 4", "2, 8", "3", "1, -2, 4", ""]
    for text in texts:
        print(describe_dataset(text))


if __name__ == "__main__":
    main(sys.argv)

