class SortedSequence:
    """A list validated as non-decreasing, so binary search is meaningful."""

    def __init__(self, values):
        for left, right in zip(values, values[1:]):
            if left > right:
                raise ValueError("sequence is not sorted: {} > {}".format(left, right))
        self.values = list(values)


class SearchWindow:
    """The inclusive index range still under consideration."""

    def __init__(self, low, high):
        self.low = low
        self.high = high

    def is_empty(self):
        return self.low > self.high

    def midpoint(self):
        return (self.low + self.high) // 2

    def keep_upper_half(self, mid):
        self.low = mid + 1

    def keep_lower_half(self, mid):
        self.high = mid - 1


class ProbeStep:
    """One comparison made during the search."""

    def __init__(self, index, value, target):
        self.index = index
        self.value = value
        self.direction = "found" if value == target else ("right" if value < target else "left")

    def describe(self):
        return "[{}]={} -> {}".format(self.index, self.value, self.direction)


class SearchOutcome:
    def __init__(self, index, probes):
        self.index = index
        self.probes = probes

    def verdict(self):
        return "index {}".format(self.index) if self.index >= 0 else "not found"

    def path(self):
        return ", ".join(step.describe() for step in self.probes)


class ReportTable:
    def __init__(self, headers):
        self.rows = [list(headers)]

    def add_row(self, cells):
        self.rows.append([str(cell) for cell in cells])

    def render(self):
        widths = [max(len(row[i]) for row in self.rows) for i in range(len(self.rows[0]))]
        lines = []
        for row in self.rows:
            lines.append("  ".join(cell.ljust(widths[i]) for i, cell in enumerate(row)).rstrip())
        return "\n".join(lines)


def search_with_trace(sorted_list, target):
    window = SearchWindow(0, len(sorted_list) - 1)
    probes = []
    while not window.is_empty():
        mid = window.midpoint()
        step = ProbeStep(mid, sorted_list[mid], target)
        probes.append(step)
        if step.direction == "found":
            return SearchOutcome(mid, probes)
        if step.direction == "right":
            window.keep_upper_half(mid)
        else:
            window.keep_lower_half(mid)
    return SearchOutcome(-1, probes)


def binary_search(sorted_list, target):
    return search_with_trace(sorted_list, target).index


def main():
    haystack = SortedSequence([1, 2, 3, 5, 7, 9, 11, 14])
    table = ReportTable(["target", "result", "probes", "path"])
    for target in (5, 1, 14, 4, 20):
        outcome = search_with_trace(haystack.values, target)
        table.add_row([target, outcome.verdict(), len(outcome.probes), outcome.path()])
    print(table.render())


if __name__ == "__main__":
    main()

